-- format redirect link URL with all the query string parameters
function generateRedirectURL(variant, target)
	return "http://cloud.rovio.com/link/redirect/?d=".. deviceModel .."&p=abs&a=".. variant .."&v=".. gameVersionNumber .."&t=".. target .."&r=game&c=".. customerString
end

function createStartUpAssets()
	
	if deviceModel == "windows" then
		g_cameraProfileList = { deviceModel, "osx", "ipad", "iphone" }
	elseif deviceModel == "osx" then
		g_cameraProfileList = { deviceModel, "windows", "ipad", "iphone" }
	elseif deviceModel == "iphone" then
		g_cameraProfileList = { deviceModel, "osx", "ipad", "iphone" }
	elseif deviceModel == "ipad" then
		g_cameraProfileList = { deviceModel, "iphone" }
	elseif (deviceModel == "android2" and isHDVersion) or deviceModel == "android" then
		g_cameraProfileList = { deviceModel, "ipad", "iphone" }
	elseif deviceModel == "roku" then
		g_cameraProfileList = { deviceModel, "osx", "windows", "ipad", "iphone" }
	else
		g_cameraProfileList = { deviceModel, "iphone" }
	end
	
	-- Create urls
	local variant = "full"
	if isLiteVersion then
		variant = "lite"
	end
	
	if isHDVersion and not isPCProfile() then
		variant = "HD"
	end
	
	local appStoreFullType = "originalfull"
	local appStoreSeasonsFullType = "angrybirdsseasonsfull"
	
	if customerString ~= "rovio" then
		appStoreFullType = appStoreFullType .."_" .. customerString
		appStoreSeasonsFullType = appStoreSeasonsFullType .."_" .. customerString
	end
	
	if applyChinaRestictions then
		variant = variant .."_china"
	end
	
	APP_STORE_FULL_VERSION_URL = generateRedirectURL(variant, appStoreFullType)
	APP_STORE_SEASONS_FULL_VERSION_URL = generateRedirectURL(variant, appStoreSeasonsFullType)
	NEWSLETTER_URL = generateRedirectURL(variant, "newsletter")
	ANDROID_MARKET_FULL_VERSION_URL = generateRedirectURL("litebeta2", "originalfull")
	REPORT_BUG_URL = generateRedirectURL("litebeta2", "reportbug")
	ANGRY_BIRDS_TRAILER_URL = generateRedirectURL(variant, "trailer")
	OVI_STORE_URL = generateRedirectURL(variant, "full")
	--OVI_STORE_URL_S60 = "http://lr.ovi.mobi/store/10042237_AngryBirds" -- Redirect not allowed by Nokia
	ROVIO_UPDATE_URL_S60 = generateRedirectURL(variant, "checklatestfull")
	OVI_STORE_URL_S60 = generateRedirectURL("lite", "originalfull")
	OVI_STORE_MORE_GAMES_URL_S60 = generateRedirectURL(variant, "moregames")
	ROVIO_IN_OVI_STORE_URL = "http://store.ovi.com/publisher/RovioMobile/"
	LP1_IN_OVI_STORE_URL = generateRedirectURL(variant, "lp1")
	LP2_IN_OVI_STORE_URL = generateRedirectURL(variant, "lp2")
	FACEBOOK_URL = generateRedirectURL(variant, "facebook")
	TWITTER_URL = generateRedirectURL(variant, "twitterfollow")
	MIGHTY_EAGLE_TRAILER = generateRedirectURL(variant, "trailer2")
	ABPCGAME_URL = generateRedirectURL(variant, "")
	
	if applyChinaRestictions then
		ROVIO_UPDATE_URL_S60 = generateRedirectURL("full_china", "checklatestfull")
	end
	
	ABSHOP_URL = generateRedirectURL(variant, "shop")
	BING_URL = generateRedirectURL(variant, "bing")
	XMAS_GIFT_URL = generateRedirectURL(variant, "xmasgift")
	PRIVACY_POLICY_URL = generateRedirectURL(variant, "privacypolicy")
	EULA_URL = generateRedirectURL(variant, "eula")
	AB_FBCONNECT_URL = generateRedirectURL(variant, "facebooklike")
	AB_TWITTER_URL = generateRedirectURL(variant, "twitterfollow")
	BING_SEARCH_URL = "http://m.bing.com/search/search.aspx?d=&dl=&pq=&a=results&form=MB0001&MID=35067&Q="
	POSTCARD_URL = generateRedirectURL(variant, "facebookcardhalloween")
	SUMMER_VIDEO_URL = generateRedirectURL(variant, "summervideo")
	
	SHOP_NO_ADS_URL = generateRedirectURL(variant, "noads_"..customerString)
	APPLE_GIFT_PURCHASE_URL = generateRedirectURL(variant, "purchasegift")
	
	uniqueDeviceId = uniqueDeviceId or "none"
	if releaseBuild then
		ROVIO_NEWS_URL = "http://cloud.rovio.com/content/embed/pauseMenu/?d=" .. deviceModel .."&p=abs&a=".. variant .."&v=".. gameVersionNumber .."&sw=".. screenWidth .."&sh=".. screenHeight .."&i=".. uniqueDeviceId.."&c="..customerString
	else
		ROVIO_NEWS_URL = "http://smoke.rovio.com/content/embed/pauseMenu/?d=" .. deviceModel .."&p=abs&a=".. variant .."&v=".. gameVersionNumber .."&sw=".. screenWidth .."&sh=".. screenHeight .."&i=".. uniqueDeviceId.."&c="..customerString
	end
	
	QZONE_URL = generateRedirectURL(variant, "qzone")
	
	ABLIKE_URL = generateRedirectURL(variant, "ablike")
	ABCARDS_URL = generateRedirectURL(variant, "abfbcards")
	REGISTRATION_DIALOG_URL = generateRedirectURL( "free", "angrybirdsseasonsfullpc")
	
	_G.res.createTextGroupSet(localizationPath .. "/TEXTS_BASIC.dat")
	initLocales()
	
	loadFonts()
	defaultMenuFont = fontBasic
	setFont(defaultMenuFont)
	
	loadImages( { "SPLASHES" } )
	initializeSplash()
	
	-- if we want to play audio during the startup scene
	if deviceModel == "roku" then
		_G.res.createAudioOutput(2, 16, 44100)	-- 16kHz doesn't seem to supported by Roku hardware
	else
		_G.res.createAudioOutput(1, 16, 16000)
	end
	
	if isPCProfile() then
		if settings.fullScreen == nil then
			settings.fullScreen = true		
		else
			--the game already starts in full screen mode by default, so if it is in full screen, we don't make an extra call
			if settings.fullScreen == false then
				setFullScreenMode(settings.fullScreen)
				
				local t_minimumScreenWidth = 1024
				local t_minimumScreenHeight = 600						
				
				if settings.screenWidth == nil then
					settings.screenWidth = t_minimumScreenWidth
				end
				
				if settings.screenHeight == nil then
					settings.screenHeight = t_minimumScreenHeight
				end
				
				local t_width = _G.math.max(t_minimumScreenWidth, settings.screenWidth)
				local t_height = _G.math.max(t_minimumScreenHeight, settings.screenHeight)
				
				setResolution(t_width, t_height)
			end
		end
	end
	
	if deviceModel == "windows" and g_registrationEnabled == true then
		if settings.license ~= nil then
            local t_fullGameKeyIndex = getIndexInTable(settings.license.registeredKeyTypes, g_registrationKeys.fullGame)
			
			local t_deviceIdsMatch = areDeviceIDsEqual(settings.license.hardwareID, getDeviceID())
			g_isGameUnlocked = t_fullGameKeyIndex > 0 and t_deviceIdsMatch
			
			
			-- at this point, its clear the user is trying to hack the game 
			if not t_deviceIdsMatch then
            	-- local t_timeLimit = 60*30	
				-- settings.license.gamePlayTime = t_timeLimit
				-- g_isGameUnlocked = false
				settings.lastOpenLevels = {}
				settings.episodesCompleted = {}
			
			end
		else
			g_isGameUnlocked = false
		end
		
		if settings.license == nil then
			settings.license = {}
			settings.license.gamePlayTime = 0
			settings.license.registeredKeyTypes = {}
			
			settings.lastOpenLevels = {}
			settings.episodesCompleted = {}	

			settings.license.hardwareID = getDeviceID()		
			
		end
					
		
	end			
	
	settings.platform = {}
	settings.platform.device = deviceModel
	settings.platform.hardwareID = getDeviceID()	
	
	highscores.platform = {}
	highscores.platform.device = deviceModel
	highscores.platform.hardwareID = getDeviceID()
	
	if deviceModel == "windows" and g_updateCheckFlags.enabled == true then
		
		if settings.updateNotification == nil then
			settings.updateNotification = {}
			settings.updateNotification.updateNotified = false	
			settings.updateNotification.gameVersionOnLastWarning = gameVersionNumber
			
		else				
			
			--user has just updated the game, or installed another version manually (not necessarily newer)
			if settings.updateNotification.gameVersionOnLastWarning ~= gameVersionNumber then
				settings.updateNotification.updateNotified = false							
				settings.updateNotification.gameVersionOnLastWarning = gameVersionNumber				
			end
		end
	end
end

