function createAssets()

	-- uncomment for japanese
	-- _G.res.loadLocale("TEXTS_BASIC", "de_DE")
	-- _G.res.useLocale("de_DE")
	if settings.currentMainMenuTheme == nil or settings.isMoonCakeUpdate == nil then
		if isExpBranch then
			settings.currentMainMenuTheme = themes.THEME_ID_HALLOWEEN2011
			settings.currentMainMenuSong = themes.THEME_MENU_MUSIC_HALLOWEEN2011
		else
			settings.currentMainMenuTheme = themes.THEME_ID_MOONCAKE
			settings.currentMainMenuSong = themes.THEME_MENU_MUSIC_MOONCAKE
		end
		if not applyChinaRestictions and not usePCSelectionMenus() and not is3G() then
			settings.selectedEpisode = 2
			settings.selectedEpisode2 = 2
		else
			settings.selectedEpisode = 1
			settings.selectedEpisode2 = 1
		end
		settings.isMoonCakeUpdate = true
	end
	
	if useDynamicAssets then
		handleDynamicAssets(getMainMenuAssets(), true) -- don't release splash sprites just yet
	elseif deviceModel == "s60" then
		loadImages( { "INGAME", "OTHER", "OTHER_2", "ACHIEVEMENTS", "MENU", "BUTTONS", "LEVELSELECTION", "GOLDENEGGS", "TUTORIALS" } )
		loadCompoSprites( {"LEVELSELECTION_COMPOSPRITES", "TUTORIALS_COMPOSPRITES"} )
		loadCurrentThemeToMemory()
	else
		loadImages( { "INGAME", "OTHER", "OTHER_2", "ACHIEVEMENTS", "MENU", "BUTTONS", "LEVELSELECTION", "GOLDENEGGS", "TUTORIALS", "THEME_EASTER", "THEME_HALLOWEEN", "THEME_SPACE", "THEME_STPATRICK", "THEME_SUMMER", "THEME_VALENTINE", "THEME_XMAS", "THEME_MOONCAKE", "THEME_HALLOWEEN2011" } )
		loadCompoSprites( { "LEVELSELECTION_COMPOSPRITES", "TUTORIALS_COMPOSPRITES", "THEME_EASTER_COMPOSPRITES", "THEME_HALLOWEEN_COMPOSPRITES", "THEME_STPATRICK_COMPOSPRITES", "THEME_SUMMER_COMPOSPRITES", "THEME_VALENTINE_COMPOSPRITES", "THEME_XMAS_COMPOSPRITES", "THEME_MOONCAKE_COMPOSPRITES", "THEME_HALLOWEEN2011_COMPOSPRITES" } )
	end
	
	if applyChinaRestictions then
		loadImages({"CHINA"})
	end

	-- initialize sounds
	sounds.createSounds()

	-- determine butterfly particle speeds based on screen width
	-- so they don't disappear before going out of screen
	local butterflies = { "butterflyMainMenuL2R_Red",  "butterflyMainMenuR2L_Red",
						  "butterflyMainMenuL2R_Blue", "butterflyMainMenuR2L_Blue"}
	for _, v in _G.ipairs(butterflies) do
		local minVel = (screenWidth + 50) / particleTable.particles[v].lifeTime
		if _G.string.find(v, "R2L") then
			particleTable.particles[v].minVelX = -minVel -- flies from right to left
		else
			particleTable.particles[v].minVelX =  minVel -- flies from left to right
		end
		particleTable.particles[v].maxVelX = 2 * particleTable.particles[v].minVelX
	end

	if settings.audioEnabled == false then
		_G.res.stopAudioOutput()
		setEffectsVolume(0)
		setMusicVolume(0)
	else
		_G.res.startAudioOutput()
		setEffectsVolume(1)
		setMusicVolume(1)
	end
    
    loadLuaFileToObject( scriptPath .. "/menus/page.lua", this, "page" )
    loadLuaFileToObject( scriptPath .. "/menus/editorjointPage.lua", this, "editorjointPage" )
    loadLuaFileToObject( scriptPath .. "/menus/item.lua", this, "item" )
	
	if usePCSelectionMenus() or isExpBranch then
		--loadLuaFileToObject( scriptPath .. "/menus/levelSelectionManager.lua", this, "levelSelectionManager")
		loadLuaFileToObject( scriptPath .. "/menus/levelSelectionPage.lua", this, "levelSelectionPage")
        loadLuaFileToObject( scriptPath .. "/menus/MenuManager.lua", this, "menuManager")
        MenuManager = menuManager.MenuManager
	end

    Page = page.Page
    EditorJointPage = editorjointPage.EditorJointPage
    Item = item.Item
    SpriteItem = item.SpriteItem
    AnimatedSpriteItem = item.AnimatedSpriteItem
    RectItem = item.RectItem
    ButtonSpriteItem = item.ButtonSpriteItem
    TextItem = item.TextItem
	
    if usePCSelectionMenus() or isExpBranch then
		LevelSelectionItem = item.LevelSelectionItem
		ScalingButtonItem = item.ScalingButtonItem
		PCEpisodeButtonItem = item.PCEpisodeButtonItem
		--LevelSelectionManager = levelSelectionManager.LevelSelectionManager
		LevelSelectionPage = levelSelectionPage.LevelSelectionPage
        if isExpBranch then
            loadLuaFileToObject( scriptPath .. "/menus/SeasonManager.lua", this, "seasonManager")
            SeasonManager = seasonManager.SeasonManager
            loadLuaFileToObject( scriptPath .. "/menus/PC/Halloween2011Manager.lua", this, "halloween2Manager")
            Halloween2011Manager = halloween2Manager.Halloween2011Manager
        end
        loadLuaFileToObject( scriptPath .. "/menus/PC/EpisodeManager.lua", this, "epManager")
        EpisodeManager = epManager.EpisodeManager
        loadLuaFileToObject( scriptPath .. "/menus/EpisodePage.lua", this, "epPage")
        EpisodePage = epPage.EpisodePage
		loadLuaFileToObject( scriptPath .. "/menus/PC/HalloweenManager.lua", this, "halManager")
		HalloweenManager = halManager.HalloweenManager
        loadLuaFileToObject( scriptPath .. "/menus/PC/ValentineManager.lua", this, "valManager")
		ValentineManager = valManager.ValentineManager
        loadLuaFileToObject( scriptPath .. "/menus/PC/StPatrickManager.lua", this, "stPatManager")
		StPatrickManager = stPatManager.StPatrickManager
        loadLuaFileToObject( scriptPath .. "/menus/PC/EasterManager.lua", this, "eastManager")
		EasterManager = eastManager.EasterManager
		loadLuaFileToObject( scriptPath .. "/menus/PC/XmasManager.lua", this, "xmaManager")
		XmasManager = xmaManager.XmasManager
        loadLuaFileToObject( scriptPath .. "/menus/PC/SummerManager.lua", this, "sumManager")
		SummerManager = sumManager.SummerManager
        loadLuaFileToObject( scriptPath .. "/menus/PC/MooncakeManager.lua", this, "mooManager")
		MooncakeManager = mooManager.MooncakeManager
		currentLevelSelectionManager = MenuManager:new()
	end
    
    if isExpBranch and not usePCSelectionMenus() then
		ScalingButtonItem = item.ScalingButtonItem
        EpisodeSelectionItem = item.EpisodeSelectionItem
        loadLuaFileToObject( scriptPath .. "/menus/MenuManager.lua", this, "menuManager")
        MenuManager = menuManager.MenuManager
        loadLuaFileToObject( scriptPath .. "/menus/Mobile/EpisodeManager.lua", this, "epManager")
        EpisodeManager = epManager.EpisodeManager
        loadLuaFileToObject( scriptPath .. "/menus/EpisodePage.lua", this, "epPage")
        EpisodePage = epPage.EpisodePage
		currentLevelSelectionManager = MenuManager:new()
    end
	
	print("Assets created successfully!\n")
	assetsCreated = true
end

function saveLuaFileWrapper(fileName, tableName, appData)
	if isLiteVersion == true and deviceModel == "s60" then
		if tableName == "settings" then
			fileName = "settings_trial.lua"
		end
		
		if tableName == "highscores" then
			fileName = "highscores_trial.lua"
		end
	end
	
	saveLuaFile(fileName, tableName, appData)
end

