-- Mode for splash sequences

function initializeSplash()
	splashTimer = 0
	current = 1
	splashes = { 	{ sprite = "SPLASH_ROVIO", time = 2, bgColor = { red = 255, green = 255, blue = 255}},
					{ sprite = "SPLASH_ANGRY_BIRDS", time = 1, bgColor = { red = 0, green = 0, blue = 0}, startLoading = true } }
	
	if g_disableRovioSplash then
		_G.table.remove(splashes, 1)
	end
	if isKorea then
		_G.table.insert(splashes, 1, { sprite = "KOREA_IMAGE_1", time = 3, bgColor = { red = 255, green = 255, blue = 255}})
	end
	
	setBGColor(splashes[current].bgColor.red, splashes[current].bgColor.green, splashes[current].bgColor.blue)
end

function updateSplashes(dt, time)

	-- Update timer
	splashTimer = _G.assert(splashTimer) + dt
	
	if keyPressed["LBUTTON"] and splashes[current].sprite ~= "KOREA_IMAGE_1" then
		splashTimer = splashes[current].time + 1
	end

	
	local sw, sh = _G.res.getSpriteBounds("", splashes[current].sprite)
	local scale = false
	local xs, ys = 1, 1
	local xCoord, yCoord =  screenWidth / 2, screenHeight / 2
	if splashes[current].sprite == "SPLASH_ROVIO" and screenHeight * 0.8 < sh then
		scale = true
		ys = screenHeight / (sh * 1.5)
		xs = ys
		local newWidth = sw * xs
		if newWidth > screenWidth then
			ys = screenWidth / sw
			xs = screenWidth / sw
		end
	elseif splashes[current].sprite ~= "SPLASH_ROVIO" and splashes[current].sprite ~= "KOREA_IMAGE_1" and screenHeight ~= sh then
		if deviceModel ~= "ipad" then
			scale = true
			ys = screenHeight / sh
			xs = screenHeight / sh
			local newWidth = sw * xs
			if newWidth > screenWidth then
				ys = screenWidth / sw
				xs = screenWidth / sw
			end
		end
	end
			
	if scale then
		setRenderState(0, 0, xs, ys)
		_G.res.drawSprite("", splashes[current].sprite, _G.math.floor(xCoord / xs), _G.math.floor(yCoord / ys))
		if splashes[current].sprite == "SPLASH_ANGRY_BIRDS" then
			if (isBetaVersion and deviceModel == "android") or isLiteVersion then
				_G.res.drawSprite("", "LOGO_SEASONS_LITE", screenWidth / 2, screenHeight * 0.07)
			end
		end
		setRenderState(0, 0, 1, 1)
	else
		_G.res.drawSprite("", splashes[current].sprite, screenWidth/2, screenHeight/2)
		if splashes[current].sprite == "SPLASH_ANGRY_BIRDS" then
			if (isBetaVersion and deviceModel == "android") or isLiteVersion then
				_G.res.drawSprite("", "LOGO_SEASONS_LITE", screenWidth / 2, screenHeight * 0.07)
			end
		elseif splashes[current].sprite == "KOREA_IMAGE_1" then
			_G.res.drawSprite("", "KOREA_IMAGE_2", screenWidth - 30, screenHeight - 35)
		end
	end
	
	-- draw copyright notice
	if splashes[current].sprite == "SPLASH_ROVIO" then
		if screenWidth < 480 then
			local copyrightW,_ = _G.res.getSpriteBounds("COPYRIGHT_TEXT")
			setRenderState(0, 0, screenWidth/copyrightW, 1)
			_G.res.drawSprite("", "COPYRIGHT_TEXT", _G.math.floor((screenWidth / 2) / (screenWidth/copyrightW)), screenHeight)
			setRenderState(0, 0, 1, 1)
		else
			_G.res.drawSprite("", "COPYRIGHT_TEXT", screenWidth / 2, screenHeight)
		end
	end
	
	if (splashes[current].startLoading or current == #splashes) and splashTimer > dt and assetsCreated ~= true then
		if checkAdsEnabled() and deviceModel ~= "ipad" then --(isLiteVersion and deviceModel ~= "ipad" or deviceModel == "android") and not settings.isPremium then
			requestAndShowVideo("interstitial_preapp")
		elseif checkAdsEnabled() and deviceModel == "ipad" then -- used to be isLiteVersion -- only ipad has interstitials currently in iAds
			g_requestingInterstitial = true
			requestInterstitial()
		end
		createAssets()
	end
	
	-- Change sprite if showed long enough
	if splashTimer > splashes[current].time then
		splashTimer = 0
		current = current + 1
		if splashes[current] ~= nil then
			setBGColor(splashes[current].bgColor.red, splashes[current].bgColor.green, splashes[current].bgColor.blue)
		end
		if current > #splashes then
			initialize()
			
			if isPCProfile() then
				local t_minimumScreenWidth = 1024
				local t_minimumScreenHeight = 600
				
				if screenWidth < t_minimumScreenWidth or screenHeight < t_minimumScreenHeight then
					g_invalidResolutionTriggeredOnStart = true											
				end
			end
			
			setGameMode(updateMenu)
		end
	end
	
end

