function makeEditLevelPack(index, currentLevel)
	local page = {}
	
	page.name = "levelSelectionEdit" .. index
	page.theme = index
	page.back = nil
	page.font = fontBasic
	page.state = "READY"
	page.title = { text = "Theme" .. index, x = screenWidth * 0.5, y = 7, vanchor = "TOP", hanchor = "HCENTER" }
	page.items = {}	

	local linesPerPage = 3
	local itemsPerLine = 10
	local itemsPerPage = 21 --itemsPerLine * linesPerPage
	local levelNumber = currentLevel
	
	local pageLevelIndex = 0
	local currentPage = index
		
	if levelOrder.packs[currentPage] ~= nil then
		page.title.text = levelOrder.packs[currentPage]
		itemsPerPage = #levelOrder[levelOrder.packs[currentPage]]
	end	
	
	for line = 1, linesPerPage do
		local yDivider = line / (linesPerPage + 1)
		for index = 1, itemsPerLine do
			pageLevelIndex = pageLevelIndex + 1
			
			if pageLevelIndex <= itemsPerPage then
				levelNumber = levelNumber + 1
				_G.table.insert(page.items, 
					{
						boss = false,
						levelIndex = levelNumber,
						pageLevelIndex = pageLevelIndex,
						themeIndex = page.theme,
						text =  "" .. levelNumber,
						folder = levelPath .. "/pack" .. currentPage .. "/",					
						filename = "Level" .. levelNumber,
						updateFunction = updateEditor, 
						x = screenWidth / (itemsPerLine + 0.5) * index - 12,
						y = screenHeight * yDivider,
					}
				)
				
				
				if levelOrder.packs[currentPage] ~= nil then
					page.items[#page.items].filename = levelOrder[levelOrder.packs[currentPage]][pageLevelIndex]
					page.items[#page.items].folder = levelPath .. "/" .. levelOrder.packs[currentPage] .. "/"
					if isLiteVersion then
						page.items[#page.items].filename = levelOrder[levelOrder.packs[currentPage]][pageLevelIndex]
						page.items[#page.items].folder = levelPath .. "/packLite/"
					end
				end	

				if checkForLuaFile(page.items[#page.items].folder .. page.items[#page.items].filename .. ".lua") == true then
					page.items[#page.items].sprite = "LS_LEVEL_BG_NORMAL_OPEN_1"
					page.items[#page.items].sheet = "LEVELSELECTION_SHEET_1"
				end
			end
		end
	end
	
	return page, levelNumber
end

-- <GameCenter>
-- <GameCenter getters>
function getLeaderboardNameForTotalScore()
	if deviceModel ~= "ipad" then
		if isLiteVersion then
			return "totalScoreSeasonsLite"
		else -- full version
			return "totalScore"
		end
	elseif deviceModel == "ipad" then
		if isLiteVersion then
			return "totalScoreSeasonsHDLite"
		else -- full version
			return "totalScoreHD"
		end
	end
	
	return false
end

function getLeaderboardNameForEpisode(levelPack)
	local lboardName
	
	if levelPack == 1 then --xmas
		lboardName = "totalScoreXmas"
	elseif levelPack == 2 then --valentines
		lboardName = "totalScoreValentine"
	elseif levelPack == 3 then --st. patricks
		lboardName = "totalScoreStPatrick"
	elseif levelPack == 4 then --easter
		lboardName = "totalScoreEaster"
	elseif levelPack == 5 then --summer
		lboardName = "totalScoreSummer"
	elseif levelPack >= 6 and levelPack <= 7 then --mooncake
		lboardName = "totalScoreMooncake"
	elseif levelPack >= 8 and levelPack <= 10 then -- halloween 2011
		lboardName = "totalScoreHalloween2011"
	elseif levelPack >= 12 and levelPack <= 14 then -- halloween
		lboardName = "totalScoreHalloween"
	end
	
	if lboardName ~= nil and deviceModel == "ipad" then
		lboardName = lboardName .. "HD"
	end
	
	if lboardName ~= nil and isLiteVersion then
		lboardName = lboardName .. "Lite"
	end
	
	if lboardName ~= nil then
		return lboardName
	end
	print("No leaderboard name set for pack " .. levelPack .. ". Check getLeaderboardNameForEpisode -function. \n")
	return false
end

function getLeaderboardNameForWorld(levelPack)
	if isLiteVersion ~= true then
		if levelPack >= 12 and levelPack <= 14 then -- halloween
			local lboardName = "totalScoreHalloweenWorld" .. levelPack - 11
			if deviceModel == "ipad" then
				lboardName = lboardName .. "HD"
			end
			return lboardName
		else -- only halloween episode has world leaderboards currently.
			return false
		end
	end
	
	return false -- LiteVersion does not have world leaderboards.
end

function getEpisodePageIdentifier(levelPack)
	local identifier = false
	if levelPack == 1 then --xmas
		identifier = "1"
	elseif levelPack == 2 then --valentines
		identifier = "V"
	elseif levelPack == 3 then --st. patricks
		identifier = "SP"
	elseif levelPack == 4 then --easter
		identifier = "Easter"
	elseif levelPack == 5 then --summer
		identifier = "Summer"
	elseif levelPack >= 6 and levelPack <= 7 then --mooncake
		identifier = "Mooncake"
	elseif levelPack >= 12 and levelPack <= 14 then -- halloween
		identifier = "2"
	end
	if not identifier then
		print("No episodepage identifier found for levelPack " .. levelPack .. ". Check getEpisodePageIdentifier -function.\n")
	end
	return identifier
end

function getLeaderboardNamesForLevel(levelName)
	if levelOrder and levelOrder.packs then
		for i = 1, #levelOrder.packs do
			local pack = levelOrder[levelOrder.packs[i]]
			for k, v in _G.pairs(pack) do
				if v == levelName then
					local lboardNames = {}
					local lboardNameWorld = getLeaderboardNameForWorld(i)
					local lboardNameEpisode = getLeaderboardNameForEpisode(i)
					local lboardNameTotal = getLeaderboardNameForTotalScore()
					if lboardNameWorld then
						_G.table.insert(lboardNames, lboardNameWorld)
					end
					if lboardNameEpisode then
						_G.table.insert(lboardNames, lboardNameEpisode)
					end
					if lboardNameTotal then
						_G.table.insert(lboardNames, lboardNameTotal)
					end
					return lboardNames
				end
			end
		end
	end
	return false
end
-- </GameCenter getters>

function setPostedStatus(levelName)
	if gameCenterEnabled and gameCenter and gameCenter.leaderboards and leaderboards then
		local lboardNames = getLeaderboardNamesForLevel(levelName)
		if lboardNames then
			for k, v in _G.pairs(lboardNames) do
				if gameCenter.leaderboards[leaderboards[v]] then
					print("Setting posted status to false for leaderboard " .. v .. ".\n")
					gameCenter.leaderboards[leaderboards[v]].posted = false
				end
			end
		end
	end
end

function setIndicatorPositions()
	if isLiteVersion ~= true and gameCenterEnabled and gameCenter and gameCenter.leaderboards and leaderboards then
		local bg = getItemByName(getItemByName(episodeSelectionPage.items, "episodeV").children, "epVMeterBG")
		local _, bgH = _G.res.getSpriteBounds("", bg.sprite)
		if bg.x and bgH ~= 0 then
		
			for i = 1, #levelOrder.episodes do
				local packName = levelOrder.episodes[i][1] or ""
				local packNumber = 0
				if _G.string.sub(packName, 1, 4) == "pack" then -- getting pack number
					packNumber = _G.tonumber(_G.string.sub(levelOrder.episodes[i][1], 5)) or 0
				end
	
				local lboardName = getLeaderboardNameForEpisode(packNumber)
				if lboardName then
					setIndicatorPositionExt(lboardName, packNumber)
				end
			end
		end
	end
end


function enableFutureEagleGraphics()
	getItemByName(levelFailed.items, "buttonEagle").sprite = "BUTTON_FUTURE_EAGLE_BIG"
	getItemByName(levelFailed.items, "buttonEagle").updateFunction = launchFutureEagleBait
	
	getItemByName(levelFailed.items, "ingameFeatherEmpty").sprite = "LIGHTNING_VERTICAL_NOT_ACHIEVED"
