function setIndicatorPositionExt(lboardName, packNumber)
	local lboardId = leaderboards[lboardName]
	if lboardId then
		local bg = getItemByName(getItemByName(episodeSelectionPage.items, "episodeV").children, "epVMeterBG")
		local _, bgH = _G.res.getSpriteBounds("", bg.sprite)
		if gameCenter.leaderboards[lboardId] and gameCenter.leaderboards[lboardId].loading ~= true then
			local lboard = gameCenter.leaderboards[lboardId]
			if lboard.localRank and lboard.range then
				local localRank = lboard.localRank
				local range = lboard.range
				local posInMeter = 1
				if localRank > 0 then
					if range > 1 then
						posInMeter = (localRank - 1) / (range - 1)
					else -- range and rank are 1
						posInMeter = 0
					end
				end
				
				-- Link this leaderboard to correct indicator on episode selection page and position it accordingly.
				local epIdentifier = getEpisodePageIdentifier(packNumber)
				if epIdentifier then
					local episode = getItemByName(episodeSelectionPage.items, "episode" .. epIdentifier)
					if episode then
						for k, v in _G.pairs(episode.children) do
							if v.sprite and v.sprite == "GLOBAL_METER_INDICATOR" then
								v.x, v.y = bg.x, _G.math.min(bg.y - (bgH * 0.645) + ((bgH * 0.645) * posInMeter), bg.y)
								break
							end
						end
					else
						print("No global rank meter added to episode " .. epIdentifier .. "\n")
					end
				end		
			end
		end
	end
end

function disableGameCenter()
	if mainMenu and mainMenu.items and episodeSelectionPage and episodeSelectionPage.items then
		local leaderboards = getItemByName(mainMenu.items, "leaderboards")
		if leaderboards then
			leaderboards.callFunction = initGameCenter
		end
		
		local achievements = getItemByName(mainMenu.items, "achievements")
		if achievements then
			achievements.callFunction = initGameCenter
		end
			
		local ep1MeterBG = getItemByName(episodeSelectionPage.items, "ep1MeterBG")
		if ep1MeterBG then
			ep1MeterBG.visible = false
		end
		local ep1MeterIndicator = getItemByName(episodeSelectionPage.items, "ep1MeterIndicator")
		if ep1MeterIndicator then
			ep1MeterIndicator.visible = false
		end
		
		local ep2MeterBg = getItemByName(episodeSelectionPage.items, "ep2MeterBG")
		if ep2MeterBg then
			ep2MeterBg.visible = false
		end
		local ep2MeterIndicator = getItemByName(episodeSelectionPage.items, "ep2MeterIndicator")
		if ep2MeterIndicator then
			ep2MeterIndicator.visible = false
		end
		
	end
end

function enableGameCenter()
	if mainMenu and mainMenu.items and episodeSelectionPage and episodeSelectionPage.items then
		local leaderboards = getItemByName(mainMenu.items, "leaderboards")
		if leaderboards then
			leaderboards.callFunction = showLoadingLeaderboards
		end
		
		local achievements = getItemByName(mainMenu.items, "achievements")
		if achievements then
			achievements.callFunction = showLoadingAchievements
		end
			
		local ep1MeterBG = getItemByName(episodeSelectionPage.items, "ep1MeterBG")
		if ep1MeterBG then
			ep1MeterBG.visible = true
		end
		local ep1MeterIndicator = getItemByName(episodeSelectionPage.items, "ep1MeterIndicator")
		if ep1MeterIndicator then
			ep1MeterIndicator.visible = true
		end
		
		local ep2MeterBg = getItemByName(episodeSelectionPage.items, "ep2MeterBG")
		if ep2MeterBg then
			ep2MeterBg.visible = true
		end
		local ep2MeterIndicator = getItemByName(episodeSelectionPage.items, "ep2MeterIndicator")
		if ep2MeterIndicator then
			ep2MeterIndicator.visible = true
		end
	end
end

