				setGameMode(gotoAbout)
			end
		end
	end
	
	if page == gameFinished or page == gameFinishedThreeStars or
	   page == gameFinishedLPV or page == gameFinishedThreeStarsLPV or 
	   page == gameFinishedLPSP or page == gameFinishedThreeStarsLPSP or
	   page == gameFinishedLPEaster or page == gameFinishedThreeStarsLPEaster or 
	   page == gameFinishedLPSummer or page == gameFinishedThreeStarsLPSummer or 
	   page == gameFinishedLPMooncake or page == gameFinishedThreeStarsLPMooncake or 
	   page == gameFinishedLPH or page == gameFinishedThreeStarsLPH or
       page == gameFinishedLPH2 or page == gameFinishedThreeStarsLPH2 then
		page.items[1].angle = page.items[1].angle + 0.8 * dt
	end
end

function prepareTextItem(page, ci)
	if ci.text ~= nil then
		local textBoxSize = ci.textBoxSize and ci.textBoxSize or screenWidth
		local group = ci.group and ci.group or "TEXTS_BASIC"
		
		--check font
		if ci.font == nil then
			-- use default
			ci.font = defaultMenuFont
			--use page default if it exists
			if page.font ~= nil then
				ci.font = page.font
			end
		end
		setFont(ci.font)
		clipText(group, ci.text, textBoxSize)
		local fh = _G.res.getFontLeading()
		local textHeight = #clippedText.lines * fh
		ci.h = textHeight
		ci.w = clippedText.widestLine
		ci.lines = {}
		
		local k = 1
		while  k <= #clippedText.lines do
			ci.lines[k] = clippedText.lines[k]
			--print("Calculated new lines: " .. ci.lines[k] .. "\n")
			k = k + 1
		end
	end
end

function calculateTotalScoreAndStarsLite()
	local currentLevelInTable = 1
	local pageTable = levelOrder["pack1"]
	
	local totalScoreLite = 0
	local gainedStarsLite = 0
	local totalStarsLite = 0
	
	for k,v in _G.pairs(liteLevelsTable) do
		local totalScore = 0
		local gainedStars = 0
		local totalStars = 0
		totalStars = totalStars + liteLevelsTable[k].levelsNumber*3
		-- print("episode: "..k)
		for j = 1, liteLevelsTable[k].levelsNumber do
			-- print("liteLevelsTable[k].levels["..j.."]: "..liteLevelsTable[k].levels[j])
			if highscores[liteLevelsTable[k].levels[j]] ~= nil and highscores[liteLevelsTable[k].levels[j]].completed == true then
				totalScore = totalScore + highscores[liteLevelsTable[k].levels[j]].score
				if highscores[liteLevelsTable[k].levels[j]].score >= getStarLimit(liteLevelsTable[k].levels[j]).goldScore then
					gainedStars = gainedStars + 3
				elseif highscores[liteLevelsTable[k].levels[j]].score >= getStarLimit(liteLevelsTable[k].levels[j]).silverScore then
					gainedStars = gainedStars + 2
				elseif highscores[liteLevelsTable[k].levels[j]].score > 0 then
					gainedStars = gainedStars + 1
				end
			end
			currentLevelInTable = currentLevelInTable + 1
		end
		liteLevelsTable[k].totalScore, liteLevelsTable[k].totalStars, liteLevelsTable[k].stars = totalScore, totalStars, gainedStars
		totalScoreLite = totalScoreLite + totalScore
		gainedStarsLite = gainedStarsLite + gainedStars
		totalStarsLite = totalStarsLite + totalStars
		print("lite pack, sub-episode: "..liteLevelsTable[k].name.." - totalScore: "..liteLevelsTable[k].totalScore..", totalStars: "..liteLevelsTable[k].totalStars..", gainedStars: "..liteLevelsTable[k].stars.."\n")
	end
	
	return totalScoreLite, gainedStarsLite, totalStarsLite
end

function calculateTotalScoreAndStars(levelTable)

	local totalScore = 0
	local gainedStars = 0
	local totalStars = 0
	
	for k = 1, #levelTable do
		local pageTable = levelTable[k]
		totalStars = totalStars + #pageTable*3
		for i = 1, #pageTable do
		
			if highscores[pageTable[i]] ~= nil and highscores[pageTable[i]].completed == true then
				totalScore = totalScore + highscores[pageTable[i]].score
				if highscores[pageTable[i]].score >= getStarLimit(pageTable[i]).goldScore then
					gainedStars = gainedStars + 3
				elseif highscores[pageTable[i]].score >= getStarLimit(pageTable[i]).silverScore then
					gainedStars = gainedStars + 2
				elseif highscores[pageTable[i]].score > 0 then
					gainedStars = gainedStars + 1
				end
			end
			
		end
	end
	
	return totalScore, gainedStars, totalStars
end

function calculateTotalLevelsCompleted(levelTable)
	local totalLevelsCompleted = 0
	
	for k = 1, #levelTable do
		local pageTable = levelTable[k]
		for i = 1, #pageTable do
		
			if highscores[pageTable[i]] ~= nil then
				totalLevelsCompleted = totalLevelsCompleted + 1
			end
		end
	end
	return totalLevelsCompleted
end


function calculateStarsFromGoldenEggLevels()
	stars = 0
	_G.table.foreach( settings.openGoldenEggLevels, function(k,v) if v == 2 then stars = stars + 1 end end)
	return stars
end

function calculateOpenGoldenEggLevels()
	count = 0
	_G.table.foreach( settings.openGoldenEggLevels, function(k,v) count = count + 1 end)
	return count
end

-- prepare current menu page when it is set as active page
function prepareMenuPages(page)
	
	if levelSelectionEdit ~= nil and page == levelSelectionEdit[1] then
		startedFromEditor = true
	end
	
	enableMenuParticles = false
	
	if page ~= pausePage and page ~= mightyEagleDemoPage and page ~= levelComplete and page ~= levelFailed and page ~= tutorials and page ~= goldenEggAchievedPage and
			page ~= areYouSurePage and page ~= achievementPopUpPage and page ~= about and page ~= levelSelection and page ~= mainMenu then
		--print("Clearing all particles for page: " .. (page.name and page.name or "nil"))
		--print("RESET in prepareMenuPages")
		clearParticlesNative()
		
		if not isExpBranch then
			activateMainMenuFirstFrame = true
		end
	else
		--print("SKIP RESET in prepareMenuPages: " .. page.name)
	end
	
	if page.backgroundOverlay ~= nil and page ~= loadingPage then
		page.backgroundOverlay.shade = 0
	end
	
	if page == levelSelection and (usePCSelectionMenus() or isExpBranch) then
		if oldMenuPage ~= mainMenu and 
			oldMenuPage ~= episodeSelectionPage and oldMenuPage ~= levelSelection then
			_G.res.stopAllAudio()
		end
		if _G.res.isAudioPlaying(settings.currentMainMenuSong) == false then
			sounds.playAudio(settings.currentMainMenuSong, 0.8, true, 7)
		end
	end
	
	if page == levelUnavailablePopup then
		local bgBox = page.backgroundBox
		local header = getItemByName(page.items, "header")
		prepareTextItem(page, header)
		bgBox.x, bgBox.y = screenWidth / 2, screenHeight / 2
		bgBox.width, bgBox.height = header.w * 2, header.h * 4
		
		header.x, header.y = screenWidth / 2, bgBox.y - bgBox.height / 2.25
		
		local gift = getItemByName(page.items, "gift")
		gift.x, gift.y = bgBox.x + bgBox.width * 0.35, bgBox.y - bgBox.height / 2 - 40
		
		local timeLeft = getItemByName(page.items, "timeLeft")
		timeLeft.x, timeLeft.y = screenWidth / 2, screenHeight / 2
		
		local buttonYes = getItemByName(page.items, "buttonYes")
		buttonYes.x, buttonYes.y = bgBox.x + bgBox.width * 0.35, bgBox.y + bgBox.height / 1.45
	end
	
	if page == systemPopup then
		local bgBox = page.backgroundBox
		local title = getItemByName(page.items, "title")
		prepareTextItem(page, title)
		bgBox.x, bgBox.y = screenWidth / 2, screenHeight / 2
		bgBox.width, bgBox.height = title.w * 2, title.h * 4
		
		local message = getItemByName(page.items, "message")
		
		message.textBoxSize = screenWidth * 0.5
		prepareTextItem(page, message)
		
		if message.w < message.textBoxSize then
			message.textBoxSize = message.w * 1.1
		end
		
		if message.textBoxSize > 550 then
			message.textBoxSize = 550
		end
		
		bgBox.width, bgBox.height = message.textBoxSize * 1.1, (title.h * 2 + message.h) * 1.1
		
		title.x, title.y = screenWidth / 2, bgBox.y - bgBox.height / 2.25
		message.x, message.y = screenWidth / 2, title.y + title.h * 1.5 + message.h / 2
		
		local icon = getItemByName(page.items, "icon")
		if icon ~= nil then
			icon.x, icon.y = bgBox.x + bgBox.width * 0.35, bgBox.y - bgBox.height / 2 - 53
		end
		
		local buttonYes = getItemByName(page.items, "buttonYes")
		buttonYes.x, buttonYes.y = bgBox.x + bgBox.width * 0.35, bgBox.y + bgBox.height * 0.6
	end
	
	if page == loadingPage then
		local loader = getItemByName(page.items, "loader")
		local sw, sy = _G.res.getSpriteBounds("", loader.sprite)
		local loadingSprite = getItemByName(page.items, "loadingSprite")
		loadingSprite.x, loadingSprite.y = screenWidth / 2, screenHeight / 2
		loader.x, loader.y = loadingSprite.x, loadingSprite.y
		loader.cleanAngle = 0
		loader.angle = 0
		loader.rotationPivotX, loader.rotationPivotY = sw / 2, sy / 2
		getItemByName(page.items, "loadingText").y = screenHeight / 2
		loadingPage.backgroundOverlay.shade = deviceModel == "roku" and 1.0 or 0.65
	end
	
	-- page specific controls
	
	if page == mainMenu then
		if isLiteVersion then
			calculateTotalScoreAndStarsLite()
		end
		
		releaseImages( {"SPLASHES"} )
		
		mainMenu.menuButton = about
		if activateMainMenuFirstFrame then
			--print("NEW PARTICLES")
			mainMenu.firstFrame = true
			activateMainMenuFirstFrame = false
		end
		
		initializeMainMenuBats()
		
		maxDistanceToMoon = _G.math.floor(_G.math.sqrt(_G.math.pow(screenWidth / 2, 2) +  _G.math.pow(screenHeight / 2, 2)))
		
		mainMenu.state = "READY"
		
