		local smallSw, smallSh = _G.res.getSpriteBounds("", getItemByName(page.items, "facebook").sprite)
		
		local playW, playH = _G.res.getSpriteBounds("", getItemByName(page.items, "play").sprite)
		
		local play = getItemByName(page.items, "play")
		local playBG = getItemByName(page.items, "playBG")
		
		play.scale, play.xs, play.ys = true, 1, 1
		
		if settings.currentMainMenuTheme == themes.THEME_ID_HALLOWEEN then
			play.sprite = "MENU_PLAY_H"
			getItemByName(page.items, "menuLogo").sprite = "MENU_LOGO_H"
		elseif settings.currentMainMenuTheme == themes.THEME_ID_VALENTINE then
			play.sprite = "MENU_PLAY_V"
