		epMooncakeScoreBox1.width, epMooncakeScoreBox1.height = ep1ScoreBox1.width, ep1ScoreBox1.height
		epMooncakeScoreBox1.x, epMooncakeScoreBox1.y = -episodeMooncake.width / 2, episodeMooncake.height / 2 + sh2 / 6
		
		local epMooncakeScoreBox2 = getItemByName(page.items, "epMooncakeScoreBox2")
		epMooncakeScoreBox2.width, epMooncakeScoreBox2.height = ep1ScoreBox2.width, ep1ScoreBox2.height
		epMooncakeScoreBox2.x, epMooncakeScoreBox2.y = episodeMooncake.width / 2, episodeMooncake.height / 2 + sh2 / 6
		
		episodeMooncakeScore.x, episodeMooncakeScore.y = -episodeMooncake.width / 2 + epMooncakeScoreBox2.width / 2, epMooncakeScoreBox1.y
		
		local episodeMooncakeScoreText = getItemByName(page.items, "episodeMooncakeScoreText")
		episodeMooncakeScoreText.x, episodeMooncakeScoreText.y = epMooncakeScoreBox1.x + epMooncakeScoreBox1.width / 2, epMooncakeScoreBox1.y - 0.8 * epMooncakeScoreBox1.height

		local episodeMooncakeStars = getItemByName(page.items, "episodeMooncakeStars")
		episodeMooncakeStars.x, episodeMooncakeStars.y = episodeMooncake.width / 2 - epMooncakeScoreBox2.width / 2, epMooncakeScoreBox2.y
		
		local epMooncakeStarSprite = getItemByName(page.items, "epMooncakeStarSprite")
		epMooncakeStarSprite.x, epMooncakeStarSprite.y = epMooncakeScoreBox2.x - epMooncakeScoreBox2.width / 2, epMooncakeScoreBox1.y - 0.8 * epMooncakeScoreBox1.height
		
		local epMooncakeFeatherBox = getItemByName(page.items, "epMooncakeFeatherBox")
		local epMooncakeFeatherBoxW, epMooncakeFeatherBoxH = _G.res.getSpriteBounds("", epMooncakeFeatherBox.box.bottomMiddle)
		epMooncakeFeatherBox.width, epMooncakeFeatherBox.height = episodeMooncake.width * 0.4, fh * 0.65
		epMooncakeFeatherBox.x, epMooncakeFeatherBox.y = 0, episodeMooncake.height / 2 + epMooncakeFeatherBoxH / 2
		
		local epMooncakeFeatherBoxSprite = getItemByName(page.items, "epMooncakeFeatherBoxSprite")
		epMooncakeFeatherBoxSprite.x, epMooncakeFeatherBoxSprite.y = epMooncakeFeatherBox.x - epMooncakeFeatherBox.width * 0.3, epMooncakeFeatherBox.y + epMooncakeFeatherBox.height * 0.7
		
		local epMooncakeFeatherBoxSpriteW, epMooncakeFeatherBoxSpriteH = _G.res.getSpriteBounds("", epMooncakeFeatherBoxSprite.sprite)
		local epMooncakeFeatherBoxText = getItemByName(page.items, "epMooncakeFeatherBoxText")
		epMooncakeFeatherBoxText.x, epMooncakeFeatherBoxText.y = epMooncakeFeatherBoxSprite.x + 1.4 * epMooncakeFeatherBoxSpriteW, epMooncakeFeatherBoxSprite.y + epMooncakeFeatherBoxSpriteH * 0.4
		
		local feathers, maxFeathers = getEpisodeFeathers(levelOrder_packMooncake)
		epMooncakeFeatherBoxText.text = ""..feathers.."/"..maxFeathers
		
		local lock = getItemByName(getItemByName(page.items, "episodeMooncake").children, "lock")
		lock.x, lock.y = 0, 0
		
		local appStore = getItemByName(getItemByName(page.items, "episodeMooncake").children, "appStore")
		appStore.x, appStore.y = 0, 0
		
		if gameCenterSupported then
			local epMooncakeMeterBG = getItemByName(getItemByName(page.items, "episodeMooncake").children, "epMooncakeMeterBG")
			local epMooncakeMeterIndicator = getItemByName(getItemByName(page.items, "episodeMooncake").children, "epMooncakeMeterIndicator")
			local meterW, meterH = _G.res.getSpriteBounds("", epMooncakeMeterBG.sprite)
			local meterPx, meterPy = _G.res.getSpritePivot("", epMooncakeMeterBG.sprite)
			local epMooncakeBorderW, _ = _G.res.getSpriteBounds("", "EPISODEP_TOP_LEFT")
			local epMooncakeSw, _ = _G.res.getSpriteBounds("", epMooncakeMeterBG.sprite)		
			epMooncakeMeterBG.x, epMooncakeMeterBG.y = -episodeMooncake.width / 2 - (epMooncakeBorderW * 0.6) - (epMooncakeSw / 2), meterPy - meterH / 2
			
			epMooncakeMeterIndicator.x, epMooncakeMeterIndicator.y = epMooncakeMeterBG.x, epMooncakeMeterIndicator.y or epMooncakeMeterBG.y
			if gameCenterEnabled then
				epMooncakeMeterBG.visible = true
				epMooncakeMeterIndicator.visible = true
			else
				epMooncakeMeterBG.visible = false
				epMooncakeMeterIndicator.visible = false
			end
		end
		
		-- Prepare base game icon if available
		local scoreTable = {}
		scoreTable["episodeSummer"] = levelOrder_packSummer
		scoreTable["episodeEaster"] = levelOrder_packEaster
		scoreTable["episodeSP"] = levelOrder_packStPatrick
		scoreTable["episodeV"] = levelOrder_packValentine
		scoreTable["episode1"] = levelOrder_packBasic
		scoreTable["episode2"] = levelOrder_packHalloween
		scoreTable["episodeMooncake"] = levelOrder_packMooncake
		
		for key,pack in _G.pairs(scoreTable) do
			local score, gainedStars, totalStars = calculateTotalScoreAndStars(pack)
			--print("Key: ".. key .. " got following values: " .. score .. ", " .. gainedStars .. " and " .. totalStars)
			getItemByName(getItemByName(page.items, key).children, key .. "Score").text = _G.string.format("%d", score)
			getItemByName(getItemByName(page.items, key).children, key .. "Stars").text = gainedStars .. "/" .. totalStars
			getItemByName(getItemByName(page.items, key).children, key .. "ScoreText").visible = true
		end
		
		if gameCenterEnabled then
			setIndicatorPositions()
			gameCenter.safeToRefresh = true
		end
		
		-- Upsell and newsletter
		local upsell = getItemByName(page.items, "upsellABFull")
		upsell.x, upsell.y = 0, - episode1.height * 0.8
		upsell.width, upsell.height =  _G.res.getSpriteBounds("",upsell.sprite)
		
		local upsellPage, episodeIndex = getItemByName(page.items, "upsellPage")
		upsellPage.x, upsellPage.y = (episodeIndex - settings.selectedEpisode) * (screenWidth / 2) + screenWidth / 2, episode1.y + episode1.height / 2
		upsellPage.width = upsell.width
		
		local upsellShop, episodeIndex = getItemByName(page.items, "upsellShop")
		upsellShop.x, upsellShop.y = (episodeIndex - settings.selectedEpisode) * (screenWidth / 2) + screenWidth / 2, episode1.y --+ episode1.height / 2
		upsellShop.width = _G.res.getSpriteBounds("",upsellShop.sprite)
		
		if not applyChinaRestictions then
			local valentineCard, episodeIndex = getItemByName(page.items, "valentineCard")
			valentineCard.x, valentineCard.y = (episodeIndex - settings.selectedEpisode) * (screenWidth / 2) + screenWidth / 2, episode1.y --+ episode1.height / 2
			valentineCard.width = _G.res.getSpriteBounds("",valentineCard.sprite)
		end
		
		if (deviceModel == "android" and isHDVersion) then
			local giftButton = getItemByName(page.items, "giftButton")
			giftButton.sprite = "BTN_ADFREE"
			local gbW, gbH = _G.res.getSpriteBounds("", giftButton.sprite)
			giftButton.x, giftButton.y = screenWidth - gbW / 2, gbH / 2
			if isPremium then
				giftButton.visible = false
			end
		elseif deviceModel == "iphone" or deviceModel == "iphone4" or deviceModel == "ipad" then
			local giftButton = getItemByName(page.items, "giftButton")
			giftButton.sprite = "BTN_GIFT_THIS_APP"
            giftButton.sound = ""
			local gbW, gbH = _G.res.getSpriteBounds("", giftButton.sprite)
			giftButton.x, giftButton.y = screenWidth - gbW / 2, gbH / 2
		end
		
		if deviceModel ~= "iphone" and deviceModel ~= "iphone4" and deviceModel ~= "ipad" then
			ep1FeatherBox.visible, ep1FeatherBoxSprite.visible, ep1FeatherBoxText.visible = false, false, false
			ep2FeatherBox.visible, ep2FeatherBoxSprite.visible, ep2FeatherBoxText.visible = false, false, false
			epVFeatherBox.visible, epVFeatherBoxSprite.visible, epVFeatherBoxText.visible = false, false, false
			epSPFeatherBox.visible, epSPFeatherBoxSprite.visible, epSPFeatherBoxText.visible = false, false, false
			epEasterFeatherBox.visible, epEasterFeatherBoxSprite.visible, epEasterFeatherBoxText.visible = false, false, false
			epSummerFeatherBox.visible, epSummerFeatherBoxSprite.visible, epSummerFeatherBoxText.visible = false, false, false
			epMooncakeFeatherBox.visible, epMooncakeFeatherBoxSprite.visible, epMooncakeFeatherBoxText.visible = false, false, false
		end
	end
end

function prepareLevelSelectionPages(page)
		
	if page == levelSelectionPagesBasic then
		
		levelRestartedFrom = nil
		levelSelectionDragSpeed = nil
		
		
		page.bgColor = {red = page.bgColors[page.currentPage].red, green = page.bgColors[page.currentPage].green, blue =  page.bgColors[page.currentPage].blue}
		
		levelSelectionPagesPressed = false
		for i = levelSelectionPagesBasic.firstLevelIndex, #levelSelectionPagesBasic.items do
			levelSelectionPagesBasic.items[i].disableSelection = true
		end
		
		getItemByName(loadingPage.items, "loadingText").visible = false
		getItemByName(loadingPage.items, "loadingSprite").visible = true
		getItemByName(loadingPage.items, "loader").visible = true
		
		if isLiteVersion then
			getItemByName(loadingPage.items, "loadingText").visible = true
			getItemByName(loadingPage.items, "loadingSprite").visible = false
		end
		
		if not isExpBranch then settings.currentLevelSelectionPages.basic = page.currentPage end

		local ySpaceAdd = -0.08 * screenHeight
		local lsDotSpacing = 15
		local lsDotY = 10
		local textY = 0.03 * screenHeight + 12
		--local yDividerMultiplier = 1.16
		local yDividerMultiplier = 1.05
		
		local contentAreaWidth = screenWidth * 0.83
		local boxSeparatorOffsetY = 1
		
		if isLiteVersion then
			contentAreaWidth = screenWidth * 0.7
			if iAdsSupported and deviceModel ~= "ipad" then
				yDividerMultiplier = 1.2
				boxSeparatorOffsetY = 0.92
			else
				yDividerMultiplier = 1.1
			end
		end
		
		if isLiteVersion then
			local text1 = getItemByName(page.items, "text_1")
			text1.x, text1.y = screenWidth / 2 - 1.5 * lsDotSpacing, screenHeight - textY
			local text2 = getItemByName(page.items, "text_2")
			text2.x, text2.y = screenWidth / 2 - 0.5 * lsDotSpacing, screenHeight - textY
			local text3 = getItemByName(page.items, "text_3")
			text3.x, text3.y = screenWidth / 2 + 0.5 * lsDotSpacing, screenHeight - textY
			-- local text4 = getItemByName(page.items, "text_4")
			-- text4.x, text4.y = screenWidth / 2 + 1.5 * lsDotSpacing, screenHeight - textY
					
			local dot1 = getItemByName(page.items, "dot1")
			dot1.x, dot1.y = text1.x , screenHeight - lsDotY
			local dot2 = getItemByName(page.items, "dot2")
			dot2.x, dot2.y = text2.x, screenHeight - lsDotY
			local dot3 = getItemByName(page.items, "dot3")
			dot3.x, dot3.y = text3.x, screenHeight - lsDotY
			-- local dot4 = getItemByName(page.items, "dot4")
			-- dot4.x, dot4.y = text4.x, screenHeight - lsDotY

		else
			local text1 = getItemByName(page.items, "text_1")
			text1.x, text1.y = screenWidth / 2 - lsDotSpacing / 2, screenHeight - textY
			local text2 = getItemByName(page.items, "text_2")
			text2.x, text2.y = screenWidth / 2 + lsDotSpacing / 2, screenHeight - textY
					
			local dot1 = getItemByName(page.items, "dot1")
			dot1.x, dot1.y = text1.x , screenHeight - lsDotY
			local dot2 = getItemByName(page.items, "dot2")
			dot2.x, dot2.y = text2.x, screenHeight - lsDotY
		end
		
		
		local left = getItemByName(page.items, "left")
		left.x, left.y = 0, screenHeight
		local right = getItemByName(page.items, "right")
		right.x, right.y = screenWidth, screenHeight
		
		local back = getItemByName(page.items, "back")
		back.x, back.y = 0, screenHeight		
		
		local itemsPerPage = 25
		local itemsPerLine = 8
		local linesPerPage = 3
		local pages = 1
		
		if isLiteVersion then
			linesPerPage = 1
			pages = 2
			itemsPerPage = 12
			itemsPerLine = 6
		end
		
		local contentAreaStart = (screenWidth / 2) - (contentAreaWidth / 2)
		local contentItemStep = 0
		if itemsPerLine > 1 then
			contentItemStep = contentAreaWidth / (itemsPerLine-1)
		end
		
		local offset = 0
		local boxSeparatorOffset = screenWidth * 20 / 480 
		
		for k = 0, pages - 1 do
			for i = 1, itemsPerPage do
				local line = _G.math.ceil(i / itemsPerLine)
				local indexInLine = _G.math.fmod((i - 1), itemsPerLine) + 1
				local yDivider = line / (linesPerPage + 2) * yDividerMultiplier
                local index = page.firstLevelIndex - 1 + i + k * itemsPerPage
				page.items[index].text = ""..i
				if i == itemsPerPage and not isLiteVersion then
					page.items[index].x = offset + screenWidth / 2 + levelSelectionPagesBasic.currentOffset
					page.items[index].relativeX =  offset + page.items[index].x - levelSelectionPagesBasic.currentOffset
					page.items[index].y = screenHeight * yDivider * 1.02 + ySpaceAdd
					page.items[index].sprite = "LS_LEVEL_BG_NORMAL_CLOSED_X_BIG"
				else
					page.items[index].x = offset + contentAreaStart + (indexInLine - 1) * contentItemStep + levelSelectionPagesBasic.currentOffset
					page.items[index].relativeX =  offset + page.items[index].x - levelSelectionPagesBasic.currentOffset
					page.items[index].y = screenHeight * yDivider + ySpaceAdd
					
					if not isLiteVersion then
						page.items[index].sprite = "LS_LEVEL_BG_NORMAL_CLOSED_X"
					end
				end
				page.items[index].openingHatch = false
				page.items[index].scaleX = 1
				if not isLiteVersion then
					page.items[index].callFunction = openHatch
				end
				if isLiteVersion and i > 12 then
					page.items[index].x = page.items[index].x - boxSeparatorOffset
					page.items[index].relativeX = page.items[index].relativeX - boxSeparatorOffset
					page.items[index].y = screenHeight * yDivider + ySpaceAdd * 0.5
				elseif isLiteVersion and i > 9 and i <= 12 then
					page.items[index].x = page.items[index].x + boxSeparatorOffset
					page.items[index].relativeX = page.items[index].relativeX + boxSeparatorOffset
					page.items[index].y = page.items[page.firstLevelIndex + 1].y + getItemByName(page.items, "xmasLogo").spriteHeight * 2.5 * boxSeparatorOffsetY
				elseif isLiteVersion and i > 6 and i <= 9 then
					page.items[index].x = page.items[index].x - boxSeparatorOffset
					page.items[index].relativeX = page.items[index].relativeX - boxSeparatorOffset
					page.items[index].y = page.items[page.firstLevelIndex + 1].y + getItemByName(page.items, "xmasLogo").spriteHeight * 2.5 * boxSeparatorOffsetY
				elseif isLiteVersion and i > 3 and i <= 6 then
					page.items[index].x = page.items[index].x + boxSeparatorOffset
					page.items[index].relativeX = page.items[index].relativeX + boxSeparatorOffset
					page.items[index].y = screenHeight * yDivider + ySpaceAdd * 0.5
				elseif isLiteVersion and i <= 3 then
					page.items[index].x = page.items[index].x - boxSeparatorOffset
					page.items[index].relativeX = page.items[index].relativeX - boxSeparatorOffset
					page.items[index].y = screenHeight * yDivider + ySpaceAdd * 0.5
				end		
			end
			
			offset = offset + screenWidth / 2
		end
		
		if isLiteVersion then 
			for i = 1, #page.items do
				if page.items[i].levelIndex ~= nil and page.items[i].name == nil then
					themeIndex = _G.math.ceil(page.items[i].levelIndex / 3)
					if themeIndex == 1 then
						if settings.lastOpenLevelLite["xmas"] >= page.items[i].levelIndex or highscores[page.items[i].filename] ~= nil 
						  or page.items[i - 1] and page.items[i - 1].filename and highscores[page.items[i - 1].filename] and highscores[page.items[i - 1].filename].completed then
							page.items[i].sprite = "LS_LITE_LVL_BUTTON_XMAS"
							page.items[i].selectable = true
							page.items[i].text = "" .. page.items[i].pageLevelIndex
						else
							page.items[i].sprite = "LS_LEVEL_BG_NORMAL_CLOSED"
							page.items[i].selectable = false
							page.items[i].text = nil
						end
					elseif themeIndex == 2 then
						if settings.lastOpenLevelLite["halloween"] >= page.items[i].levelIndex - 3 or highscores[page.items[i].filename] ~= nil 
						  or page.items[i - 1] and page.items[i - 1].filename and highscores[page.items[i - 1].filename] and highscores[page.items[i - 1].filename].completed then
							page.items[i].sprite = "LS_LITE_LVL_BUTTON_HALLOWEEN"
							page.items[i].selectable = true
							page.items[i].text = "" .. page.items[i].pageLevelIndex - 3
						else
							page.items[i].sprite = "LS_LEVEL_BG_NORMAL_CLOSED"
							page.items[i].selectable = false
							page.items[i].text = nil
						end
					elseif themeIndex == 3 then
						if settings.lastOpenLevelLite["valentine"] >= page.items[i].levelIndex - 6 or highscores[page.items[i].filename] ~= nil 
						  or page.items[i - 1] and page.items[i - 1].filename and highscores[page.items[i - 1].filename] and highscores[page.items[i - 1].filename].completed then
							page.items[i].sprite = "LS_LITE_LVL_BUTTON_VALENTINES"
							page.items[i].selectable = true
							page.items[i].text = "" .. page.items[i].pageLevelIndex - 6
						else
							page.items[i].sprite = "LS_LEVEL_BG_NORMAL_CLOSED"
							page.items[i].selectable = false
							page.items[i].text = nil
						end
					elseif themeIndex == 4 then
						if settings.lastOpenLevelLite["stPatrick"] >= page.items[i].levelIndex - 9 or highscores[page.items[i].filename] ~= nil 
						  or page.items[i - 1] and page.items[i - 1].filename and highscores[page.items[i - 1].filename] and highscores[page.items[i - 1].filename].completed then
							page.items[i].sprite = "LS_LITE_LVL_BUTTON_PATRICK"
							page.items[i].selectable = true
							page.items[i].text = "" .. page.items[i].pageLevelIndex - 9
						else
							page.items[i].sprite = "LS_LEVEL_BG_NORMAL_CLOSED"
							page.items[i].selectable = false
							page.items[i].text = nil
						end
					elseif themeIndex == 5 then
						if settings.lastOpenLevelLite["easter"] >= page.items[i].levelIndex - 12 or highscores[page.items[i].filename] ~= nil 
						  or page.items[i - 1] and page.items[i - 1].filename and highscores[page.items[i - 1].filename] and highscores[page.items[i - 1].filename].completed then
							page.items[i].sprite = "LS_LITE_LVL_BUTTON_EASTER"
							page.items[i].selectable = true
							page.items[i].text = "" .. page.items[i].pageLevelIndex - 12
						else
							page.items[i].sprite = "LS_LEVEL_BG_NORMAL_CLOSED"
							page.items[i].selectable = false
							page.items[i].text = nil
						end
                    elseif themeIndex == 6 then
                        if settings.lastOpenLevelLite["summer"] >= page.items[i].levelIndex - 15 or highscores[page.items[i].filename] ~= nil 
						  or page.items[i - 1] and page.items[i - 1].filename and highscores[page.items[i - 1].filename] and highscores[page.items[i - 1].filename].completed then
							page.items[i].sprite = "LS_LITE_LVL_BUTTON_SUMMER"
							page.items[i].selectable = true
							page.items[i].text = "" .. page.items[i].pageLevelIndex - 15
						else
							page.items[i].sprite = "LS_LEVEL_BG_NORMAL_CLOSED"
							page.items[i].selectable = false
							page.items[i].text = nil
						end
					elseif themeIndex == 7 then
						if settings.lastOpenLevelLite["mooncake"] >= page.items[i].levelIndex - 12 or highscores[page.items[i].filename] ~= nil 
						  or page.items[i - 1] and page.items[i - 1].filename and highscores[page.items[i - 1].filename] and highscores[page.items[i - 1].filename].completed then
							page.items[i].sprite = "LS_LITE_LVL_BUTTON_MOONCAKE"
							page.items[i].selectable = true
							page.items[i].text = "" .. page.items[i].pageLevelIndex - 18
						else
							page.items[i].sprite = "LS_LEVEL_BG_NORMAL_CLOSED"
							page.items[i].selectable = false
							page.items[i].text = nil
						end
					end
				end
			end
		end
		
		
		if not isLiteVersion then
			local presentItem = getItemByName(page.items, "presentItem")
			presentItem.x = screenWidth * 1.5
			presentItem.relativeX = screenWidth * 1.5
			presentItem.y = screenHeight / 2.25
			presentItem.text = nil
			
			local goldenEgg = getItemByName(page.items, "goldenEgg")
			local goldenEggW, goldenEggH = _G.res.getSpriteBounds("", goldenEgg.sprite)
			goldenEgg.x = screenWidth * 1.9
			goldenEgg.relativeX = screenWidth * 1.9
			goldenEgg.y = screenHeight * 0.65
			goldenEgg.text = nil
			
			local goldenEggStar = getItemByName(page.items, "goldenEggStar")
			goldenEggStar.x = goldenEgg.x
			goldenEggStar.relativeX = goldenEgg.relativeX
			goldenEggStar.y = goldenEgg.y
			goldenEggStar.text = nil
			
			local xmasPresent = getItemByName(page.items, "xmasPresent")
			local xmasPresentW, xmasPresentH = _G.res.getSpriteBounds("", xmasPresent.sprite)
			xmasPresent.x = screenWidth * 1.15
			xmasPresent.relativeX = screenWidth * 1.15
			xmasPresent.y = screenHeight * 0.65 - (xmasPresentH - goldenEggH)
			xmasPresent.text = nil
			
			if settings.openGoldenEggLevels["Level16"] ~= nil then
				goldenEgg.visible = true
				goldenEgg.sprite = "GOLDEN_EGG_2"
				if settings.openGoldenEggLevels["Level16"] == 2 then
					goldenEggStar.visible = true
				end
			end
			
			if settings.openGoldenEggLevels["Level17"] ~= nil then
				presentItem.sprite = "LS_GIFT_OPEN"
				presentItem.updateFunction = updateGame
			else
				presentItem.sprite = "LS_GIFT_CLOSED"
				presentItem.updateFunction = nil
			end
			
			if settings.gameCompleted == true then
				xmasPresent.visible = true
			end
			
			local bingButton = getItemByName(page.items, "bingButton")
			bingButton.x, bingButton.y, bingButton.relativeX  = 0, (presentItem.y + screenHeight) / 1.85, screenWidth * 1.5
			
			if not bingIsEnabled then
				bingButton.visible = false
			end
		end
		
		if isLiteVersion then
			local xmasLogo = getItemByName(page.items, "xmasLogo")
			xmasLogo.x = page.items[page.firstLevelIndex + 1].x
			xmasLogo.relativeX = page.items[page.firstLevelIndex + 1].relativeX
			xmasLogo.y = page.items[page.firstLevelIndex + 1].y - xmasLogo.spriteHeight
			xmasLogo.text = nil
			
