						page.items[i].selectable = true
						
						if not settings.openGoldenEggLevels["Level39"] then
							settings.openGoldenEggLevels["Level39"] = 1
						end
						
						if settings.openGoldenEggLevels["Level39"] == 2 then
							getItemByName(page.items, "mooncakeStar").visible = true
						end
						
					else
						page.items[i].selectable = false
					end
				elseif page.items[i].name then
					-- ignore
				else
					themeIndex = _G.math.ceil(page.items[i].levelIndex / page.levelsPerPage)
					-- when the registration is enabled, we only rely on data saved on settings, otherwise, copying the highscores from someone else would unlock those levels
					local t_highScoresUnlockLevels = (g_registrationEnabled == false and highscores[page.items[i].filename] ~= nil)
					
					if settings.lastOpenLevelLPMooncake >= page.items[i].levelIndex or t_highScoresUnlockLevels then
						page.items[i].text = "" .. page.items[i].pageLevelIndex
						if themeIndex == 1 then
							page.items[i].sprite = "LS_LEVEL_BG_NORMAL_OPEN_8" 
						elseif themeIndex == 2 then
							page.items[i].sprite = "LS_LEVEL_BG_NORMAL_OPEN_8" 
						elseif themeIndex == 3 then
							page.items[i].sprite = "LS_LEVEL_BG_NORMAL_OPEN_8"
						end
						page.items[i].selectable = true
					else
						page.items[i].text = nil
						page.items[i].sprite = "LS_LEVEL_BG_NORMAL_CLOSED"
						page.items[i].selectable = false
					end
				end
			end
		end
		if levelSelectionScrollStartTimer == nil or levelSelectionScrollStartTimer <= 0 then
			getItemByName(page.items, "text_1").visible = page.currentPage == 1
			getItemByName(page.items, "text_2").visible = page.currentPage == 2
			getItemByName(page.items, "text_3").visible = page.currentPage == 3
			getItemByName(page.items, "text_4").visible = page.currentPage == 4
	
			local dot1, dot1Index = getItemByName(page.items, "dot1") 
			dot1.sprite = "LS_DOT_BLACK"
			getItemByName(page.items, "dot2").sprite = "LS_DOT_BLACK"
			page.items[dot1Index - 1 + page.currentPage].sprite = "LS_DOT_WHITE"
			getItemByName(page.items, "dot1").visible = true
			getItemByName(page.items, "dot2").visible = true
			getItemByName(page.items, "dot3").visible = true
			getItemByName(page.items, "dot4").visible = true
			
			if applyChinaRestictions then
				getItemByName(page.items, "dot3").visible = false
			end
			
			currentWorldInEpisode = page.currentPage
		end
		
		if oldMenuPage ~= mainMenu and 
			oldMenuPage ~= episodeSelectionPage and oldMenuPage ~= levelSelectionPagesBasic and oldMenuPage ~= levelSelectionPagesPackEaster
			and oldMenuPage ~= levelSelectionPagesPackV and oldMenuPage ~= levelSelectionPagesPackH and oldMenuPage ~= levelSelectionPagesPackSP
			and oldMenuPage ~= levelSelectionPagesPackSummer and oldMenuPage ~= levelSelectionPagesPackMooncake then
			_G.res.stopAllAudio()
		end
		if _G.res.isAudioPlaying(settings.currentMainMenuSong) == false then
			sounds.playAudio(settings.currentMainMenuSong, 0.8, true, 7)
		end
		page.currentOffset = page.targetOffset
	end
    if isExpBranch or usePCSelectionMenus() then
        currentWorldInEpisode = 1
    end
	
	--prepare levelselectionpages for faster drawing
	if page == levelSelectionPagesPackH or page == levelSelectionPagesBasic or page == levelSelectionPagesPackV or page == levelSelectionPagesPackSP 
		or page == levelSelectionPagesPackEaster or page == levelSelectionPagesPackSummer or page == levelSelectionPagesPackMooncake then
		
		levelSelectionButtonIndeces = {}
		for k, v in _G.pairs(page.items) do
			if v.filename then
				local eagle = false
				for k2, v2 in _G.pairs(settings.eaglesUsedIn) do
					if v2.world == v.worldNumber and v2.level == v.pageLevelIndex then
						eagle = true
					end
				end
				_G.table.insert(levelSelectionButtonIndeces, {index = k, stars = 0, eagleUsed = eagle })
			end
		end
				
		for i = 1, #levelSelectionButtonIndeces do
			local ci = page.items[levelSelectionButtonIndeces[i].index]
			--local isLevelOnDevice = checkForLuaFile(ci.folder .. ci.filename .. ".lua")
			if isLiteVersion ~= true and page.isChristmas then
				if i < 25 then
					levelSelectionButtonIndeces[i].starSprite = "LS_LEVEL_STAR_BG_X"
					--levelSelectionButtonIndeces[i].starSprite = "LS_LEVEL_STAR_BG_X_BIG"
				elseif i == 25 then
					levelSelectionButtonIndeces[i].starSprite = "LS_LEVEL_STAR_BG_X_BIG"
				end
			end
			if isLiteVersion ~= true and page.isSummer and ((i <= todayDateDay) or i <= settings.summerLatestLevelAvailable ) and ci.levelIndex <= 33 and not ci.isExtraWorld and ci.sprite ~= "LS_LEVEL_BG_NORMAL_CLOSED" then
				levelSelectionButtonIndeces[i].starSprite = "LS_SUMMER_STAR_BG"
			end
			if highscores[ci.filename] ~= nil and (ci.name == nil or _G.string.sub(ci.name, 0, 10) == "extraLevel") then
				if highscores[ci.filename].score > 0 then
					if page.isChristmas then
						if ci.levelIndex == 25 then
							levelSelectionButtonIndeces[i].starSprite = "LS_STARS_BIG_X_1"
						else
							levelSelectionButtonIndeces[i].starSprite = "LS_STARS_X_1"
						end
					elseif page.isSummer then
						levelSelectionButtonIndeces[i].starSprite = "LS_STARS_X_1"
					else
						levelSelectionButtonIndeces[i].starSprite = "LS_STARS_1"
					end
				end
	
				if getStarLimit(ci.filename) ~= nil and (ci.name == nil or _G.string.sub(ci.name, 0, 10) == "extraLevel") then
					if highscores[ci.filename].score >= getStarLimit(ci.filename).silverScore then
						if page.isChristmas then
							if ci.levelIndex == 25 then
								levelSelectionButtonIndeces[i].starSprite = "LS_STARS_BIG_X_2"
							else
								levelSelectionButtonIndeces[i].starSprite = "LS_STARS_X_2"
							end
						elseif page.isSummer then
							levelSelectionButtonIndeces[i].starSprite = "LS_STARS_X_2"
						else
							levelSelectionButtonIndeces[i].starSprite = "LS_STARS_2"
						end
					end
					if highscores[ci.filename].score >= getStarLimit(ci.filename).goldScore then
						if page.isChristmas then
							if ci.levelIndex == 25 then
								levelSelectionButtonIndeces[i].starSprite = "LS_STARS_BIG_X_3"
							else
								levelSelectionButtonIndeces[i].starSprite = "LS_STARS_X_3"
							end
						elseif page.isSummer then
							levelSelectionButtonIndeces[i].starSprite = "LS_STARS_X_3"
						else
							levelSelectionButtonIndeces[i].starSprite = "LS_STARS_3"
						end
					end
					if(settings.mightyEagleEnabled == true or g_futureEagleEnabled == true) and highscores[ci.filename].eagleScore ~= nil and 
					    highscores[ci.filename].eagleScore >= 100 then
						levelSelectionButtonIndeces[i].featherSprite = "LS_EAGLE_FEATHER"
					else
						levelSelectionButtonIndeces[i].featherSprite = nil
					end
				end
			end
		end
	end

		-- page specific controls end
end

function prepareCutScene(page, backgroundWidth, backgroundHeight, tuneTimer)
	if screenHeight < backgroundHeight then
		page.scale = true
		page.ys = screenHeight / backgroundHeight 
		page.xs = screenHeight / backgroundHeight
		page.offsetY = 0
		local newWidth = backgroundWidth * page.xs
		if newWidth < screenWidth then
			page.offsetX = (screenWidth - newWidth) / 2
		end
	elseif backgroundWidth  < screenWidth then
		page.scale = true
		page.xs = screenWidth / backgroundWidth
		page.ys = screenWidth / backgroundWidth
		page.offsetY = (screenHeight - backgroundHeight * page.ys) / 2
		local newHeight = backgroundHeight * page.ys
		if screenHeight < newHeight then
			page.xs = screenHeight / backgroundHeight
			page.ys = screenHeight / backgroundHeight
			page.offsetY = 0
			local newWidth = backgroundWidth * page.xs
			page.offsetX = (screenWidth - newWidth) / 2
		end
	end
	
	if backgroundWidth * page.xs <= screenWidth then
		page.dontScroll = true
	else
		page.scrollSpeed = -(screenWidth - backgroundWidth * page.xs) / tuneTimer
	end	
end

function handleGameModeChange(page, selectedMenuItem)	
	-- game specific
	if page.items[selectedMenuItem].levelIndex then
		print("Level index: " .. page.items[selectedMenuItem].levelIndex .. "\n")
		-- print(""..selectedMenuItem - levelSelectionPagesPackV.firstLevelIndex + 1)
		
		if levelSelectionPages == levelSelection then
			if currentGameMode == updateGame or currentGameMode == updatePictureLevel or currentGameMode == updateSoundboard then
				if settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] == 0 then
					settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] = 1
				end
			end
		end
		
		if levelSelectionPages == levelSelectionPagesPackMooncake then
			if currentGameMode == updateGame or currentGameMode == updatePictureLevel or currentGameMode == updateSoundboard then
				if settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] == 0 then
					settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] = 1
				end
			end
		end

		if levelSelectionPages == levelSelectionPagesPackSummer then
			if currentGameMode == updateGame or currentGameMode == updatePictureLevel or currentGameMode == updateSoundboard then
				if settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] == 0 then
					settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] = 1
				end
			end
		end
		
		if levelSelectionPages == levelSelectionPagesPackEaster then
			if currentGameMode == updateGame or currentGameMode == updatePictureLevel or currentGameMode == updateSoundboard then
				if settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] == 0 then
					settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] = 1
				end
			end
		end
		
		if levelSelectionPages == levelSelectionPagesPackSP then
			if currentGameMode == updateGame or currentGameMode == updatePictureLevel or currentGameMode == updateSoundboard then
				if settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] == 0 then
					settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] = 1
				end
			end
		end
		
		if levelSelectionPages == levelSelectionPagesPackV then
			if currentGameMode == updateGame or currentGameMode == updatePictureLevel or currentGameMode == updateSoundboard then
				if settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] == 0 then
					settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] = 1
				end
			end
		end
		
		if levelSelectionPages == levelSelectionPagesPackH then
			if currentGameMode == updateGame or currentGameMode == updatePictureLevel or currentGameMode == updateSoundboard then
				if settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] == 0 then
					settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] = 1
				end
			end
		end
		
		if levelSelectionPages == levelSelectionPagesBasic then
			if currentGameMode == updateGame or currentGameMode == updatePictureLevel or currentGameMode == updateSoundboard then
				if settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] == 0 then
					settings.openGoldenEggLevels["Level" .. page.items[selectedMenuItem].levelIndex] = 1
				end
			end
		end
	end
	
	if currentGameMode == updateGame then		
		currentLevelNumberInTheme = page.items[selectedMenuItem].pageLevelIndex or currentLevelNumberInTheme
		currentWorldNumber = page.items[selectedMenuItem].worldNumber or currentWorldNumber
		
		if page.items[selectedMenuItem].restartLevel == nil then
			inExtraWorld = page.items[selectedMenuItem].isExtraWorld or false
			levelRestarted = false
		else
			levelRestarted = true
		end
		
		if inExtraWorld then -- if we're starting an extra level

			if page.items[selectedMenuItem].restartLevel == nil then
				levelName = page.items[selectedMenuItem].filename
				levelFolder = page.items[selectedMenuItem].folder
				levelIndex = page.items[selectedMenuItem].levelIndex
				if levelIndex < 10 then
					levelIndex = "0"..levelIndex
				else
					levelIndex = ""..levelIndex
				end
				numberOfAttemptsInLevel = 1
				--print("FlurryEventWithParam: Golden egg level started, param: Level, paramValue: " .. goldenEggLevelMapping["Level" .. currentLevelNumberInTheme] .. "\n")
				if currentLevelNumberInTheme == 37 and not settings.samsungGEStartedFirstTime then
					settings.samsungGEStartedFirstTime = true
					logFlurryEvent("Samsung space golden egg started first time")
				end
				logFlurryEventWithParam("Golden egg level started", "Level", "" .. goldenEggLevelMapping["Level" .. currentLevelNumberInTheme]) 
			else
				-- level restarted
				settings.gameRestarted = settings.gameRestarted + 1
				--print("FlurryEventWithParam: Golden egg level restarted, Level, " .. goldenEggLevelMapping["Level" .. currentLevelNumberInTheme] .. "\n")
				logFlurryEventWithParam("Golden egg level restarted", "Level", "" .. goldenEggLevelMapping["Level" .. currentLevelNumberInTheme]) 
				numberOfAttemptsInLevel = numberOfAttemptsInLevel + 1
			end
			currentThemeNumber = 1
		else
			if page.items[selectedMenuItem].restartLevel == nil then
				levelName = page.items[selectedMenuItem].filename
				levelFolder = page.items[selectedMenuItem].folder
				levelIndex =  page.items[selectedMenuItem].levelIndex
				if levelIndex < 10 then
					levelIndex = "0"..levelIndex
				else
					levelIndex = ""..levelIndex
				end
				
				numberOfAttemptsInLevel = 1
				levelRestartedFlurryParams = {}
				levelRestartedFlurryParams["Level"] = currentWorldNumber .. "-" .. currentLevelNumberInTheme
				levelRestartedFlurryParams["From"] = "levelselection menu"
				logFlurryEventWithParams("Level started", "levelRestartedFlurryParams") 
				--print("FlurryEventWithParam: Level started, Level, " .. currentWorldNumber .. "-" ..currentLevelNumberInTheme .. "\n")
			else
				-- level restarted
				settings.gameRestarted = settings.gameRestarted + 1
				
				levelRestartedFlurryParams = {}
				levelRestartedFlurryParams["Level"] = currentWorldNumber  .. "-" .. currentLevelNumberInTheme
				levelRestartedFlurryParams["Attempts"] = "" .. numberOfAttemptsInLevel
				levelRestartedFlurryParams["Birds used"] = "" .. birdsShot
				levelRestartedFlurryParams["Birds available"] = "" .. birdsCounter
				levelRestartedFlurryParams["From"] = "" .. levelRestartedFrom
				
				logFlurryEventWithParams("Level restarted", "levelRestartedFlurryParams")

				--print("FlurryEventWithParam: Level restarted, Level, " .. currentWorldNumber .. "-" ..currentLevelNumberInTheme .. "\n")
				numberOfAttemptsInLevel = numberOfAttemptsInLevel + 1
			end
		end
		
		setEditing(false)
		setPhysicsEnabled(false)
		currentLevelNumber = page.items[selectedMenuItem].levelIndex or currentLevelNumber
		currentThemeNumber = page.items[selectedMenuItem].themeIndex or currentThemeNumber
		currentPageNumber = page.pageNumber or currentPageNumber
		loading = true
		setGameMode(updateLoading)
	end
	
	if currentGameMode == updateEditor then
		_G.res.stopAudio(settings.currentMainMenuSong)
		levelName = page.items[selectedMenuItem].filename
		levelFolder = page.items[selectedMenuItem].folder
		levelIndex = page.items[selectedMenuItem].levelIndex
		if levelIndex < 10 then
			levelIndex = "0"..levelIndex
		else
			levelIndex = ""..levelIndex
		end
		setEditing(true)
		setPhysicsEnabled(physicsEnabled)
		currentLevelNumberInTheme = page.items[selectedMenuItem].pageLevelIndex or currentLevelNumberInTheme		
		currentLevelNumber = page.items[selectedMenuItem].levelIndex or currentLevelNumber
		currentThemeNumber = page.items[selectedMenuItem].themeIndex or currentThemeNumber
		currentWorldNumber = page.items[selectedMenuItem].worldNumber or currentWorldNumber
		currentPageNumber = page.pageNumber or currentPageNumber
		
		setGameMode(updateLoading)
		oldGameMode = updateEditor
	end
end


function updateLoading(dt)	
	if loadingPageDrawn == false then
		prepareMenuPage(loadingPage)
		loadingPageDrawn = true
		

		if oldGameMode == updateEditor then
			loadLevelEditor(levelFolder .. levelName)
			loadLevelInternal(levelFolder .. levelName)
			setGameMode(updateEditor)
			oldGameMode = nil
		else
			loadLevelDelayed = levelFolder .. levelName
			local dateString = ""
			local levelIndexNumber = levelIndex * 1
			if levelIndexNumber <= 9 then
				dateString = "2011-06-"..levelIndexNumber + 21
			else
				if (levelIndexNumber - 9) < 10 then
					dateString = "2011-07-0"..levelIndexNumber - 9
				else
					dateString = "2011-07-"..levelIndexNumber - 9
				end
			end
			loadLevelFile(loadLevelDelayed, dateString)
		end
		
		
		--changeResolution = true
		--wantedResolution = "FULL"
		
		if iapEnabled == true and inExtraWorld ~= true then
			inGameEagleButtonVisible = true
		end
	end
	drawMenu(dt)
end

function updateLoadingEx(dt)
	if loadingPageDrawn == false then
		loadingPage.backgroundOverlay.shade = deviceModel == "roku" and 1.0 or 0.65
		loading = true
		drawMenu(dt)
		loadingPageDrawn = true
		if loadingPage.nextPage.bgColor ~= nil then
			loadingPage.nextPage.bgColor = { red = loadingPage.nextPage.bgColor.red, green = loadingPage.nextPage.bgColor.green, blue = loadingPage.nextPage.bgColor.blue}
		end
		setActiveMenuPage(loadingPage.nextPage, loadingPage.prepareNextPage)
		popupPage = nil
		loadingPageDrawn = false
		loading = false
		--drawMenu()
		setGameMode(updateMenu)		
	end
end

function releaseCutScenes()
	if useDynamicAssets then return end
	releaseCompoSprites( {"CUTSCENES_COMPOSPRITES"} )
	releaseImages( {"CUTSCENES"} )
	loadImages( {"OTHER", "OTHER_2", "MENU", "BUTTONS", "LEVELSELECTION", "GOLDENEGGS", "TUTORIALS" } )
	loadCompoSprites( {"TUTORIALS_COMPOSPRITES"} )
end

function loadCutScenes()
	if useDynamicAssets then return end
	releaseCompoSprites( {"TUTORIALS_COMPOSPRITES"} )
	releaseImages( {"OTHER", "OTHER_2", "MENU", "BUTTONS", "LEVELSELECTION", "GOLDENEGGS", "TUTORIALS" } )
	loadImages( {"CUTSCENES"}  )
	loadCompoSprites( {"CUTSCENES_COMPOSPRITES"} )
end

