    setActiveManager("halloween2")

	releaseCutScenes()
	
	if checkAdsEnabled() and videoAdRequested ~= true and videoReady ~= true and time - lastVideoAdTime > 300 then
		requestAndShowVideo("interstitial_levelselect")
		lastVideoAdTime = time
	end
end

function gotoEpisodeSelection()
	setGameMode(updateMenu)
	_G.res.stopAllAudio()
	sounds.playAudio(settings.currentMainMenuSong, 0.8, true, 7)
	setActiveMenuPage(episodeSelectionPage)
	drawMenu(dt)
	releaseCutScenes()
end

function loadPreviousLevel(dt)
	drawGame()
	drawMenu(dt)
	if  levelSelectionPages == levelSelectionPagesBasic or levelSelectionPages == levelSelectionPagesPackH 
		or levelSelectionPages == levelSelectionPagesPackV or levelSelectionPages == levelSelectionPagesPackSP 
		or levelSelectionPages == levelSelectionPagesPackEaster or levelSelectionPages == levelSelectionPagesPackSummer 
		or levelSelectionPages == levelSelectionPagesPackMooncake then
		if currentLevelNumberInTheme <= 1 then
			levelSelectionPages.currentPage = levelSelectionPages.currentPage - 1
			if levelSelectionPages.currentPage <= 0 then
				if levelSelectionPages == levelSelectionPagesBasic then
					levelSelectionPages.currentPage = 1
				else
					if levelSelectionPages == levelSelectionPagesBasic then
						levelSelectionPages = levelSelectionPagesPackV
					elseif levelSelectionPages == levelSelectionPagesPackV then
						levelSelectionPages = levelSelectionPagesPackSP
					elseif levelSelectionPages == levelSelectionPagesPackSP then
						levelSelectionPages = levelSelectionPagesPackEaster
					elseif levelSelectionPages == levelSelectionPagesPackEaster then
						levelSelectionPages = levelSelectionPagesPackSummer
					elseif levelSelectionPages == levelSelectionPagesPackSummer then
						levelSelectionPages = levelSelectionPagesPackMooncake
					elseif levelSelectionPages == levelSelectionPagesExtra then
						levelSelectionPages = levelSelectionPagesBasic
					elseif levelSelectionPages == levelSelectionPagesPack3 then
						levelSelectionPages = levelSelectionPagesExtra
					elseif levelSelectionPages == levelSelectionPagesPack4 then
						levelSelectionPages = levelSelectionPagesPack3
					elseif levelSelectionPages == levelSelectionPagesPackH then
						levelSelectionPages = levelSelectionPagesPack4
					end
					levelSelectionPages.currentPage = levelSelectionPages.pageCount
					currentLevelNumberInTheme = levelSelectionPages.levelsPerPage
					currentLevelNumber = levelSelectionPages.pageCount * levelSelectionPages.levelsPerPage
					currentThemeNumber = currentThemeNumber	- 1
					currentWorldNumber = currentWorldNumber - 1
				end
			else
				currentLevelNumberInTheme = levelSelectionPages.levelsPerPage
				currentLevelNumber = currentLevelNumber - 1
				currentThemeNumber = currentThemeNumber	- 1
				currentWorldNumber = currentWorldNumber - 1
			end

		else
			currentLevelNumberInTheme = currentLevelNumberInTheme - 1
			currentLevelNumber = currentLevelNumber - 1
		end
		
		local index = (levelSelectionPages.currentPage - 1) * levelSelectionPages.levelsPerPage + levelSelectionPages.firstLevelIndex		
		levelName = levelSelectionPages.items[currentLevelNumberInTheme + index - 1].filename
		levelFolder = levelSelectionPages.items[currentLevelNumberInTheme + index - 1].folder
		levelIndex = levelSelectionPages.items[currentLevelNumberInTheme + index - 1].levelIndex
		if levelIndex < 10 then
			levelIndex = "0"..levelIndex
		else
			levelIndex = ""..levelIndex
		end
	end
	
	if usePCSelectionMenus() or isExpBranch then
		local currentPageIndex = currentLevelSelectionManager:getCurrentPage()
		local activePage = currentLevelSelectionManager.pages[currentPageIndex]
		local firstLevelIndex = activePage.firstLevelIndex or 1
		
		if currentLevelNumberInTheme > firstLevelIndex then
			currentLevelNumberInTheme = currentLevelNumberInTheme - 1
			currentLevelNumber = currentLevelNumber - 1
		else
			if currentPageIndex > 1 then
				currentLevelSelectionManager:setOffsetByPage(currentPageIndex - 1)
				currentWorldNumber = currentWorldNumber - 1
				activePage = currentLevelSelectionManager.pages[currentLevelSelectionManager:getCurrentPage()]
				currentLevelNumber = activePage.levelAmount
				currentLevelNumberInTheme = activePage.levelAmount
			end
		end
		print("level"..currentLevelNumberInTheme)
		levelName = activePage.items["level"..currentLevelNumberInTheme].filename
		levelFolder = activePage.items["level"..currentLevelNumberInTheme].folder
		levelIndex = activePage.items["level"..currentLevelNumberInTheme].levelIndex
		
		if levelIndex < 10 then
			levelIndex = "0"..levelIndex
		else
			levelIndex = ""..levelIndex
		end

	end
	
	loading = true
	setGameMode(updateLoading)
end

function loadNextLevel(dt)
	if not g_isGameUnlocked and isPCProfile() and g_registrationEnabled and currentLevelNumberInTheme >= 3 then
		--we must switch to windowed mode before opening the dialog
		g_isFullScreenBeforeOpeningRegistration = settings.fullScreen
		if (g_isFullScreenBeforeOpeningRegistration == true) then
			g_updateCount = 0
			_G.res.stopAudio(currentMusic)
			setFullScreenMode(false)
            return
		else
			local t_returnedKey = openRegistrationDialog("Activate the full game!",g_registrationURLs.validationURL, g_registrationURLs.registrationURL, g_registrationKeys.fullGame)
			if t_returnedKey ~= "" then
				g_isGameUnlocked = true
				_G.table.insert(settings.license.registeredKeyTypes, g_registrationKeys.fullGame)
				settings.license.hardwareID = getDeviceID()
			end
			return
		end
	end
    
	drawGame()
	--drawMenu()
	if  levelSelectionPages == levelSelectionPagesBasic or levelSelectionPages == levelSelectionPagesPackH 
		or levelSelectionPages == levelSelectionPagesPackV or levelSelectionPages == levelSelectionPagesPackSP or
		levelSelectionPages == levelSelectionPagesPackEaster or levelSelectionPages == levelSelectionPagesPackSummer or
		levelSelectionPages == levelSelectionPagesPackMooncake then
		if currentLevelNumberInTheme >= levelSelectionPages.levelsPerPage then
			levelSelectionPages.currentPage = levelSelectionPages.currentPage + 1
			if levelSelectionPages.currentPage > levelSelectionPages.pageCount then
				if levelSelectionPages == levelSelectionPagesPackH then
					levelSelectionPages.currentPage = levelSelectionPages.pageCount
				else
					if levelSelectionPages == levelSelectionPagesPackMooncake then
						levelSelectionPages = levelSelectionPagesPackSummer
					elseif levelSelectionPages == levelSelectionPagesPackSummer then
						levelSelectionPages = levelSelectionPagesPackEaster
					elseif levelSelectionPages == levelSelectionPagesPackEaster then
						levelSelectionPages = levelSelectionPagesPackSP
					elseif levelSelectionPages == levelSelectionPagesPackSP then
						levelSelectionPages = levelSelectionPagesPackV
					elseif levelSelectionPages == levelSelectionPagesPackV then
						levelSelectionPages = levelSelectionPagesBasic
					elseif levelSelectionPages == levelSelectionPagesBasic then
						levelSelectionPages = levelSelectionPagesExtra
					elseif levelSelectionPages == levelSelectionPagesExtra then
						levelSelectionPages = levelSelectionPagesPack3
					elseif levelSelectionPages == levelSelectionPagesPack3 then
						levelSelectionPages = levelSelectionPagesPack4	
					elseif levelSelectionPages == levelSelectionPagesPack4 then
						levelSelectionPages = levelSelectionPagesPackH	
					end
					levelSelectionPages.currentPage = 1
					currentLevelNumberInTheme = 1
					currentLevelNumber = 1
					currentThemeNumber = currentThemeNumber	+ 1
					currentWorldNumber = currentWorldNumber + 1
				end
			else				
				currentLevelNumberInTheme = 1
				currentLevelNumber = currentLevelNumber + 1
				currentThemeNumber = currentThemeNumber	+ 1
				currentWorldNumber = currentWorldNumber + 1
			end
		else
			currentLevelNumberInTheme = currentLevelNumberInTheme + 1
			currentLevelNumber = currentLevelNumber + 1
		end
		
		numberOfAttemptsInLevel = 1
		
		levelStartedFlurryParams = {}
		levelStartedFlurryParams["Level"] = currentWorldNumber  .. "-" .. currentLevelNumberInTheme
		levelStartedFlurryParams["From"] = "" .. levelRestartedFrom
		logFlurryEventWithParams("Level started", "levelStartedFlurryParams") 
		-- print("FlurryEventWithParam: Level started, Level, " .. currentWorldNumber .. "-" ..currentLevelNumberInTheme .. "\n")
        
        if currentWorldNumber == 7 or currentWorldNumber == 9 then
            currentWorldInEpisode = 2
        end 
		
		local index = (levelSelectionPages.currentPage - 1) * levelSelectionPages.levelsPerPage + levelSelectionPages.firstLevelIndex
		if isLiteVersion then
			index = levelSelectionPages.firstLevelIndex
		end
		levelName = levelSelectionPages.items[currentLevelNumberInTheme + index - 1].filename
		levelFolder = levelSelectionPages.items[currentLevelNumberInTheme + index - 1].folder
		levelIndex = levelSelectionPages.items[currentLevelNumberInTheme + index - 1].levelIndex
		if levelIndex < 10 then
			levelIndex = "0"..levelIndex
		else
			levelIndex = ""..levelIndex
		end
		
	end
	 
	if usePCSelectionMenus() or isExpBranch then 
		local currentPageIndex = currentLevelSelectionManager:getCurrentPage()
		local activePage = currentLevelSelectionManager.pages[currentPageIndex]
		local nextPageIndex = currentPageIndex
		if currentPageIndex < #currentLevelSelectionManager.pages then
			nextPageIndex = currentPageIndex + 1
		end
		
		local lastLevelIndexCurrentPage = currentLevelSelectionManager.pages[currentPageIndex].firstLevelIndex - 1 + activePage.levelAmount
		
		if currentLevelNumberInTheme < lastLevelIndexCurrentPage then
			currentLevelNumberInTheme = currentLevelNumberInTheme + 1
			currentLevelNumber = currentLevelNumber + 1
		else
			if currentPageIndex < #currentLevelSelectionManager.pages and currentLevelSelectionManager.pages[nextPageIndex] and currentLevelSelectionManager.pages[nextPageIndex].items["level1"] then
				if currentLevelSelectionManager.navSavePage then
                    settings.currentLevelSelectionPages[currentLevelSelectionManager.navSavePage] = nextPageIndex
                    currentLevelSelectionManager.slideToPage = true
                end
				currentLevelNumberInTheme = 1
				currentLevelNumber = 1
				currentWorldNumber = currentWorldNumber + 1
				activePage = currentLevelSelectionManager.pages[nextPageIndex]
                currentLevelSelectionManager.activePage = nextPageIndex
			end
		end
		levelName = activePage.items["level"..currentLevelNumberInTheme].filename
		levelFolder = activePage.items["level"..currentLevelNumberInTheme].folder
		levelIndex = activePage.items["level"..currentLevelNumberInTheme].levelIndex
		
		if levelIndex < 10 then
			levelIndex = "0"..levelIndex
		else
			levelIndex = ""..levelIndex
		end

	end
	
	levelRestartedFrom = nil
	loading = true
	setGameMode(updateLoading)
end


