function isGEPage2Unlocked()
	local flag = false
	for i = 1, levelSelectionPagesGoldenEggs[1].levelCount - 15 do
		if settings.openGoldenEggLevels["Level"..15+i] then
			flag = flag or true
		end
	end
	return flag
