-- Show/hide time left to unlock next level
function showTimeLeft(levelSelected)
	
	local timeLeft = (timeToNext + (levelSelected - todayDateDay - 1) * 86400) - _G.os.time()
	-- print("levelSelected: "..levelSelected.." todayDateDay: "..todayDateDay.. "timeLeft: "..timeLeft.." timeToNext: "..timeToNext)
	if timeLeft < 0 then
		-- setGameMode(updateGame)
		-- handleGameModeChange(levelSelectionPagesPackSummer, levelSelectionPagesPackSummer.firstLevelIndex + levelSelected - 1)
		openSummerHatch(levelSelected)
		--showAlertBox("Error", "A connection error has occurred, please try again.")
	else
		local timeLeftDays = _G.math.floor(timeLeft / 86400)
		local timeLeftHours = _G.math.floor(_G.math.fmod(timeLeft, 86400) / 3600)
		local timeLeftMinutes =  _G.math.floor(_G.math.fmod(timeLeft, 3600) / 60)
		--local timeLeftSeconds = _G.math.fmod(timeLeft, 60)
		
		-- if timeLeftSeconds < 10 then
			-- timeLeftSeconds = "0"..timeLeftSeconds
		-- end
		 
		getItemByName(levelUnavailablePopup.items, "timeLeft").text = ""..timeLeftDays.." days, "..timeLeftHours .." hours and "..timeLeftMinutes .." minutes"
		
		if getItemByName(levelUnavailablePopup.items, "timeLeft").text == "0 days, 0 hours and 0 minutes" then
			getItemByName(levelUnavailablePopup.items, "timeLeft").text = "0 days, 0 hours and 1 minutes"
		end
		setActivePopupPage(levelUnavailablePopup)
	end
end

function hideTimeLeft()
	popupPage = nil
	setActiveMenuPage(levelSelectionPagesPackSummer, true)
	levelUnavailablePopupTimer = 0
end

