function gotoExternalLink(link)
    local target = link
    if isPCProfile() and isInFullScreenMode() and not fullScreenTimer then
        -- print("Disabling fullscreen")
		toggleFullScreen()
        fullScreenBeforeLink = true
        fullScreenTimer = 0.1
        linkToBeOpened = link
    elseif isPCProfile() and not isInFullScreenMode() and not fullScreenTimer then
        -- print("Not in fullscreen, no need to do stuff")
        fullScreenBeforeLink = false
	end
    if not isPCProfile() or (isPCProfile() and (not fullScreenBeforeLink or (fullScreenTimer and fullScreenTimer <= 0))) then
        fullScreenTimer = nil
    -- print((isPCProfile() and "EX: PC version " or "Non-PC version") .. (fullScreenBeforeLink and "fullscreen" or "windowed") .. " and game thinks it's in " .. (isInFullScreenMode() and "fullscreen mode." or "windowed mode."))
    -- print("Current gotten link is : " .. link)
        if link == FACEBOOK_URL then logFlurryEvent("Facebook link clicked")
        elseif link == XMAS_GIFT_URL then 
            logFlurryEvent("Xmas present link clicked")
            settings.xmasPresentOpened = true
            saveLuaFileWrapper("settings.lua", "settings", true)
        elseif link == FACEBOOK_URL then logFlurryEvent("Facebook link clicked")
        elseif link ==TWITTER_URL then logFlurryEvent("Twitter link clicked")
        elseif link == ANGRY_BIRDS_TRAILER_URL then logFlurryEvent("Trailer link clicked")
        elseif link == ABSHOP_URL then logFlurryEvent("ABshop link clicked")
        elseif link == "angrybirdsriofullpc" or link == "originalfull" then 
           logFlurryEvent("AB ".. link .." PC game link clicked")
           target = (ABPCGAME_URL .. "" .. link)
            -- print("Rio or classic link after mod : " .. target)
        end
        --print("Attempting to open link: " .. target)
        _G.res.openURL(target)
    end
end

