function gotoPostcardPage()
	-- Create a WebView if it hasn't been created yet
	if not ABPostcardViewCreated and webViewIsSupported then
		if deviceModel == "ipad" then
			ABPostcardView = _G.WebView.new((screenWidth - 640) / 2, (screenHeight - 480) / 2, 480, 640)
		else
			ABPostcardView = _G.WebView.new(0, 0, screenHeight, screenWidth)
		end
		ABPostcardViewCreated = true
		isABCardWebViewLoading = true
		
		-- ABPostcardView:allowCallsFromJavaScript("_G")
		-- _G.hideABPostcardView = function()
								-- print("_G.hideABPostcardView called \n")
								-- ABPostcardView:hide()
							-- end
		-- Add onLinkClicked call-back
		local onLinkClickedABLike = function(view, url)
			print("link clicked: "..url.."\n")
			local beginIndex, endIndex = _G.string.find(url, "close")
			local checkIndexBegin, checkIndexEnd = _G.string.find(url, ".php?session=")
			if beginIndex ~= nil and beginIndex >= 1 then
				ABPostcardView:hide()
				popupPage = nil
				isABCardWebViewLoading = false
			end
			
			if checkIndexBegin ~= nil and checkIndexBegin >= 1 then
				return _G.WebView.LOAD_PAGE_INTO_WEBVIEW
			else
				return _G.WebView.DONT_LOAD_PAGE
			end
		end
		
		ABPostcardView:setOnLinkClickedCallback(onLinkClickedABLike)
		
		-- Load postcard
		local onPageLoadedABLike = function(view, success, pageTitle)
			isABCardWebViewLoading = false
			ABPostcardViewLoaded = false
			local beginIndex, endIndex = _G.string.find(pageTitle, "404")
			if success and beginIndex == nil then
				if pageTitle == "dismissABLikePage[jqrt]" then
					ABPostcardView:hide()
					popupPage = nil
				else
					if pageTitle == "Angry Birds Seasons Cards" then
						ABPostcardViewLoaded = true
					end
					if currentMenuPage == episodeSelectionPage then
						isABCardWebViewLoading = true
						view:show()
					end
					-- new menu system has different menu page
					if isExpBranch then
						if currentMenuPage.name == "levelSelectionManager" then
							isABCardWebViewLoading = true
							view:show()
						end
					end
				end
			else
				if popupPage ~= systemPopup then
					view:hide()
					popupPage = nil
					showSystemPopup("Network error", "A connection error has occurred, please try again.")
				end
			end
			print("pageTitle: "..pageTitle.."\n")
		end
		
		ABPostcardView:setOnPageLoadedCallback(onPageLoadedABLike)	
	elseif not webViewIsSupported then
		setGameMode(updateMenu)
		setActiveMenuPage(currentMenuPage, true)
		_G.res.openURL(POSTCARD_URL)
	end
	
	if ABPostcardView ~= nil then
		if ABPostcardViewLoaded then
			ABPostcardView:show()
			setActivePopupPage(loadingPage)
		else
			isABCardWebViewLoading = true
			setActivePopupPage(loadingPage)
			ABPostcardView:loadPage(ABCARDS_URL)
		end
	end
	
	setGameMode(updateMenu)
	if isExpBranch then
		setActiveManager(currentLevelSelectionManager.name)
	elseif isLiteVersion then
		setActiveMenuPage(levelSelectionPagesBasic, true)
	else
		setActiveMenuPage(episodeSelectionPage, true)
	end
	drawMenu()
	logFlurryEvent("Postcard page link clicked")
	-- _G.res.openURL(POSTCARD_URL)
end

function gotoABFBConnect()
	-- Create a WebView if it hasn't been created yet
	if not ABLikeViewCreated and webViewIsSupported then
		
		if not settings.fbPageLiked then
			if deviceModel == "ipad" then
				ABLikeView = _G.WebView.new((screenWidth - 640) / 2, (screenHeight - 480) / 2, 480, 640)
			else
				ABLikeView = _G.WebView.new(0, 0, screenHeight, screenWidth)
			end
			ABLikeViewCreated = true
			isABLikeWebViewLoading = true
			
			-- ABLikeView:allowCallsFromJavaScript("_G")
			-- _G.hideABLikeView = function()
									-- print("_G.hideABLikeView called \n")
									-- ABLikeView:hide()
								-- end
			-- Add onLinkClicked call-back
			local onLinkClickedABLike = function(view, url)
				print("link clicked: "..url.."\n")
				local beginIndex, endIndex = _G.string.find(url, "close")
				if beginIndex ~= nil and beginIndex >= 1 then
					return _G.WebView.LOAD_PAGE_INTO_WEBVIEW
				else
					return _G.WebView.DONT_LOAD_PAGE
				end
			end
			
			ABLikeView:setOnLinkClickedCallback(onLinkClickedABLike)
			
			-- Load AB like page
			local onPageLoadedABLike = function(view, success, pageTitle)
				isABLikeWebViewLoading = false
				local beginIndex, endIndex = _G.string.find(pageTitle, "404")
				if success and beginIndex == nil then
					if pageTitle == "dismissABLikePage[jqrt]" then
						ABLikeView:hide()
						popupPage = nil
					elseif pageTitle == "dismissABLikePage[jqrtakta]" then
						popupPage = nil
						view:hide()
						settings.fbPageLiked = true
						settings.fbPageLikedSP = true
						settings.fbPageLikedMooncake = true
						view:delete()
						ABLikeView = nil
						ABLikeViewCreated = nil
						setActiveMenuPage(currentMenuPage, true)
					else
						isABLikeWebViewLoading = true
						view:show()
					end
				else
					if popupPage ~= systemPopup then
						view:hide()
						popupPage = nil
						showSystemPopup("Network error", "A connection error has occurred, please try again.")
					end
				end
				print("pageTitle: "..pageTitle.."\n")
			end
			
			ABLikeView:setOnPageLoadedCallback(onPageLoadedABLike)
		else
			showSystemPopup("Thank you!", "We like you too!\n\n")
		end
	elseif not webViewIsSupported then
		if settings.fbPageLiked then
			showSystemPopup("Thank you!", "We like you too!\n\n")
		else
			setGameMode(updateMenu)
			setActiveMenuPage(currentMenuPage, true)
			settings.fbPageLiked = true
			settings.fbPageLikedSP = true
			settings.fbPageLikedMooncake = true
			_G.res.openURL(AB_FBCONNECT_URL)
		end
	end
	
	if ABLikeView ~= nil then
		isABLikeWebViewLoading = true
		setActivePopupPage(loadingPage)
		ABLikeView:loadPage(ABLIKE_URL)
	end
	
	setGameMode(updateMenu)
	-- setActiveMenuPage(currentMenuPage, true)
	-- -- if currentMenuPage == levelSelectionPagesPackV then
		-- -- settings.fbPageLiked = true
	-- -- else
		-- -- settings.fbPageLikedSP = true
	-- -- end
	
	drawMenu()
	logFlurryEvent("ABFBConnect link clicked")
	-- _G.res.openURL(AB_FBCONNECT_URL)
end

