	end
	if settings.tutorials["BIRD_GREY"] ~= nil then
		_G.table.insert(birdTutorialPopups, settings.tutorials["BIRD_GREY"].sprite)
	end
	if settings.tutorials["BIRD_GREEN"] ~= nil then
