function drawHalloweenMenu(dt)
	local xs = 1
	local ys = 1

	setRenderState(0, 0, xs, ys, 0)
	local mainMenuSky = "BACKGROUND_9_LAYER_1"
	local mainMenuGround = "THEME_9_BG_LAYER_2"
	local skyW, skyH = _G.res.getSpriteBounds("",mainMenuSky)
	local groundW, groundH = _G.res.getSpriteBounds("",mainMenuGround)
	
	local skyScaleW = (skyW * screenHeight / skyH) / skyW
	local skyScaleH = screenHeight / skyH
	
	setRenderState(screenWidth / (2 * xs) - (time * 10) % skyW, 0, skyScaleW, skyScaleH)
	_G.res.drawSprite("", mainMenuSky, 0, 0, "LEFT", "TOP")
	_G.res.drawSprite("", mainMenuSky, -skyW, 0, "LEFT", "TOP")
	_G.res.drawSprite("", mainMenuSky, skyW, 0, "LEFT", "TOP")
	_G.res.drawSprite("", mainMenuSky, -2 * skyW, 0, "LEFT", "TOP")
	_G.res.drawSprite("", mainMenuSky, 2 * skyW, 0, "LEFT", "TOP")
	
	local moonScale = (screenHeight / 320) * 0.8
	local moonX, moonY = screenWidth / (2 * moonScale) , screenHeight / (1.8 * moonScale)
	setRenderState(0, 0, moonScale, moonScale, 0)	
	_G.res.drawSprite("", "MENU_MOON", moonX, moonY , "HCENTER", "VCENTER")
	
	local moonOriginX, moonOriginY = screenWidth / 2, screenHeight / 1.8
	
	for i = 1, #bats do
		local distanceToMoon = _G.math.floor(_G.math.sqrt(_G.math.pow(bats[i].x - moonOriginX, 2) + _G.math.pow(bats[i].y - moonOriginY, 2)))
		local batScale = 1.5 * distanceToMoon / maxDistanceToMoon
		bats[i].animationSteps = _G.math.random(190, 240) * 0.017 / dt
		--print("distanceToMoon: "..distanceToMoon)
		bats[i].timerAnim = bats[i].timerAnim + dt
		bats[i].y = bats[i].y - ( bats[i].y - moonOriginY ) / bats[i].animationSteps
		if bats[i].x > moonOriginX then
			setRenderState(0, 0, batScale, batScale, 0)
			bats[i].x = bats[i].x - ( bats[i].x - moonOriginX ) / bats[i].animationSteps
			if bats[i].currentAnimFrame == 4 then
				_G.res.drawSprite("", "BAT_FRAME_2", bats[i].x / batScale, bats[i].y / batScale, "HCENTER", "VCENTER")
			else
				_G.res.drawSprite("", "BAT_FRAME_"..bats[i].currentAnimFrame, bats[i].x / batScale, bats[i].y / batScale, "HCENTER", "VCENTER")
			end
		else
			setRenderState(0, 0, -batScale, batScale, 0)
			bats[i].x = bats[i].x + ( moonOriginX - bats[i].x ) / bats[i].animationSteps
			_G.res.drawSprite("", "BAT_FRAME_"..bats[i].currentAnimFrame, bats[i].x / (-batScale), bats[i].y / batScale, "HCENTER", "VCENTER")
		end
		if distanceToMoon <= 20 then
			bats[i].x = _G.math.random(- screenWidth / 2, 1.5 * screenWidth)
			bats[i].y = screenHeight + 50
			bats[i].currentAnimFrame = _G.math.random(1, 3)
			bats[i].timerAnim = 0
			bats[i].timerWings = _G.math.random() * 0.025 + 0.06
		end
		
		if bats[i].timerAnim >= bats[i].timerWings then
			bats[i].timerAnim = 0
			bats[i].currentAnimFrame = bats[i].currentAnimFrame % 3 + 1
		end
		--print(""..bats[i].currentAnimFrame % 3 + 1)
	end
	
					-- draw birds, rewards..
	for k, v in _G.pairs(birdAnimations) do
		if v.layer == 3 then
			local scale = v.scale * 0.45
			setRenderState(0, 0, scale, scale, v.angle, _G.res.getSpritePivot(v.sheet, v.sprite))
			_G.res.drawSprite(v.sheet, v.sprite, _G.math.floor(v.x/scale), _G.math.floor(v.y/scale - screenHeight * 0.2 / v.scale))
		end
	end	
	

	for k, v in _G.pairs(birdAnimations) do
		if v.layer == 4 then
			local scale = v.scale * 0.6
			setRenderState(0, 0, scale, scale, v.angle, _G.res.getSpritePivot(v.sheet, v.sprite))
			_G.res.drawSprite(v.sheet, v.sprite, _G.math.floor(v.x/scale), _G.math.floor(v.y/scale - screenHeight * 0.125 / v.scale))
		end
	end		
	
	
	for k, v in _G.pairs(birdAnimations) do
		if v.layer == 5 then
			local scale = v.scale * 0.75
			setRenderState(0, 0,scale, scale, v.angle, _G.res.getSpritePivot(v.sheet, v.sprite))
			_G.res.drawSprite(v.sheet, v.sprite, _G.math.floor(v.x/scale), _G.math.floor(v.y/scale))
		end
	end	

	
	local groundScale = 0.7 * screenHeight / 320
	
	setRenderState(0, 0, 1, 1, 0, 0, 0)
	setRenderState(screenWidth / (2 * xs) - (time * 30) % groundW, 0, groundScale, groundScale)
	_G.res.drawSprite("", mainMenuGround, -2 * groundW, screenHeight / groundScale, "LEFT", "BOTTOM")
	_G.res.drawSprite("", mainMenuGround, -groundW, screenHeight / groundScale, "LEFT", "BOTTOM")
	_G.res.drawSprite("", mainMenuGround, 0, screenHeight / groundScale, "LEFT", "BOTTOM")
	_G.res.drawSprite("", mainMenuGround, groundW, screenHeight / groundScale, "LEFT", "BOTTOM")
	_G.res.drawSprite("", mainMenuGround, 2 * groundW, screenHeight / groundScale, "LEFT", "BOTTOM")
	-- end of halloween main menu draw
end

