			setRenderState(0, 0, 1, 1, 0)
		end
		
	end
	
	if page == levelSelectionPagesPackSP then
		-- draw effect for new golden egg levels
		if settings.openGoldenEggLevels["Level22"] == 0 then
			setRenderState(0, 0, 1, 1, goldenEggsStarEffectAngle, _G.res.getSpritePivot("", "GOLDEN_EGG_STAR_EFFECT"))
			_G.res.drawSprite("", "GOLDEN_EGG_STAR_EFFECT", getItemByName(page.items, "goldenEgg").x, getItemByName(page.items, "goldenEgg").y)
			setRenderState(0, 0, 1, 1, 0)
		end
		
		if settings.openGoldenEggLevels["Level23"] == 0 then
			setRenderState(0, 0, 2, 2, goldenEggsStarEffectAngle, _G.res.getSpritePivot("", "GOLDEN_EGG_STAR_EFFECT"))
