			_G.res.drawSprite("", "GOLDEN_EGG_STAR_EFFECT", getItemByName(page.items, "goldenEgg").x, getItemByName(page.items, "goldenEgg").y)
			setRenderState(0, 0, 1, 1, 0)
		end
		
		if settings.openGoldenEggLevels["Level21"] == 0 then
			setRenderState(0, 0, 2, 2, 0)
			_G.res.drawSprite("", "BLUE_RADIAL_GRADIENT", getItemByName(page.items, "heart3Stars").x / 2, getItemByName(page.items, "heart3Stars").y / 2)
			setRenderState(0, 0, 2, 2, goldenEggsStarEffectAngle, _G.res.getSpritePivot("", "GOLDEN_EGG_STAR_EFFECT"))
			_G.res.drawSprite("", "GOLDEN_EGG_STAR_EFFECT", getItemByName(page.items, "heart3Stars").x / 2, getItemByName(page.items, "heart3Stars").y / 2)
			setRenderState(0, 0, 1, 1, 0)
		end
		
	end
	
	if page == levelSelectionPagesPackH then
		-- draw effect for new golden egg levels
		if settings.openGoldenEggLevels["Level18"] == 0 then
			setRenderState(0, 0, 1, 1, goldenEggsStarEffectAngle, _G.res.getSpritePivot("", "GOLDEN_EGG_STAR_EFFECT"))
			_G.res.drawSprite("", "GOLDEN_EGG_STAR_EFFECT", getItemByName(page.items, "goldenEgg").x, getItemByName(page.items, "goldenEgg").y)
			setRenderState(0, 0, 1, 1, 0)
		end
		
		if settings.openGoldenEggLevels["Level19"] == 0 then
			setRenderState(0, 0, 2, 2, goldenEggsStarEffectAngle, _G.res.getSpritePivot("", "GOLDEN_EGG_STAR_EFFECT"))
			_G.res.drawSprite("", "GOLDEN_EGG_STAR_EFFECT", getItemByName(page.items, "pumpkin").x / 2, getItemByName(page.items, "pumpkin").y / 2)
			setRenderState(0, 0, 1, 1, 0)
		end
		
	end
	
	if page == levelSelectionPagesBasic then
		-- draw effect for new golden egg levels
		if settings.openGoldenEggLevels["Level16"] == 0 and not isLiteVersion then
			setRenderState(0, 0, 1, 1, goldenEggsStarEffectAngle, _G.res.getSpritePivot("", "GOLDEN_EGG_STAR_EFFECT"))
			_G.res.drawSprite("", "GOLDEN_EGG_STAR_EFFECT", getItemByName(page.items, "goldenEgg").x, getItemByName(page.items, "goldenEgg").y)
			setRenderState(0, 0, 1, 1, 0)
		end
		
		if settings.openGoldenEggLevels["Level17"] == 0 and not isLiteVersion then
			setRenderState(0, 0, 2, 2, goldenEggsStarEffectAngle, _G.res.getSpritePivot("", "GOLDEN_EGG_STAR_EFFECT"))
			_G.res.drawSprite("", "GOLDEN_EGG_STAR_EFFECT", getItemByName(page.items, "presentItem").x / 2, getItemByName(page.items, "presentItem").y / 2)
			setRenderState(0, 0, 1, 1, 0)
		end
		
		if settings.xmasPresentOpened ~= nil and settings.xmasPresentOpened == false and not isLiteVersion then
			setRenderState(0, 0, 1, 1, goldenEggsStarEffectAngle, _G.res.getSpritePivot("", "GOLDEN_EGG_STAR_EFFECT"))
			_G.res.drawSprite("", "GOLDEN_EGG_STAR_EFFECT", getItemByName(page.items, "xmasPresent").x, getItemByName(page.items, "xmasPresent").y)
			setRenderState(0, 0, 1, 1, 0)
		end
	end
	
	if (page == levelSelectionPagesBasic or page == levelSelectionPagesPackV or page == levelSelectionPagesPackH 
		or page == levelSelectionPagesPackSP or page == levelSelectionPagesPackEaster or page == levelSelectionPagesPackSummer
		or page == levelSelectionPagesPackMooncake) then
			return drawLevelSelectionItems(page)
	end
	
	-- check if user want's to draw one whole item at a time or all sprites (and boxes) first and then text
	local drawSprites = true
	local drawText = true
	local loops = 0
	if page.drawSpritesFirst == true then
		drawText = false
		loops = 1
	end
	
	if page == goldenEggAchievedPage and page.items[1].visible == true then
		local starEffectSprite = "GOLDEN_EGG_STAR_EFFECT"
		setRenderState(0, 0, 1, 1, page.items[1].starAngle, _G.res.getSpritePivot("", starEffectSprite))
		_G.res.drawSprite("", starEffectSprite, page.items[1].x, page.items[1].y)
		setRenderState(0, 0, 1, 1, 0)
	end
		
	if page == mightyEaglePaymentPage and getItemByName(page.items, "progress").angle < 1080 then
        local angle = _G.math.floor(getItemByName(mightyEaglePaymentPage.items, "progress").angle/(_G.math.pi/6)) * (_G.math.pi/6) -- Use 30 degree increments
        local boundx, boundy = _G.res.getSpriteBounds("", getItemByName(mightyEaglePaymentPage.items, "progress").sprite)
		setRenderState(0, 0, 1, 1, angle, boundx/2,boundy/2)
		_G.res.drawSprite("", getItemByName(mightyEaglePaymentPage.items, "progress").sprite, getItemByName(mightyEaglePaymentPage.items, "progress").x, getItemByName(mightyEaglePaymentPage.items, "progress").y)
		setRenderState(0, 0, 1, 1, 0)
	end
	
	if page == goldenEggStarAchievedPage and page.items[1].visible == true and page.items[2].visible == true then
		local starEffectSprite = "GOLDEN_EGG_STAR_EFFECT"
		setRenderState(0, 0, 1, 1, page.items[1].angle, _G.res.getSpritePivot("", starEffectSprite))
		_G.res.drawSprite("", starEffectSprite, page.items[1].x, page.items[1].y)
		setRenderState(0, 0, 1, 1, 0)
	end
	
	-- draw normal menu items
	for k = 0, loops do
		local i = 1
		while i <= #page.items do
			local ci = page.items[i]
			if ci.visible ~= false then
				-- calculate position
				local x = screenWidth/2
				local y = screenHeight/(#page.items + 1) * i
				x = ci.x and ci.x or x
				y = ci.y and ci.y or y
				x, y = offsetCoordinates(page, x, y)
				if ci.itemDrawFunction ~= nil then
					ci.itemDrawFunction(page, ci, x, y, drawSprites, drawText)
				else
					drawMenuItem(page, ci, _G.math.floor(x), _G.math.floor(y), drawSprites, drawText)
				end
			end
			i = i + 1
		end
		drawSprites = not drawSprites
		drawText = not drawText
	end
	

end

function drawMenuItem(page, item, x, y, drawSprites, drawText)
	if item.visible == false then
		return
	end
	
	local ci = item
	
	-- get anchor data
	local hanchor = ci.hanchor and ci.hanchor or "HCENTER"
	local vanchor = ci.vanchor and ci.vanchor or "VCENTER"

	-- local xs = 1
	-- local ys = 1
	-- local angle = 0
	
	-- if item.xs ~= nil then xs = item.xs	end
	-- if item.ys ~= nil then ys = item.ys	end
	-- if item.angle ~= nil then angle = item.angle	end
	
	-- setRenderState(0, 0, xs, ys, angle)
	
	if drawSprites == true then
		if ci.sprite ~= nil then
			local sheet = ""
			if ci.sheet ~= nil then
				sheet = ci.sheet
			end
			
			if isPCProfile() or deviceModel == "roku" then
				
				local t_pageScaleX = page.xs or 1
				local t_pageScaleY = page.ys or 1
				
				local t_clipX = page.clipX or 0
				local t_clipY = page.clipY or 0
				local t_clipW = page.clipW or screenWidth
				local t_clipH = page.clipH or screenHeight
				
				local t_rotPivotX = ci.rotationPivotX or 0
				local t_rotPivotY = ci.rotationPivotY or 0
				local t_angle = ci.angle or 0
				local t_scaleX = ci.xs or 1
				local t_scaleY = ci.ys or 1
				
				local t_finalScaleX = t_pageScaleX * t_scaleX
				local t_finalScaleY = t_pageScaleY * t_scaleY
				
				_G.res.setClipRect(t_clipX, t_clipY, t_clipW, t_clipH)
				
				if ci.mouseState ~= nil then
					drawMouseScalingItem(sheet,ci, x, y)
				else
					setRenderState(_G.math.floor(x) / t_finalScaleX, _G.math.floor(y) / t_finalScaleY, t_finalScaleX, t_finalScaleY, t_angle, t_rotPivotX, t_rotPivotY )
					_G.res.drawSprite(ci.sprite, 0,0)
					setRenderState(0, 0, 1, 1, 0, 0, 0)
				end
				
				if ci.rectangle then
					drawRect(ci.color.red, ci.color.green, ci.color.blue, 1.0, _G.math.floor(x), _G.math.floor(y), _G.math.floor(ci.width + x), _G.math.floor(ci.height + y), false)
				end
				
				_G.res.setClipRect(0,0,screenWidth, screenHeight)																
				
			else
				--NOT PC
				if ci.angle then
					local rotPivotX = ci.rotationPivotX or 0
					local rotPivotY = ci.rotationPivotY or 0
					setRenderState(0, 0, 1, 1, ci.angle, rotPivotX, rotPivotY)
					_G.res.drawSprite(sheet, ci.sprite, _G.math.floor(x), _G.math.floor(y))
					setRenderState(0, 0, 1, 1, 0, 0, 0)
				elseif ci.scale and ci.xs and ci.ys then
					setRenderState(0, 0, ci.xs, ci.ys)
					_G.res.drawSprite("", ci.sprite, _G.math.floor(x) / ci.xs, _G.math.floor(y) / ci.ys)
					setRenderState(0, 0, 1, 1)
				elseif page.scale and page.xs and page.ys then
					if ci.isCompoSprite then
						setRenderState(0, 0, page.xs, page.ys)
						_G.res.drawCompoSprite("", ci.sprite, _G.math.floor(x) / page.xs, _G.math.floor(y) / page.ys)
						setRenderState(0, 0, 1, 1)
					else
						setRenderState(0, 0, page.xs, page.ys)
						_G.res.drawSprite(sheet, ci.sprite, _G.math.floor(x) / page.xs, _G.math.floor(y) / page.ys)
						setRenderState(0, 0, 1, 1)
					end
				else
					if ci.isCompoSprite then
						_G.res.drawCompoSprite("", ci.sprite, _G.math.floor(x), _G.math.floor(y))
					else
						_G.res.drawSprite(sheet, ci.sprite, _G.math.floor(x), _G.math.floor(y))
					end
				end
			end
		elseif ci.box ~= nil then
		--[[	local x, y = 0, 0

			if ci.x ~= nil then
				x = ci.x
			end
			if ci.y ~= nil then
				y = ci.y
			end]]
			
			local sheet = ""
			if ci.sheet ~= nil then
				sheet = ci.sheet
			end
			
			if ci.color ~= nil then
				local r,g,b,a = 1.0, 1.0, 1.0, 1.0
				if ci.color.red ~= nil then
					r = ci.color.red
				end
				if ci.color.green ~= nil then
					g = ci.color.green
				end
				if ci.color.blue ~= nil then
					b = ci.color.blue
				end
				if ci.color.alpha ~= nil then
					a = ci.color.alpha
				end
				
				drawBox(ci.box, sheet, _G.math.floor(x), _G.math.floor(y), _G.math.floor(ci.width), _G.math.floor(ci.height), ci.hanchor, ci.vanchor, { red = r, green = g, blue = b, alpha = a })
			else
				drawBox(ci.box, sheet, _G.math.floor(x), _G.math.floor(y), _G.math.floor(ci.width), _G.math.floor(ci.height), ci.hanchor, ci.vanchor, nil)
			end
		end
	end
	
	if drawText == true then
		if ci.lines ~= nil then
			if ci.mouseState ~= nil then
				drawMouseScalingItem(sheet,ci, x, y)
			else
				--check font
				setFont(ci.font)

				local fh = _G.res.getFontLeading()			
				local k = 1
				while k <= #ci.lines do
					_G.res.drawString("", ci.lines[k], _G.math.floor(x), _G.math.floor(y - ci.h * 0.5 + fh * (k-0.5)), hanchor, vanchor)
					k = k + 1
				end	
			end		
		end
	end
	
	if ci.children ~= nil then
		for i = 1, #ci.children do
			local childItem = ci.children[i]
			drawMenuItem(page, childItem, childItem.x + x, childItem.y + y, drawSprites, drawText)
		end
	end
end

function drawLevelSelectionItems(page)
	local i = 1
	drawSprites = true
	drawText = true
	while i <= #page.items do
		local ci = page.items[i]
		if ci.visible ~= false then
			if ci.sprite then-- and ci.name == nil then
				local sheet = ci.sheet or ""
				if not ci.filename or ci.x >= 0 - ci.spriteWidth and ci.x <= screenWidth + ci.spriteWidth then 
					_G.res.drawSprite(sheet, ci.sprite, _G.math.floor(ci.x), _G.math.floor(ci.y))
					-- if settings.mightyEagleEnabled then
						-- for k, v in _G.pairs(settings.eaglesUsedIn) do
							-- if v.world == ci.worldNumber and v.level == ci.pageLevelIndex then
								-- _G.res.drawSprite("LEVELSELECTION_SHEET_1", "LS_EAGLE_BUTTON", _G.math.floor(ci.x), _G.math.floor(ci.y))
							-- end
						-- end
					-- end
				end
			-- if item is not sprite (scores and stars)
			else
				-- calculate position
				local x = screenWidth/2
				local y = screenHeight/(#page.items + 1) * i
				x = ci.x and ci.x or x
				y = ci.y and ci.y or y
				x, y = offsetCoordinates(page, x, y)
				if ci.itemDrawFunction ~= nil then
					ci.itemDrawFunction(page, ci, x, y, drawSprites, drawText)
				else
					drawMenuItem(page, ci, _G.math.floor(x), _G.math.floor(y), drawSprites, drawText)
				end
			end
		end
		i = i + 1
	end
	
	for i = 1, #levelSelectionButtonIndeces do
		local ci = page.items[levelSelectionButtonIndeces[i].index]
		if ci.visible ~= false and ci.x >= 0 - ci.spriteWidth and ci.x <= screenWidth + ci.spriteWidth then	
			if levelSelectionButtonIndeces[i].eagleUsed then
				_G.res.drawSprite("LEVELSELECTION_SHEET_1", "LS_EAGLE_BUTTON", _G.math.floor(ci.x), _G.math.floor(ci.y))
			end
			if levelSelectionButtonIndeces[i].starSprite then
				if page.isChristmas then
					if i < 25 then
						_G.res.drawSprite("LEVELSELECTION_SHEET_1", "LS_LEVEL_STAR_BG_X", _G.math.floor(ci.x), _G.math.floor(ci.y))			
					elseif i == 25 then
						_G.res.drawSprite("LEVELSELECTION_SHEET_1", "LS_LEVEL_STAR_BG_X_BIG", _G.math.floor(ci.x), _G.math.floor(ci.y))	
					end
					_G.res.drawSprite("LEVELSELECTION_SHEET_1", levelSelectionButtonIndeces[i].starSprite, _G.math.floor(ci.x), _G.math.floor(ci.y))			
				elseif page.isSummer then
					_G.res.drawSprite("", "LS_SUMMER_STAR_BG", _G.math.floor(ci.x), _G.math.floor(ci.y))			
					_G.res.drawSprite("LEVELSELECTION_SHEET_1", levelSelectionButtonIndeces[i].starSprite, _G.math.floor(ci.x), _G.math.floor(ci.y))			
				else
					if not isLiteVersion then
						_G.res.drawSprite("LEVELSELECTION_SHEET_1", levelSelectionButtonIndeces[i].starSprite, _G.math.floor(ci.x), _G.math.floor(ci.y + ci.spriteHeight * 0.5))			
					else
						_G.res.drawSprite("LEVELSELECTION_SHEET_1", levelSelectionButtonIndeces[i].starSprite, _G.math.floor(ci.x), _G.math.floor(ci.y + ci.spriteHeight * 0.48))			
					end
				end
			
			end
			if (settings.mightyEagleEnabled == true or g_futureEagleEnabled == true) and levelSelectionButtonIndeces[i].featherSprite ~= nil then
				
				_G.res.drawSprite("LEVELSELECTION_SHEET_1", levelSelectionButtonIndeces[i].featherSprite, _G.math.floor(ci.x), _G.math.floor(ci.y))
				
			end
		end
	end
			
	for i = 1, #levelSelectionButtonIndeces do
		local ci = page.items[levelSelectionButtonIndeces[i].index]
		if ci.text ~= nil and ci.visible ~= false and ci.lines and ci.x >= 0 - ci.spriteWidth and ci.x <= screenWidth + ci.spriteWidth and (levelSelectionButtonIndeces[i].eagleUsed ~= true or settings.mightyEagleEnabled ~= true) then
			setFont(ci.font)
			_G.res.drawString("", ci.lines[1], _G.math.floor(ci.x), _G.math.floor(ci.y), "HCENTER", "VCENTER")
		end
	end
	
	if deviceModel == "n900" and page == levelSelectionPagesBasic and getItemByName(page.items, "overlay").visible then
		local itm = getItemByName(page.items, "overlay")
		drawRect( 0, 0, 0, itm.shade, itm.x, itm.y, screenWidth, screenHeight, false)
		itm = getItemByName(page.items, "button1")
		_G.res.drawSprite(itm.sheet, itm.sprite, itm.x, itm.y)
		itm = getItemByName(page.items, "button2")
		_G.res.drawSprite(itm.sheet, itm.sprite, itm.x, itm.y)
	end
	
	local back = getItemByName(page.items, "back")
	_G.res.drawSprite("BUTTONS_SHEET_1", back.sprite, back.x, back.y)
	
	local _, textIndex = getItemByName(page.items, "text_" .. page.themes[1])
	for i = textIndex, page.pageCount + textIndex - 1 do
		local numberText = page.items[i]
		if numberText.visible and numberText.lines then
			setFont(numberText.font)
			_G.res.drawString("", numberText.lines[1], numberText.x, numberText.y, "HCENTER", "VCENTER")
		end
	end
		
end

function goldenEggMenuDimDraw(page, item, x, y, drawSprites, drawText)
	if getItemByName(page.items, "overlay").visible then
		local itm = getItemByName(page.items, "overlay")
		drawRect( 0, 0, 0, itm.shade, itm.x, itm.y, screenWidth, screenHeight, false)
	end
end

