function filterLoadedLevel()
	if currentGameMode ~= updateEditor then
		if currentLevelNumberInTheme == 15 and currentWorldNumber == 11 then
			if settings.openGoldenEggLevels["Level16"] then
				loadedObjects.world["ExtraGoldenEgg_1"] = nil
				for k,v in _G.pairs(loadedObjects.joints) do
					if v.end1 == "ExtraGoldenEgg_1" or v.end2 == "ExtraGoldenEgg_1" then
						loadedObjects.joints[k] = nil
					end
				end
			end
		end

		if (currentLevelNumberInTheme == 2 and currentWorldNumber == 14) then
			if settings.openGoldenEggLevels["Level18"] then
				loadedObjects.world["ExtraGoldenEgg_1"] = nil
				for k, v in _G.pairs(loadedObjects.joints) do
					if v.end1 == "ExtraGoldenEgg_1" or v.end2 == "ExtraGoldenEgg_1" then
						loadedObjects.joints[k] = nil
					end
				end
			end
		end
		
		if currentLevelNumberInTheme == 7 and currentWorldNumber == 2 then
			if settings.openGoldenEggLevels["Level20"] then
				loadedObjects.world["ExtraGoldenEgg_1"] = nil
				for k, v in _G.pairs(loadedObjects.joints) do
					if v.end1 == "ExtraGoldenEgg_1" or v.end2 == "ExtraGoldenEgg_1" then
						loadedObjects.joints[k] = nil
					end
				end
			end
		end
		
		if currentLevelNumberInTheme == 8 and currentWorldNumber == 3 then
			if settings.openGoldenEggLevels["Level22"] then
				loadedObjects.world["ExtraGoldenEgg_3"] = nil
				for k, v in _G.pairs(loadedObjects.joints) do
					if v.end1 == "ExtraGoldenEgg_3" or v.end2 == "ExtraGoldenEgg_3" then
						loadedObjects.joints[k] = nil
					end
				end
			end
		end
		
		if currentLevelNumberInTheme == 2 and currentWorldNumber == 4 then
			if settings.openGoldenEggLevels["Level25"] then
				loadedObjects.world["ExtraGoldenEgg_1"] = nil
				for k, v in _G.pairs(loadedObjects.joints) do
					if v.end1 == "ExtraGoldenEgg_1" or v.end2 == "ExtraGoldenEgg_1" then
						loadedObjects.joints[k] = nil
					end
				end
			end
		end
		
