			end
		end
		
		if settings.stPatrickLiteCompleted ~= true then
			if highscores[liteLevelsTable.stPatrick.levels[#liteLevelsTable.stPatrick.levels]] ~= nil 
			  and highscores[liteLevelsTable.stPatrick.levels[#liteLevelsTable.stPatrick.levels]].completed then
				settings.stPatrickLiteCompleted = true
			end
		end
		
		if settings.easterLiteCompleted ~= true then
			if highscores[liteLevelsTable.easter.levels[#liteLevelsTable.easter.levels]] ~= nil 
			  and highscores[liteLevelsTable.easter.levels[#liteLevelsTable.easter.levels]].completed then
				settings.easterLiteCompleted = true
			end
		end
        
        if settings.summerLiteCompleted ~= true then
			if highscores[liteLevelsTable.summer.levels[#liteLevelsTable.summer.levels]] ~= nil 
			  and highscores[liteLevelsTable.summer.levels[#liteLevelsTable.summer.levels]].completed then
				settings.summerLiteCompleted = true
			end
		end
		
        if settings.mooncakeLiteCompleted ~= true then
			if highscores[liteLevelsTable.mooncake.levels[#liteLevelsTable.mooncake.levels]] ~= nil 
			  and highscores[liteLevelsTable.mooncake.levels[#liteLevelsTable.mooncake.levels]].completed then
				settings.mooncakeLiteCompleted = true
			end
		end
		
		local ready = true
        for key,_ in _G.pairs(liteLevelsTable) do
            if key == "xmas" then key = "holiday" end
            if not settings[key .. "LiteCompleted"] then ready = false end
        end
        
        if ready then
            addToAchievementUnlockQueue("Ready For More", true)
        end

		if settings.threeStars == true then
			--addToAchievementUnlockQueue("Total Destruction Lite")
		end
		
		if totalBlocks >= 500 then
			addToAchievementUnlockQueue("Block Smasher Free", true)
		end
		
		if settings.woodBlocksDestroyed ~= nil and settings.woodBlocksDestroyed >= 100 then
			addToAchievementUnlockQueue("Woodpecker Free", true)
		end
		
		if settings.iceBlocksDestroyed ~= nil and settings.iceBlocksDestroyed >= 100 then
			addToAchievementUnlockQueue("Icepicker Free", true)
		end
		
		if settings.holidayLiteThreeStars then
			addToAchievementUnlockQueue("Holiday Vandal", true)
		end
			
		if settings.halloweenLiteThreeStars then
			addToAchievementUnlockQueue("Halloween Wrecker", true)
		end
		
		if settings.valentineLiteThreeStars then
			addToAchievementUnlockQueue("Famed Lover", true)
		end
		
		if settings.stPatrickLiteThreeStars then
			addToAchievementUnlockQueue("Hamrocks and Shenanigans", true)
		end
		
		if settings.easterLiteThreeStars then
			addToAchievementUnlockQueue("Cracking Easter", true)
		end
        
        if settings.summerLiteThreeStars then
			addToAchievementUnlockQueue("Cracking Easter", true)
		end
		
		--FIXME: Mooncake episode achievements?
		
	end

end


function postTotalHighScores()
	if postHighscores == true then
		if not isLiteVersion then
		
			local totalScore = 0

			-- iterate through episodes
			for i = 1, #levelOrder.episodes do
				local epPack = levelOrder.episodes[i]
				local epTotalScore = 0
				local packNumber = 0
				-- iterate through worlds
				for j = 1, #epPack do
					local worldTotalScore = getWorldScore(epPack[j])	
					epTotalScore = epTotalScore + worldTotalScore
					packNumber = _G.tonumber(_G.string.sub(epPack[j], 5)) or 0
					-- post world score if there are more than 1 worlds in the episode
					if #epPack > 1 then
						local lboardName = getLeaderboardNameForWorld(packNumber)
						if lboardName and worldTotalScore > 0 then
							postLevelHighScore(lboardName, worldTotalScore, false)
						end
					end
				end
			
				totalScore = totalScore + epTotalScore
				
				-- post episode score
				local lboardName = getLeaderboardNameForEpisode(packNumber)
				if lboardName and epTotalScore > 0 then
					postLevelHighScore(lboardName, epTotalScore, false)
				end
			end
			
			-- post total score
			local lboardName = getLeaderboardNameForTotalScore()
			if lboardName and totalScore > 0 then
				postLevelHighScore(lboardName, totalScore, false)
			end

		else -- liteVersion
			local totalScoreLite, gainedStars, maxStars = calculateTotalScoreAndStarsLite()
			for k, v in _G.pairs(liteLevelsTable) do
				if v.totalScore > 0 then
					local lboardName
					if k == "xmas" then
						if deviceModel ~= "ipad" then
							lboardName = "totalScoreXmasLite"
						else
							lboardName = "totalScoreXmasHDLite"
						end
					elseif k == "halloween" then
						if deviceModel ~= "ipad" then
							lboardName = "totalScoreHalloweenLite"
						else
							lboardName = "totalScoreHalloweenHDLite"
						end
					elseif k == "valentine" then
						if deviceModel ~= "ipad" then
							lboardName = "totalScoreValentineLite"
						else
							lboardName = "totalScoreValentineHDLite"
						end
					elseif k == "stPatrick" then
						if deviceModel ~= "ipad" then
							lboardName = "totalScoreStPatrickLite"
						else
							lboardName = "totalScoreStPatrickHDLite"
						end
					elseif k == "easter" then
						if deviceModel ~= "ipad" then
							lboardName = "totalScoreEasterLite"
						else
							lboardName = "totalScoreEasterHDLite"
						end
					elseif k == "summer" then
						if deviceModel ~= "ipad" then
							lboardName = "totalScoreSummerLite"
						else
							lboardName = "totalScoreSummerHDLite"
						end
					elseif k == "mooncake" then
						if deviceModel ~= "ipad" then
							lboardName = "totalScoreMooncakeLite"
						else
							lboardName = "totalScoreMooncakeHDLite"
						end
					end
					-- post sub-episode scores
					postLevelHighScore(lboardName, v.totalScore, false)
				end
			end
			
			if totalScoreLite > 0 then
				-- post total score
				if deviceModel ~= "ipad" then
					postLevelHighScore("totalScoreSeasonsLite", totalScoreLite, false)
				else
					postLevelHighScore("totalScoreSeasonsHDLite", totalScoreLite, false)
				end
			end
		end
	end
end

-- <score getters>
function getTotalScore()
	local totalScore = 0
	for i = 1, #levelOrder.episodes do
		for k, pack in _G.ipairs(levelOrder.episodes[i]) do
			for level = 1, #levelOrder[pack] do
				if highscores[levelOrder[pack][level]] ~= nil and highscores[levelOrder[pack][level]].score ~= nil then
					totalScore = totalScore + highscores[levelOrder[pack][level]].score
				end
			end
		end
	end
	return totalScore
end

function getWorldScore(packName)
	local totalScore = 0
	
	for level = 1, #levelOrder[packName] do
		if highscores[levelOrder[packName][level]] ~= nil and highscores[levelOrder[packName][level]].score ~= nil then
			totalScore = totalScore + highscores[levelOrder[packName][level]].score
		end
	end
	
	return totalScore
end
-- </score getters>

function postLevelHighScore(levelName, score, isLevelScore)
	if postHighscores == true then
		if leaderboards ~= nil then
			leaderboardid = leaderboards[levelName]
			if leaderboardid ~= nil then
				print("Posting highscore for level " .. levelName .. " (score = " .. score ..  " leaderboard = " .. leaderboardid .. ")\n")
				postHighscore(leaderboardid, score, isLevelScore)
			else
				print("Leaderboard id for level " .. levelName .. " not found!\n")
			end
		end
	end
end

function openHatch(itemIndex)
	getItemByName(levelSelectionPagesBasic.items, "back").selectable = false
	
	for i = levelSelectionPagesBasic.firstLevelIndex, #levelSelectionPagesBasic.items do
		levelSelectionPagesBasic.items[i].disableSelection = true
	end
	levelSelectionPagesBasic.items[levelSelectionPagesBasic.firstLevelIndex + itemIndex - 1].openingHatch = true
end

function openSummerHatch(itemIndex)
	getItemByName(levelSelectionPagesPackSummer.items, "back").selectable = false
	for i = levelSelectionPagesPackSummer.firstLevelIndex, #levelSelectionPagesPackSummer.items do
		levelSelectionPagesPackSummer.items[i].disableSelection = true
	end
	levelSelectionPagesPackSummer.items[levelSelectionPagesPackSummer.firstLevelIndex + itemIndex - 1].openingHatch = true
end

