-- GAME
--
currentFrame = 0
function updateGame(dt, time)
	-- if keyPressed["Y"] then
		-- createObject(blockTable, "ExtraBlockTNT", "justaname", 0, -5)
	-- end
	
	-- disable roku motion remote when not dragging a bird
	rokuEnableMotion(selectedBird ~= nil)
	
	--%ADDED
	local t_isPCVersion = isPCProfile()	
	local t_isInFullScreen = isInFullScreenMode()
	
	if t_isPCVersion == true then
		if t_isInFullScreen ~= g_mouseOrTouchStates.fullScreen then
			cancelBirdDrag()
			prepareMenuPage(g_ingamePausePage)
		end
		
		g_mouseOrTouchStates.fullScreen = t_isInFullScreen		

	end
	--%ADDED END
	
	--[[ BEGIN FPS DEBUG CODE -- 
	
	if drawFPSStatistics or FPSFrames > 1 then
	
		if not drawFPSStatistics then
			drawFPSStatistics = true
			FPSFrames = 0
			FPSTime = 0
			FPSMin = 1000000
			FPSMax = 0
		end
		
		local FPS = 1/dt
		if FPS < FPSMin then
			FPSMin = FPS
		end
		if FPS > FPSMax then
			FPSMax = FPS
		end
	end
	FPSFrames = FPSFrames + 1
	FPSTime = FPSTime + dt
	
	-- END FPS DEBUG CODE --]]
	if objects.levelWeather ~= nil then
		if objects.levelWeather.firstFrame == true then
			if objects.levelWeather.startAtGroundLevel then
				_G.particles.addParticles(objects.levelWeather.particles, objects.levelWeather.settingsBegin.amount, objects.levelWeather.x, objects.levelWeather.y / 3, objects.levelWeather.width, -2500, 0, objects.levelWeather.settingsBegin.ignoreLimits, true)
			else
				_G.particles.addParticles(objects.levelWeather.particles, objects.levelWeather.settingsBegin.amount, objects.levelWeather.x, objects.levelWeather.y / 3, objects.levelWeather.width, objects.levelWeather.y, 0, objects.levelWeather.settingsBegin.ignoreLimits, true)
			end
			objects.levelWeather.firstFrame = false
			objects.levelWeather.x = objects.levelWeather.x - (particleTable.particles[objects.levelWeather.particles].maxVelX * particleTable.particles[objects.levelWeather.particles].maxVelX / (particleTable.particles[objects.levelWeather.particles].maxVelX / 3)) / 2
		else
			weatherParticlesTimer = weatherParticlesTimer + dt
			if weatherParticlesTimer > (1 / objects.levelWeather.settingsFrame.amount) and isPhysicsEnabled() then
				weatherParticlesTimer = 0
				_G.particles.addParticles(objects.levelWeather.particles, 1, objects.levelWeather.x, objects.levelWeather.y, objects.levelWeather.width, 10, 0, objects.levelWeather.settingsFrame.ignoreLimits, true)
			end
		end
	end
	
	if objects.themeSprites and isPhysicsEnabled() then
		updateThemeSprite(dt)
	end
	
	if t_isPCVersion or deviceModel == "roku" then
		local t_ingameRestart = getItemByName(g_ingamePausePage.items, "ingameButtonRestart")
		local t_ingamePause = getItemByName(g_ingamePausePage.items, "ingameButtonPause")
			
		if g_enableMouseOverStates then
			updateItemMouseOverState(t_ingameRestart, dt)
			updateItemMouseOverState(t_ingamePause, dt)
		end
		
		local t_restartPressed, t_pausePressed
		if deviceModel == "roku" then
			if birdTutorialPopups == nil or birdTutorialPopups and #birdTutorialPopups == 0 then
				t_restartPressed = itemShortcutActivated(t_ingameRestart)
				t_pausePressed   = itemShortcutActivated(t_ingamePause)
			end
		else
			local t_restartHovered = checkSpriteBoundsWithScaling(t_ingameRestart.sheet, t_ingameRestart.sprite, t_ingameRestart.x,t_ingameRestart.y, t_ingameRestart.xs, t_ingameRestart.ys, cursor.x, cursor.y)
			local t_pauseHovered   = checkSpriteBoundsWithScaling(t_ingamePause.sheet, t_ingamePause.sprite, t_ingamePause.x,t_ingamePause.y, t_ingamePause.xs, t_ingamePause.ys, cursor.x, cursor.y)
			t_restartPressed = keyPressed["LBUTTON"] and t_restartHovered and #birdTutorialPopups == 0
			t_pausePressed   = keyPressed["LBUTTON"] and t_pauseHovered and #birdTutorialPopups == 0
			
			if t_restartHovered or t_pauseHovered or birdSpecialtyAvailable then
				g_currentCursorName = "CURSOR_HAND_POINT"
			end
		end
		
		if t_restartPressed then
			levelRestarted = true
			levelRestartedFrom = "keyboard command"
			loading = true
			setGameMode(updateLoading)
			drawGame()
			return
		end
		
		if t_pausePressed then
			if startedFromEditor then
				returnToEditor()
			else
				goToMenu()
				drawGame()
				return
			end
		end
		
		
	end
	
	if isPCProfile() and g_mouseOrTouchStates.isUsingMouse == false and not settings.trackpadTutorialViewed then
		_G.table.insert(birdTutorialPopups, "TUTORIAL_9")
		_G.table.insert(birdTutorialPopups, "TUTORIAL_10")
		_G.table.insert(birdTutorialPopups, "TUTORIAL_12")
		settings.trackpadTutorialViewed = true
	end

	if oldScreenWidth ~= screenWidth or oldScreenHeight ~= screenHeight then
		if #birdTutorialPopups > 0 then
			prepareMenuPage(tutorials)
		end
		
		if popupPage ~= nil then
			if popupPage == achievementPopUpPage then
				-- reset the layout of gamecenter achievement popup except the animation
				local tempAnimationState = popupPage.animationState
				local tempAnimationTimer = popupPage.animationTimer
				prepareMenuPage(achievementPopUpPage)
				popupPage.animationState = tempAnimationState 
				popupPage.animationTimer = tempAnimationTimer 
			end
		end
		
		local t_minimumScreenWidth = 1024
		local t_minimumScreenHeight = 600
		
		if isPCProfile() and (screenWidth < t_minimumScreenWidth or screenHeight < t_minimumScreenHeight) then
			invalidResolutionPage.fromMainMenu = false		
			showIngameResolutionChangedPopUp()
		end
		
		prepareMenuPage(g_ingamePausePage)
	end
	
	if resolutionChanged == true then
		resetCameras()
		if popupPage ~= nil then
			if popupPage == achievementPopUpPage then
				prepareMenuPage(achievementPopUpPage)
			end
		end
		resolutionChanged = nil
	end
	
	cameraShakeX, cameraShakeY = 0, 0
	if cameraShake ~= nil and cameraShake ~= 0 then
		cameraShakeX = _G.math.floor(_G.math.random(-_G.math.abs(cameraShake), _G.math.abs(cameraShake)))
		cameraShakeY = _G.math.floor(_G.math.random(-_G.math.abs(cameraShake), _G.math.abs(cameraShake)))
	end
	
	if inGameEagleButtonScale ~= nil then
		inGameEagleButtonScalingTimer = inGameEagleButtonScalingTimer + dt * 6
		if inGameEagleButtonVisible == true then
			inGameEagleButtonScale = _G.math.cos(inGameEagleButtonScalingTimer) * 0.25 + 0.75
		else
			inGameEagleButtonScale = inGameEagleButtonScale - dt * 3
			if inGameEagleButtonScale <= 0 then
				inGameEagleButtonScale = nil
			end
		end
	end
	
	if popupPage ~= nil then
		if popupPage == achievementPopUpPage then
			local page = achievementPopUpPage
			local offsetMultiplier = 0.3
		
			if deviceModel == "ipad" then
				offsetMultiplier = 0.5
			end
			page.animationTimer = page.animationTimer - dt
			local bgBox = getItemByName(page.items, "achievementBox")
			if page.animationTimer > ACHIEVEMENT_POPUP_TIME_1 then
				bgBox.y = screenHeight - 190 * (ACHIEVEMENT_POPUP_DURATION - page.animationTimer)
			elseif page.animationTimer > offsetMultiplier and page.animationTimer <= ACHIEVEMENT_POPUP_TIME_1 then
				bgBox.y = screenHeight - 190 * offsetMultiplier
			elseif page.animationTimer > 0 and page.animationTimer <= offsetMultiplier then
				bgBox.y = screenHeight - 190 * (page.animationTimer - 0.1)
			elseif page.animationTimer <= 0 then
				popupPage = nil
			end
		else
			updateMenuPage(popupPage, dt)
			drawGame()
			return
		end
	end
		
	if currentMenuPage ~= pausePage then
		setActiveMenuPage(pausePage)
	end
	
	--%ADDED
	if t_isPCVersion == true then			

		updatePCMouseDragging(dt, time)
		
		updatePCCameraPanning(dt, time)
		
		--%TODO we need the gesture pause page
		updatePCGesturePause(dt, time)
	elseif deviceModel == "roku" then
		updateRokuCameraPan(dt, time)
	end
	--%ADDED END
	
	currentFrame = currentFrame + 1
    
    --check if force end timer is running
	if time ~= nil and lastScoreTime ~= 0 then
		--score has changed, reset the timer
		if oldScore ~= score then
			oldScore = score
			lastScoreTime = 0.01
		else
			lastScoreTime = lastScoreTime + dt
		end
		
		--timer expired
		if lastScoreTime >= 15 then
			levelTimeout = true
		else
			levelTimeout = false
		end
		
		--print("oldscore=" .. oldScore .. " lastscoretime=" .. lastScoreTime .. " leveltimeout=" .. _G.tostring(levelTimeout) .. "\n")
	end
    
	--updateScale()
	updateAnimations(dt)
	
	-- update cursors
	oldCursorWorld.x = cursorWorld.x
	oldCursorWorld.y = cursorWorld.y
	cursorPhysics.x, cursorPhysics.y = screenToPhysicsTransform(cursor.x, cursor.y)
	cursorWorld.x, cursorWorld.y = screenToWorldTransform(cursor.x, cursor.y)
	rightSweep = false
	leftSweep = false
	-- update game timers
	quadClickTimer = quadClickTimer - dt
	rokuClickTimer = rokuClickTimer - dt
	
	-- Handle input
	if deviceModel ~= "roku" then
		if (keyReleased["ESCAPE"] or keyReleased["KEY_BACK"]) and #birdTutorialPopups <= 0 then
			-- _G.res.stopAudio(currentMusic)
			--setPhysicsEnabled(false)
			
			if isPCProfile() then
				goToMenu()
				drawGame()			
			else
				if startedFromEditor then
					returnToEditor()
				else
					goToMenu()
				end
			end
			return
		end
		
		if startedFromEditor ~= true then
			if keyPressed["LEFT"] and cheatsEnabled == true then
				levelRestartedFrom = "keyboard command"
				setGameMode(loadPreviousLevel)
			end
			
			if keyPressed["RIGHT"] and cheatsEnabled == true then
				levelRestartedFrom = "keyboard command"
				setGameMode(loadNextLevel)
			end
			
			if (keyPressed["R"] or keyPressed["F5"]) and #birdTutorialPopups <= 0 then
				levelRestartedFrom = "keyboard command"
				loading = true
				setGameMode(updateLoading)
			end
		else
			if keyPressed["R"] then
				levelRestartedFrom = "keyboard command"
				setEditing(false)
				setPhysicsEnabled(false)
				local name = "temp/" .. levelName .. ".temp.playtest"
				checkDirectories()
			--	loadLevelDelayed = levelFolder .. name
			--	local dateString = "2010-12-"..levelIndex
			--	loadLevelFile(loadLevelDelayed, dateString)
				loadLevelEditor(levelFolder .. name)
				loadLevelInternal(levelFolder .. name)
				setGameMode(updateGame)
				if startedFromEditor ~= true then
					levelSelectionPageNumber = currentThemeNumber
				end
				currentThemeNumber = currentThemeIndex
			end
		end
	end
	
	if levelStartTimer == 0 then
		levelStartTimer = levelStartTimer + 0.01
		sounds.playAudio(sounds.getAudioName("level_start_military"), 1, false)
		_G.res.stopAudio(settings.currentMainMenuSong)
		currentBirdIndex = 0
		fillInNextBird = true
	end
	
	if _G.res.isAudioPlaying(currentMusic) == false and currentMusic then
		sounds.playAudio(currentMusic, 1, true,7)
	end
	
	if #birdTutorialPopups > 0 then
		if deviceModel == "iphone4" and wantedResolution == "FULL" then
			changeResolution = true
			wantedResolution = "HALF"
			return
		end
		if oldScreenWidth ~= screenWidth or oldScreenHeight ~= screenHeight then
			oldScreenWidth = screenWidth
			oldScreenHeight = screenHeight
			prepareMenuPage(tutorials)
			
			--closes the main menu popuppages
			
			
			
		end
		
		setPhysicsEnabled(false)
		
		local t_okButton = getItemByName(tutorials.items, "okButton")
		
		if t_okButton.mouseState ~= nil then
			updateItemMouseOverState(t_okButton, dt)
		end
		
		--local t_tutorialOkHovered = checkSpriteBounds("", "TUTORIAL_OK", tutorials.okButtonX, tutorials.okButtonY, cursor.x, cursor.y)
		local t_tutorialOkHovered = checkSpriteBounds("", "TUTORIAL_OK", t_okButton.x, t_okButton.y, cursor.x, cursor.y)

		if keyReleased["LBUTTON"] then
			
			if t_tutorialOkHovered or deviceModel == "roku" then
				_G.table.remove(birdTutorialPopups, 1)
				if #birdTutorialPopups == 0 then
					if deviceModel == "iphone4" then
						changeResolution = true
						wantedResolution = "FULL"
					end
					setPhysicsEnabled(true)
				else
				--	prepareMenuPage(tutorials)
				end
			end
			
		end
		oldCursor.x = cursor.x
		oldCursor.y = cursor.y
		
		-- Draw game
		drawGame()
		
		-- this isn't probably needed anymore because hidePausePage isn't in updateGame but updateMenu when pause page is closed
		--[[if currentMenuPage == pausePage and elementAnimations["ingamePausePageScroll"].state ~= "HIDDEN" then
			pausePage.offsetX = elementAnimations["ingamePausePageScroll"].percentage / 100 * pauseBGw - pauseBGw
			pausePage.backgroundOverlay.shade = elementAnimations["ingamePausePageScroll"].percentage / 100 * 0.65
			drawMenuPage(pausePage, dt)
		end--]]
		pausePage.backgroundOverlay.shade = 0
		return
	end
	
	if keyPressed["LBUTTON"] and (not t_isPCVersion) and deviceModel ~= "roku" then
		if isLiteVersion and staticBannerOffset and cursor.x < pauseButtonW then 
			if deviceModel ~= "iphone4" and cursor.y > bannerHeight and cursor.y < pauseButtonH + bannerHeight 
			  or deviceModel == "iphone4" and cursor.y > bannerHeight * 2 and cursor.y < pauseButtonH + bannerHeight * 2 then
				if startedFromEditor then
					returnToEditor()
				else
					goToMenu()
					drawGame()
					return
				end
			end
		elseif cursor.x < pauseButtonW and cursor.y < pauseButtonH then
			if startedFromEditor then
				returnToEditor()
			else
				goToMenu()
				drawGame()
				return
			end
