						end
						if episodeTotalScore >= 1735000 then 
							addToAchievementUnlockQueue("Go Green, Get Lucky - Score Addict")
						end
						
						episodeTotalScore, episodeStars, episodeTotalStars = calculateTotalScoreAndStars(levelOrder_packEaster)
