							addToAchievementUnlockQueue("Easter Eggs - Total Destruction")
						end
						if episodeTotalScore >= 1910000 then 
							addToAchievementUnlockQueue("Easter Eggs - Score Addict")
						end
						
						episodeTotalScore, episodeStars, episodeTotalStars = calculateTotalScoreAndStars(levelOrder_packSummer)
