                            end
							if feathers >= 60 then
								addToAchievementUnlockQueue("Feather Collector")
                            end
							if feathers >= 30 then
								addToAchievementUnlockQueue("Feather Picker")		
							end
						end
					else --isLiteVersion
			
						calculateTotalScoreAndStarsLite()
	
						if liteLevelsTable.xmas.stars >= liteLevelsTable.xmas.totalStars then
							addToAchievementUnlockQueue("Holiday Vandal", true)
						end
						
						if liteLevelsTable.halloween.stars >= liteLevelsTable.halloween.totalStars then
							addToAchievementUnlockQueue("Halloween Wrecker", true)
						end
						
						if liteLevelsTable.valentine.stars >= liteLevelsTable.valentine.totalStars then
							addToAchievementUnlockQueue("Famed Lover", true)
						end
						
						if liteLevelsTable.stPatrick.stars >= liteLevelsTable.stPatrick.totalStars then
							addToAchievementUnlockQueue("Hamrocks and Shenanigans", true)
						end
						
						if liteLevelsTable.easter.stars >= liteLevelsTable.easter.totalStars then
							addToAchievementUnlockQueue("Cracking Easter", true)
						end
                        
                        --if liteLevelsTable.summer.stars >= liteLevelsTable.summer.totalStars then
						--	addToAchievementUnlockQueue("Cracking Easter", true)
						--end
                        local ready = true
                        for key,_ in _G.pairs(liteLevelsTable) do
                            if key == "xmas" then key = "holiday" end
                            if not settings[key .. "LiteCompleted"] then ready = false end
                        end
                        if ready then print ("Ready!") else print ("Not ready!") end
                        
						if ready then
							addToAchievementUnlockQueue("Ready For More", true)
						end
					
					end
					sounds.playAudio("level_complete", 1, false, 7)				
					
			
					prepareMenuPage(levelComplete)					
					
					if deviceModel == "iphone" or deviceModel == "ipad" or deviceModel == "iphone4" then
						postTotalHighScores()
					end
				else

					levelEndMenuPage = levelFailed
					levelTimeout = false
					-- flurry fail logging 
					levelRestartedFrom = "failed menu"
					if inExtraWorld == true then
						logFlurryEventWithParam("Golden egg level failed", "Level", goldenEggLevelMapping["Level" .. currentLevelNumberInTheme])
						--print("FlurryEventWithParam: Golden egg level failed, Level, " .. goldenEggLevelMapping["Level" .. currentLevelNumberInTheme] .. "\n")
					else
						levelFailedFlurryParams = {}
						levelFailedFlurryParams["Level"] = currentWorldNumber  .. "-" .. currentLevelNumberInTheme
						levelFailedFlurryParams["Attempts"] = "" .. numberOfAttemptsInLevel
						levelFailedFlurryParams["Birds used"] = "" .. birdsShot
						levelFailedFlurryParams["Birds available"] = "" .. birdsCounter
						
						logFlurryEventWithParams("Level failed", "levelFailedFlurryParams")
					end
					
					levelFailed.items[5].text = "" .. _G.string.format("%d", highscores[levelName].score)
					

					--if levelSelectionPages == levelSelectionPagesBasic or levelSelectionPages == levelSelectionPagesExtra or levelSelectionPages == levelSelectionPagesPack3 or levelSelectionPages == levelSelectionPagesPack4 or levelSelectionPages == levelSelectionPagesPackH then 
						levelFailed.items[6].page = levelSelectionPages
					--else
					--	levelFailed.items[6].page = levelSelectionPages[currentPageNumber]
					--end
										
					getItemByName(levelFailed.items, "buttonEagle").visible = true
					getItemByName(levelFailed.items, "buttonEagleLost").visible = false
					getItemByName(levelFailed.items, "buttonNextLevel").visible = false
					-- each cutscene has it's own button
					for i = 1, #levelFailed.items do
						if _G.string.sub(levelFailed.items[i].name, 1, 14) == "buttonCutscene" then
							levelFailed.items[i].visible = false
						end
					end
				
					print("highscore: " .. highscores[levelName].score .. "\n")
					-- check if mighty eagle is unavailable
					if isEagleDisabled() and settings.mightyEagleEnabled then
						getItemByName(levelFailed.items, "buttonEagle").visible = false
						getItemByName(levelFailed.items, "buttonEagleLost").visible = true
					end
					
					if inExtraWorld == true then
						getItemByName(levelFailed.items, "buttonEagle").visible = false
						getItemByName(levelFailed.items, "buttonEagleLost").visible = false
					end
					local buttonEagleBuy = getItemByName(levelFailed.items, "buttonEagleBuy")
					buttonEagleBuy.visible = false
					if settings.mightyEagleEnabled ~= true or isLiteVersion == true then
						getItemByName(levelFailed.items, "buttonEagle").visible = false
						getItemByName(levelFailed.items, "buttonEagleLost").visible = false
						
						if iapEnabled and (highscores[levelName] == nil or highscores[levelName].score == 0) and not inExtraWorld then
							buttonEagleBuy.visible = true
						end
					else
						if highscores[levelName] ~= nil and highscores[levelName].score > 0 then
							getItemByName(levelFailed.items, "buttonEagle").visible = false
							getItemByName(levelFailed.items, "buttonEagleLost").visible = false
						end
						buttonEagleBuy.visible = false
					end
					
					getItemByName(levelFailed.items, "stars").sprite = "RESULT_STARS_0"
					if highscores[levelName].score > 0 then
						getItemByName(levelFailed.items, "stars").sprite = "RESULT_STARS_1"
						getItemByName(levelFailed.items, "buttonNextLevel").visible = true
						
						if isLiteVersion and (currentLevelNumberInTheme == 3 or currentLevelNumberInTheme == 6) then
							getItemByName(levelFailed.items, "buttonNextLevel").visible = false
						end
						if not usePCSelectionMenus() and currentLevelNumberInTheme == levelSelectionPages.levelsPerPage and inExtraWorld ~= true then
							if levelSelectionPages == levelSelectionPagesBasic then
								getItemByName(levelFailed.items, "buttonCutscene" .. currentWorldNumber).visible = false
								getItemByName(levelFailed.items, "buttonNextLevel").visible = false
							else
								getItemByName(levelFailed.items, "buttonCutscene" .. currentWorldNumber).visible = true
								getItemByName(levelFailed.items, "buttonNextLevel").visible = false
							end
						end

						if usePCSelectionMenus() or isExpBranch and inExtraWorld ~= true then
							if currentLevelNumberInTheme == currentLevelSelectionManager.finalLevelIndex and 
								currentLevelSelectionManager ~= xmasManager and currentLevelSelectionManager ~= halloweenManager 
                                and currentLevelSelectionManager ~= halloween2Manager and currentLevelSelectionManager ~= mooncakeManager then
                                getItemByName(levelFailed.items, "buttonCutscene" .. currentWorldNumber).visible = true
                                getItemByName(levelFailed.items, "buttonNextLevel").visible = false
							elseif currentLevelSelectionManager == xmasManager and currentLevelNumberInTheme == currentLevelSelectionManager.finalLevelIndex then
								getItemByName(levelFailed.items, "buttonCutscene" .. currentWorldNumber).visible = false
								getItemByName(levelFailed.items, "buttonNextLevel").visible = false
							elseif currentLevelSelectionManager == halloweenManager then
								if (currentLevelNumberInTheme % 15) == 0 then
									getItemByName(levelFailed.items, "buttonCutscene" .. currentWorldNumber).visible = true
									getItemByName(levelFailed.items, "buttonNextLevel").visible = false
								end
                            elseif currentLevelSelectionManager == halloween2Manager then
								if currentWorldNumber == 9 and currentLevelNumberInTheme == 15 then
									getItemByName(levelFailed.items, "buttonCutscene9").visible = true
									getItemByName(levelFailed.items, "buttonNextLevel").visible = false
								end
                            elseif currentLevelSelectionManager == mooncakeManager then 
                                if currentWorldNumber == 7 and currentLevelNumberInTheme == 15 then
                                    getItemByName(levelFailed.items, "buttonCutscene6").visible = true
                                    getItemByName(levelFailed.items, "buttonCutscene7").visible = false
									getItemByName(levelFailed.items, "buttonNextLevel").visible = false
                                end
							end
						end
					end
					if highscores[levelName].score >= getStarLimit(levelName).silverScore then
						getItemByName(levelFailed.items, "stars").sprite = "RESULT_STARS_2"
					end
					if highscores[levelName].score >= getStarLimit(levelName).goldScore then
						getItemByName(levelFailed.items, "stars").sprite = "RESULT_STARS_3"
					end
					
					if currentLevelNumberInTheme > 15 and currentWorldNumber > 1 and currentWorldNumber < 5 then
						getItemByName(levelFailed.items, "buttonNextLevel").visible = false
					end
					
					if not usePCSelectionMenus() and currentLevelNumberInTheme > 15 and currentWorldNumber == 7 then
						getItemByName(levelFailed.items, "buttonNextLevel").visible = false
					end
					
					getItemByName(levelFailed.items, "levelNumberSprite").visible = false
					if inExtraWorld == true then
						--hide highscores
						getItemByName(levelFailed.items, "highScoreText").visible = false
						getItemByName(levelFailed.items, "highScoreNumber").visible = false
						getItemByName(levelFailed.items, "stars").visible = false
						--change world number to egg or pumpkin
						getItemByName(levelFailed.items, "levelNumber").text = "^"
						getItemByName(levelFailed.items, "buttonNextLevel").visible = false
						
						if currentWorldNumber == 1 and currentLevelNumberInTheme == 17 then
							getItemByName(levelFailed.items, "levelNumber").text = "¨"
						elseif currentWorldNumber == 2 and currentLevelNumberInTheme == 21 then
							getItemByName(levelFailed.items, "levelNumber").text = "\\"
						elseif currentWorldNumber == 3 and currentLevelNumberInTheme == 23 then
							getItemByName(levelFailed.items, "levelNumber").text = "|"
						elseif currentWorldNumber == 4 and currentLevelNumberInTheme == 24 then
							getItemByName(levelFailed.items, "levelNumber").text = "{"
						elseif currentWorldNumber == 5 and currentLevelNumberInTheme == 35 then
							getItemByName(levelFailed.items, "levelNumber").text = "}"
						elseif currentWorldNumber == 7 and (currentLevelNumberInTheme == 38 or currentLevelNumberInTheme == 39) then
							getItemByName(levelFailed.items, "levelNumber").text = "¤"
                        elseif currentWorldNumber == 9 and currentLevelNumberInTheme == 41 then
							getItemByName(levelFailed.items, "levelNumber").text = "§"
						elseif currentWorldNumber == 14 and currentLevelNumberInTheme == 19 then
							getItemByName(levelFailed.items, "levelNumber").text = "~"
						end
					else
						getItemByName(levelFailed.items, "highScoreText").visible = true
						getItemByName(levelFailed.items, "highScoreNumber").visible = true
						getItemByName(levelFailed.items, "stars").visible = true
                        if usePCSelectionMenus() or isExpBranch then
                            if currentWorldNumber == 7 or currentWorldNumber == 13 or currentWorldNumber == 9 then
                                currentWorldInEpisode = 2
                            elseif currentWorldNumber == 14 then
                                currentWorldInEpisode = 3
                            else
                                currentWorldInEpisode = 1
                            end
                        end
						getItemByName(levelFailed.items, "levelNumber").text = currentWorldInEpisode .. "-" .. currentLevelNumberInTheme
						
						if isLiteVersion then
							if currentLevelNumberInTheme <= 3 then
								getItemByName(levelFailed.items, "levelNumber").text = "¨- " .. currentLevelNumberInTheme
							elseif currentLevelNumberInTheme <= 6 then
								getItemByName(levelFailed.items, "levelNumber").text = "~- " .. currentLevelNumberInTheme - 3
							elseif currentLevelNumberInTheme <= 9 then
								getItemByName(levelFailed.items, "levelNumber").text = "\\- " .. currentLevelNumberInTheme - 6
							elseif currentLevelNumberInTheme <= 12 then
								getItemByName(levelFailed.items, "levelNumber").text = "|- " .. currentLevelNumberInTheme - 9
							elseif currentLevelNumberInTheme <= 15 then
								getItemByName(levelFailed.items, "levelNumber").text = "{- " .. currentLevelNumberInTheme - 12
                            elseif currentLevelNumberInTheme <= 18 then
								getItemByName(levelFailed.items, "levelNumber").text = "}- " .. currentLevelNumberInTheme - 15
							end
							
						end
					end
					if numberOfAttemptsInLevel >= 3 and getItemByName(levelFailed.items, "buttonNextLevel").visible == false
					and getItemByName(levelFailed.items, "buttonCutscene2").visible == false 
					and getItemByName(levelFailed.items, "buttonCutscene3").visible == false 
					and getItemByName(levelFailed.items, "buttonCutscene4").visible == false
					and getItemByName(levelFailed.items, "buttonCutscene5").visible == false
					and getItemByName(levelFailed.items, "buttonCutscene6").visible == false
					and bingIsEnabled == true then
						getItemByName(levelFailed.items, "bingButton").visible = true
						getItemByName(levelFailed.items, "bingSign").visible = true
						local episode = ""
						local liteLevelFirstIndex = 0
						
						if currentWorldNumber == 1 then
							episode = "seasons+greedings"
						elseif currentWorldNumber == 2 then
							episode = "hogs+and+kisses"
						elseif currentWorldNumber == 3 then
							episode = "go+green+get+lucky"
						elseif currentWorldNumber == 4 then
							episode = "easter+eggs"
						elseif currentWorldNumber == 5 then
							episode = "halloween"
                        elseif currentWorldNumber == 6 then
                            episode = "summer"
						else
							episode = "mooncake"
						end
						
						if isLiteVersion then
							if currentLevelNumber <= 3 then
								liteLevelFirstIndex = 0
								episode = "xmas"
							elseif currentLevelNumber <= 6 then
								liteLevelFirstIndex = 3
								episode = "trick+or+treat"
							elseif currentLevelNumber <= 9 then
								liteLevelFirstIndex = 6
								episode = "valentine"
							elseif currentLevelNumber <= 12 then
								liteLevelFirstIndex = 9
								episode = "stpatrick"
							elseif currentLevelNumber <= 15 then
								liteLevelFirstIndex = 12
								episode = "easter"
                            elseif currentLevelNumber <= 18 then
								liteLevelFirstIndex = 15
								episode = "summer"
                            elseif currentLevelNumber <= 21 then
								liteLevelFirstIndex = 18
								episode = "mooncake"
							end
						end
						
						if inExtraWorld then
							getItemByName(levelFailed.items, "bingButton").callParam1 = "angry+birds+seasons+walkthrough+"..episode.."+golden+egg+star"
						else
							if isLiteVersion then
								getItemByName(levelFailed.items, "bingButton").callParam1 = "angry+birds+seasons+free+walkthrough+"..episode.."+level+1-"..currentLevelNumber - liteLevelFirstIndex
							else
								getItemByName(levelFailed.items, "bingButton").callParam1 = "angry+birds+seasons+walkthrough+"..episode.."+level+"..currentLevelNumber
							end
						end
						bingButtonShownParams = {}
						bingButtonShownParams["Level"] = episode.."-"..currentLevelNumber
						logFlurryEventWithParams("Bing button shown", "bingButtonShownParams")
					else
						getItemByName(levelFailed.items, "bingButton").visible = false
						getItemByName(levelFailed.items, "bingSign").visible = false
					end
					prepareMenuPage(levelFailed)
				end

				_G.res.stopAudio(currentMusic)
				--stop looping rolling sounds
				_G.res.stopAudio("wood_rolling")
				_G.res.stopAudio("rock_rolling")
				_G.res.stopAudio("light_rolling")	
				_G.res.stopAudio("snow_rolling")				
				
				setGameMode(updateMenu)
				setActiveMenuPage(levelEndMenuPage)
				changeResolution = true
				wantedResolution = "HALF"
				
				setPhysicsEnabled(false)
				-- drawGame()
				if adsEnabled == true then
	
					if videoAdRequested ~= true and videoReady ~= true and time - lastVideoAdTime > 300 then
						local interstitialSlot = getInterstitialAdSlot()
						requestAndShowVideo(interstitialSlot)
						lastVideoAdTime = time
					else
						showAd("banner_levelend")
					end
					
				end
			
				return
			end
		end
	else
		if checkLevelComplete() or quadClick == true or rokuCheat then
			
            inGameEagleButtonScale = 1
            inGameEagleButtonVisible = false
			
			rubberBandPos.x = levelStartPosition.x
			rubberBandPos.y = levelStartPosition.y
			rubberBandSpeed = 0
			
			allowResetToBirdCamera = false
			showTapIcon = false
			showTapTimer = 0
			levelCompleted = true
			--setPhysicsEnabled(false)			
			-- count the remaining birds that have not been fired
			birdsLeftCounter = currentBirdIndex

			if currentBirdName == nil or objects.world[currentBirdName].shot == true then
				birdsLeftCounter = birdsLeftCounter + 1
			end

			-- if some birds are left go to launch camera and show the scores
			if getNextBird(birdsLeftCounter) ~= nil then
				birdBuffTimer = 2.5			
				if cameraFunction ~= launchCamera then
					birdBuffTimer = 3.5
					castleCameraTimer = 1.0
					cameraFunction = launchCamera
					animationScreen.x = screen.x
					animationScreen.y = screen.y
					animationWorldScale = worldScale					
				end
			end
			
			sounds.playAudio(sounds.getAudioName("level_clear_military"), 1, false)
			levelCompleteTimer = 1.0
			if eagleBaitLaunched then
				levelCompleteTimer = 2.0
			end
			
		end
		if checkLevelFailed() then 
			-- wait for 1.5 seconds until declare level as failed
			levelFailedTimer = levelFailedTimer + dt
			if levelFailedTimer > 1.5 then
				--setPhysicsEnabled(false)
				levelCompleteTimer = 0.5
				sounds.playAudio(sounds.getAudioName("level_failed_piglets"), 1, false)
			end
		end
	end
	
	-- update timers
	gameTimer = gameTimer + dt
	
	-- update tap timer
	if tapStarted then
		tapTimer = tapTimer + dt
				
		if tapTimer > 0.25 then
			if tapCount == 1 and showTapIcon then
				-- todo: put these to own function, this code is used in three places
				rightSweep = true
				showTapIcon = false
				showTapTimer = 0
				cameraFunction = doItAllCamera
				sweepSpeed = objects.castleCameraData[deviceModel].px - objects.birdCameraData[deviceModel].px
				cameraAnimationSliderTarget = 0
				if cameraAnimationSlider >= 1 then
					cameraAnimationSlider = 1
				end
				allowResetToBirdCamera = false
				cameraTargetObject = nil
				flyingBird = nil
			end
			-- reset camera scale
			if tapCount == 2 then
				if cameraAnimationSliderTarget == 0 then
					currentZoomedScale = objects.birdCameraData[deviceModel].sx
				else
					currentZoomedScale = objects.castleCameraData[deviceModel].sx
				end
			end
		
			tapTimer = 0
			tapCount = 0
			tapStarted = false
		end
	end

	-- Handle keypress
	if keyPressed["LBUTTON"] and not levelCompleted then
		draggingStartPosPhysics.x = cursorPhysics.x
		draggingStartPosPhysics.y = cursorPhysics.y
		
		draggingStartPosScreen.x = cursor.x
		draggingStartPosScreen.y = cursor.y

		oldCursor.x = cursor.x
		oldCursor.y = cursor.y

		if tapStarted == false then
			tapPosition.x = cursor.x
			tapPosition.y = cursor.y
			tapStarted = true
			tapTimer = 0
		end
		
		-- try it out - just for fun
		--makeClickExplosion(cursorPhysics.x, cursorPhysics.y, 20000, 10, 200, 5, sounds.getAudioName("special_explosion"))

		-- if gamestate is bird flying use special action
		if flyingBird ~= nil and birdSpecialtyAvailable then
			if t_isPCVersion == true then
				--%ADDED
				--if the player has pressed the bird specialty but the finger is still in touch, we must wait until the player removes the finger
				--in order to starting dragging the next bird on the slingshot
				if g_mouseOrTouchStates.isUsingMouse == false and touchcount > 0 then
					g_birdDragOnTouchAttributes.disabledForBirdSpecialty = true
				end
				--%ADDED END
			end
			
			birdSpecialtyAvailable = false
			local bDef = getObjectDefinition(flyingBird.name)
			birdSpecialty = bDef.specialty
			if birdSpecialty == "BOOST" then
				local force = boostForce * physicsScale * flyingBird.mass
				local x, y = vNormalize(flyingBird.xVel, flyingBird.yVel)
				applyImpulse( flyingBird.name,
							-x * force,
							-y * force,
							flyingBird.x,
							flyingBird.y )
				addParticles(flyingBird.name, blockTable.blocks[flyingBird.definition].particles, 10, false, false)
				sounds.playAudio(sounds.getAudioName(blockTable.blocks[flyingBird.definition].specialSound), 1, false)
				objects.world[flyingBird.name].sprite = "BIRD_YELLOW_SPECIAL"
				setSprite(flyingBird.name, objects.world[flyingBird.name].sprite)
				local lx, ly = physicsToWorldTransform(flyingBird.x, flyingBird.y)
				addPuffToTrajectory(1, lx, ly)
			end
			if birdSpecialty == "BOMB" then
				--birdSpecialtyAvailable = true
				makeExplosion(flyingBird, bDef, sounds.getAudioName(blockTable.blocks[flyingBird.definition].specialSound))
				
				removeBird(flyingBird)
			end
			if birdSpecialty == "SOUND" then
				sounds.playAudio(sounds.getAudioName(blockTable.blocks[flyingBird.definition].specialSound), 1, false)
			end
			if birdSpecialty == "CLUSTER_BOMB" then
				
				local lx, ly = physicsToWorldTransform(flyingBird.x, flyingBird.y)
				addPuffToTrajectory(1, lx, ly)
				
				local x, y = vNormalize(flyingBird.yVel, -flyingBird.xVel)
				local newName = flyingBird.name .. "a"
				createCircle(newName, flyingBird.sprite, flyingBird.x - x, flyingBird.y - y, flyingBird.radius, flyingBird.density, flyingBird.friction, flyingBird.restitution, flyingBird.controllable, flyingBird.z_order)
				objects.world[newName].definition = flyingBird.definition
				objects.world[newName].controllable = flyingBird.controllable
				objects.world[newName].strength = flyingBird.strength
				objects.world[newName].defence = flyingBird.defence
				objects.world[newName].material = flyingBird.material
				objects.world[newName].levelGoal = flyingBird.levelGoal
				objects.world[newName].damageFactors = flyingBird.damageFactors
				objects.world[newName].spritePivotX = flyingBird.spritePivotX
				objects.world[newName].spritePivotY = flyingBird.spritePivotY
				objects.world[newName].damageSprite = flyingBird.damageSprite
				objects.world[newName].useLegacyCollisionPath = flyingBird.useLegacyCollisionPath
				objects.world[newName].shot = true
				objects.world[newName].sleeping = false
				objects.world[newName].hasCollided = false
				objects.world[newName].parentName = flyingBird.name
				objects.world[newName].xVel = flyingBird.xVel - x*7
				objects.world[newName].yVel = flyingBird.yVel - y*7
				setSprite(newName, flyingBird.damageSprite)
				setRotation(newName, flyingBird.angle)
				setVelocity(newName, flyingBird.xVel - x*7, flyingBird.yVel - y*7)
				--_G.table.insert(extraObjects, newName)
