function animateFutureEagle(futureEagle, dt)

	--keep the futureEagle "awake" even when not moving to avoid it sleeping when it should collide
	setVelocity(futureEagle.name,1, 1)


	if futureEagle.delay then
		futureEagle.delay  = futureEagle.delay - dt
		if futureEagle.delay < 0 then
			futureEagle.delay = nil
		end
		return
	end

	local speed = futureEagle.speed
	--[[if not futureEaglePath then
		return
	end
	
	local index1 = _G.math.floor(futureEagle.state)
	local frac1 = futureEagle.state - index1
	
	if(index1 > (#futureEaglePath - 3)) then
		removeBird(futureEagle)
		eagleTimer = 0
		return
	end
	
	local x1 = getPointFromCatmullRomSpline(futureEaglePath[index1].x, futureEaglePath[index1+1].x, futureEaglePath[index1+2].x, futureEaglePath[index1+3].x,frac1)
	local y1 = getPointFromCatmullRomSpline(futureEaglePath[index1].y, futureEaglePath[index1+1].y, futureEaglePath[index1+2].y, futureEaglePath[index1+3].y,frac1)
	
	local angle = getAngle(futureEagle.name)
	local delta =  _G.math.atan2((y1- futureEagle.radius*0.5)-futureEagle.y, x1 - futureEagle.x) - angle
	
	
	local newAngle = angle + delta
	newAngle = _G.math.max(_G.math.min(_G.math.pi*0.5,newAngle), -_G.math.pi*0.5)
	if  newAngle > 0.15 then
		--speed=speed*0.7
		--setRotation(futureEagle.name, -_G.math.pi*0.1)
	else
		setRotation(futureEagle.name, newAngle)
	end
	--print("angle: " ..angle .. "\n")
	--print("futureEagle angle: " .. _G.math.atan2(x1 - futureEagle.x, y1-futureEagle.y) .. "\n")
	setPosition(futureEagle.name, x1, y1 - futureEagle.radius*0.5)
	
	
	--seems that if velocity ==0, box2D might think futureEagle is "sleeping" and thus will not collide with the blocks
	setVelocity(futureEagle.name,1, 1)
	
	futureEagle.state = futureEagle.state +dt * speed]]
	
	
	local groundLimit = 0
	
	local baitx, baity = futureEagle.baitX, futureEagle.baitY
	local jumpDist = 5 * _G.math.abs(baity/3)
	local x,y = 0,0
	local newAngle = nil
	cameraShake = 2
	local angle = getAngle(futureEagle.name)
	local futureEagleShake = 0
	
	
	--particles
	if (not futureEagleParticleTimer or futureEagleParticleTimer < 0)  and (futureEagle.y + futureEagle.radius) >= groundLimit then
		futureEagleParticleTimer = 0.02
		local x, y = physicsToWorldTransform(futureEagle.x, futureEagle.y)
		local w,h= physicsToWorldTransform(futureEagle.radius, futureEagle.radius)
		newParticles(getObjectDefinition(futureEagle.name).particlesTrail, particleTable.particles[getObjectDefinition(futureEagle.name).particlesTrail].amount, x, y + h*0.5, w*0.1, h*0.1, getAngle(futureEagle.name), false, false)
		--addParticles(futureEagle.name, , , false, false)
	end
	if futureEagleParticleTimer then
		futureEagleParticleTimer = futureEagleParticleTimer -dt
	end
	--movement
	--print("baity: " .. baity .. " groundLimit:" .. groundLimit .. " futureEagleradius: " .. futureEagle.radius .. "\n") 
	if jumpDist >= baitx-futureEagle.x and _G.math.abs(baity) > (_G.math.abs(groundLimit) +futureEagle.radius) then
		_G.res.stopAudio("futureEagle_runloop")
		futureEagle.runloopPlaying  = false
		--[[if baitx-futureEagle.x >0 then
			y = tweenEaseCubicOut(jumpDist - (baitx - futureEagle.x), groundLimit, baity - groundLimit, jumpDist)
		else
			y = tweenEaseCubicIn(jumpDist - (futureEagle.x-baitx), groundLimit, baity - groundLimit, jumpDist)
		end]]
		
		if not futureEagle.jumped then
			 sounds.playAudio("futureEagle_jump",1,false)
			 futureEagle.jumped = true
		end
		local t = 1
		cameraShake = 0
		--after first bounce
		if baitx-futureEagle.x <= -jumpDist   then
			cameraShake = 2 * _G.math.abs(baity/2)
			futureEagle.earthShake = true
			-- when futureEagle hits the ground for the first time, bump pigs into the air
			if not futureEagle.pigsBumped  then
				
				for k, v in _G.pairs(objects.world) do
					if v.strength ~= nil and v.levelGoal then
						local force = -v.mass * 10
						applyImpulse( v.name,
									0,
									force,
									v.x,
									v.y )
					end
				end
				futureEagle.pigsBumped = true
				sounds.playAudio("futureEagle_landing",1,false)
			end
			 
			
			
			t = _G.math.max( 1 - _G.math.abs(baitx-futureEagle.x + jumpDist)/jumpDist,0)
			-- on second and alter bounces change the futureEagle angle
			if t > 0 then
				--interpolate from first bounce angle to second
				newAngle = _G.math.pi*0.15 
			end
		else
			newAngle = -_G.math.pi*0.15
		end
		
		y = groundLimit + (futureEagle.baitY - groundLimit) *_G.math.abs(_G.math.sin((_G.math.pi*0.5) + ((baitx-futureEagle.x)/jumpDist)*_G.math.pi*0.5))*t
		
	else
		futureEagleShake = _G.math.cos(baitx-futureEagle.x)*0.1
		y =groundLimit
		if not futureEagle.runloopPlaying then
			sounds.playAudio("futureEagle_runloop", 1, true)
			futureEagle.runloopPlaying  = true
		end
	end
	

	cameraTargetObject = futureEagle
	cameraFunction = futureEagleCamera
	
	x = futureEagle.x + dt*speed
	
	
	
	
	local delta =  _G.math.atan2((y- futureEagle.radius*0.5)-futureEagle.lastY, x - futureEagle.lastX) - angle
	
	
	newAngle = newAngle or _G.math.max(_G.math.min(angle + delta,0.1), -0.1)
	newAngle = newAngle + futureEagleShake
	--newAngle = _G.math.max(_G.math.min(_G.math.pi*0.5,newAngle), -_G.math.pi*0.5)
	setRotation(futureEagle.name, newAngle)
	
	futureEagle.x, futureEagle.y = x,y
	
	if(futureEagle.x > ( levelLimitMaxX-5 )) then
		-- if futureEagle is removed but it is in air and has not yet landed, shake the camera to simulate collision with the ground
		if not futureEagle.earthShake and  (futureEagle.y ) <= groundLimit  then
			futureEagle.earthShake = true
			cameraShake = 2 * _G.math.abs(baity/2)
		end
		cameraTargetObject = nil
		if futureEagle.runloopPlaying == true then
			_G.res.stopAudio("futureEagle_runloop")
			futureEagle.runloopPlaying  = false
		end
		removeBird(futureEagle)
		eagleTimer = 2
		
		return
	end
	
	setPosition(futureEagle.name, futureEagle.x, futureEagle.y - futureEagle.radius*0.5)
	
	
	
	
	--seems that if velocity ==0, box2D might think futureEagle is "sleeping" and thus will not collide with the blocks
	
	
	--track the last position to calculate angle (if we just take the pos from last frame, could introduce bug)
	if not futureEagleLastPosTimer or futureEagleLastPosTimer < 0  then
		futureEagleLastPosTimer = 0.02
		futureEagle.lastX = futureEagle.x
		futureEagle.lastY = futureEagle.y
	end
	futureEagleLastPosTimer = futureEagleLastPosTimer - dt
end

function getPointFromCatmullRomSpline( p0,p1,p2,p3, t)
	return ((2*p1) + ((-p0+p2)*t) + ((2*p0 -5*p1 + 4*p2 -p3)*_G.math.pow(t,2)) + ((-p0 + 3*p1 - 3*p2 + p3)*_G.math.pow(t,3)))*0.5;
end

function spawnFutureEagle(baitX,baitY, delay)
	if futureEagleSpawned then
		return
	end
	levelCompleteTimer = 0
	levelFailedTimer = -200
	eagleX, eagleY = nil, nil
	futureEagleSpawned = true
	x =  levelLimitMinX + 1
	y =  0
	
	
	--createFutureEaglePath( x, levelLimitMaxX + 5 ,  50,baitX,baitY)
	--print("createMightyEagle: " .. meX .. ", " .. meY)
	
	--[[for k,v in _G.pairs(futureEaglePath) do
		print("point: " .. v.x  .. " , " .. v.y .. "\n")
	end]]
	sounds.playAudio("futureEagle_thunder_closing",1,false)
	local newName = "futureEagle_a"
	local blockDef = blockTable.blocks["FutureEagle"]
	--print("eagleX: " .. levelLimitMinX .. ", eagleY: " .. meY - (meX - levelLimitMinX) / 2  .. "\n")
	--createCircle(newName, blockDef.sprite, levelLimitMinX + 1, y - (x - levelLimitMinX+1) / 2, blockDef.radius, blockDef.density, blockDef.friction, blockDef.restitution, true, blockDef.z_order)
	createCircle(newName, blockDef.sprite, x, y, blockDef.radius, blockDef.density, blockDef.friction, blockDef.restitution, true, blockDef.z_order)
	objects.world[newName].speed =80
	objects.world[newName].state = 1

	objects.world[newName].baitX = baitX
	objects.world[newName].baitY = baitY
	
	objects.world[newName].lastX = x
	objects.world[newName].lastY = y
	
	objects.world[newName].delay = delay or nil
	
	objects.world[newName].definition = "FutureEagle"
	objects.world[newName].controllable = blockDef.controllable
	objects.world[newName].strength = blockDef.strength
	objects.world[newName].defence = blockDef.defence
	objects.world[newName].material = blockDef.material
	objects.world[newName].damageFactors = blockDef.damageFactors
	objects.world[newName].useLegacyCollisionPath = blockDef.useLegacyCollisionPath
	objects.world[newName].levelGoal = false
	local xp, yp = _G.res.getSpritePivot("INGAME_BIRDS_2",blockDef.sprite)
	objects.world[newName].spritePivotX = xp
	objects.world[newName].spritePivotY = yp
	objects.world[newName].damageSprite = blockDef.sprite
	objects.world[newName].xVel = 0
	objects.world[newName].yVel = 0
	setSprite(newName, objects.world[newName].damageSprite)
	setRotation(newName, 0)
	objects.world[newName].animTimer = 9999
	objects.world[newName].jumpTimer = 9999
	objects.world[newName].animOn = false
	objects.world[newName].isMightyEagle = false
	objects.world[newName].shot = true
	objects.world[newName].particleTimer = 0 
	objects.world[newName].particleTimerLimit = 0.025
	objects.world[newName].recordTrajectory = false
	birds[newName] = objects.world[newName]
	--sounds.playAudio(sounds.getAudioName(blockTable.blocks[objects.world[newName].definition].specialSound), 1, false)
	birdsCounter = birdsCounter + 1
	--currentZoomedScale = objects.castleCameraData[deviceModel].sx
	--cameraAnimationSliderTarget = 1
	flyingBird = objects.world[newName]
	setMaxTranslation(5)
	_G.particles.setHardLimit(250)
	_G.particles.setSoftLimit(0, 0.2)
	
end

