-- adMob stuff starts

function showAd(nextSlot)
	if checkAdsEnabled() then
		print("Trying to show ad\n")
		if isShowingAd == true then
			print("Still showing previous ad, reseting ad timer\n")
			lastAdTime = time
		elseif adRequested == true then 
			scoreAdOffsetY = 0 
			print("Still requesting ad, doing nothing\n")
		elseif adReady == true then
			adReady = false
			isShowingAd = true
			isHidingAd = false
			lastAdTime = time
			adShowingStartedTime = time
			showAdvertisement()
			scoreAdOffsetY = 0 
			print("showing ad\n")
		elseif adRequested ~= true then
			print("No ad ready and not requesting ad, requesting now to slot " .. nextSlot .."\n")
			requestAd(nextSlot)
			adRequested = true
			scoreAdOffsetY = 0 
		end
	end
end

function getInterstitialAdSlot()

	if currentGameMode == updateGame then
		return "interstitial_levelstart"
	elseif currentGameMode == updateMenu and currentMenuPage == levelComplete then
		return "interstitial_levelend" -- should be different IDs for failed and complete ?
	elseif currentGameMode == updateMenu and currentMenuPage == levelFailed then
		return "interstitial_levelend" -- should be different IDs for failed and complete ?
	elseif currentGameMode == updateMenu then 
		return "interstitial_levelselect"
	else
		print("No specific interstitial ad slot found for current game state. Returning default. \n")
		return "interstitial_levelstart"
	end

end


function requestAdSuccesful()
	if checkAdsEnabled() then
		print("requestAdSuccesful\n")
		adReady = true
		adRequested = false
	end
end

function requestAdFailed()
	if checkAdsEnabled() then
		print("requestAdFailed\n")
		adRequested = false
	end
end

function hideAd()
	if checkAdsEnabled() then
		print("Trying to hide ad\n")
		if isShowingAd == true and isHidingAd ~= true then
			hideAdvertisement()
			isHidingAd = true
			print("hideAd\n")
		end
	end
end

function startAdTimer()
	if checkAdsEnabled() then
		isShowingAd = true
		lastAdTime = time
		print("Starting Ad Timer, starting to show ad\n")
	end
end

function showVideoAd()
	if checkAdsEnabled() then
		print("Checking if it's time for video ad\n")
		if videoReady == true and isShowingAd ~= true then
			print("Show video\n")
			showVideoAdvertisement()
			lastVideoAdTime = time
			videoAdRequested = false
		end
	end
end

function fullScreenAdDismissed()
	print("Fullscreen ad dismissed.\n")
	prepareMenusAfterAd = true
	scoreAdOffsetY = 0 
	if currentGameMode == updateGame and _G.res.isAudioPlaying(settings.currentMainMenuSong) == true then
		_G.res.stopAudio(settings.currentMainMenuSong)
	end
end

function fullScreenVideoDismissed()
	fullScreenAdDismissed()
	if currentGameMode == updateGame or (currentGameMode == updateMenu and currentMenuPage == pausePage) then
		setGameMode(hidePauseMenu)
	end
end

function checkAdsEnabled()
    return ((isLiteVersion == true and (deviceModel == "iphone" or deviceModel == "iphone4" or deviceModel == "ipad")) or deviceModel == "android") and not settings.isPremium
end


