function getIndexInTable(a_table, a_item)
	local t_index = 0
	for k,v in _G.pairs(a_table) do
		t_index = t_index + 1
		if v == a_item then
			return (t_index)
		end
	end
	
	return 0
end

function normalizeVector(x,y)
	local t_length = distance(0,0, x,y)
	return {x=x/t_length, y = y/t_length}
end

function dotProduct(x1,y1,x2,y2)
	return x1*x2 + y1*y2
end

