function checkEpisodeCompleted(worldNumber, isThreeStars)
	local l_worldCompleted = false
	local l_isCompletedFirstTime = false
	local l_isCompletedThreeStars = false
	local l_levelEndMenuPage = {}
	local l_levelEndMenuPage3Stars = {}
	local l_buttonCutscene = "buttonCutscene"..worldNumber
	local l_achievement = ""
	local l_goldenEggAchieved = ""
	local l_goldenEggAchievedSprite = ""
    
    if worldNumber == 6 or worldNumber == 8 then
        l_buttonCutscene = "buttonNextLevel"
    elseif worldNumber == 7 then
        l_buttonCutscene = "buttonCutscene6"
    end

	if (currentLevelNumberInTheme == currentLevelSelectionManager.finalLevelIndex 
        or (usePCSelectionMenus() or isExpBranch) and currentLevelNumberInTheme == currentLevelSelectionManager.pages[currentLevelSelectionManager.currentPage].levelAmount)
        and currentLevelSelectionManager ~= xmasManager and currentLevelSelectionManager ~= summerManager then
		l_worldCompleted = true
    elseif isExpBranch and (currentLevelSelectionManager == xmasManager or currentLevelSelectionManager == summerManager)then
        l_worldCompleted = true
        local orderTable = currentLevelSelectionManager == xmasManager and levelOrder_packBasic or levelOrder_packSummer
        for k = 1, #orderTable do
            for i = 1, #orderTable[k] do
                if highscores[orderTable[k][i]] == nil 
                    or highscores[orderTable[k][i]] and highscores[orderTable[k][i]].score == 0 then
                    l_worldCompleted = false
                end
            end
        end
	end
	
	if worldNumber == 1 then
		l_achievement = "Holiday Spirit"
			
		l_goldenEggAchieved = "Level17"
		l_goldenEggAchievedSprite = "present"
		
		l_levelEndMenuPage = gameFinished
		l_levelEndMenuPage3Stars = gameFinishedThreeStars
		if l_worldCompleted then
			if settings.gameCompleted ~= true then						
				l_isCompletedFirstTime = true
				settings.gameCompleted = true
			end
		end
		
		if isThreeStars and not settings.threeStars then
			l_isCompletedThreeStars = true
			settings.threeStars = true
		end
	elseif worldNumber == 2 then
		l_achievement = "All's Fair in Love and War"
			
		l_goldenEggAchieved = "Level21"
		l_goldenEggAchievedSprite = "heart"
		
