function unlockNextLevel(worldNumber)
	if worldNumber == 1 then
		if settings.lastOpenLevel <= currentLevelNumber then
			settings.lastOpenLevel = currentLevelNumber + 1
			saveLuaFileWrapper("settings.lua", "settings", true)

		end
	end
	
	if worldNumber == 2 then
		if settings.lastOpenLevelLPV <= currentLevelNumber and currentLevelNumber <= 15 then
			settings.lastOpenLevelLPV = currentLevelNumber + 1
			saveLuaFileWrapper("settings.lua", "settings", true)
		end
	end
	
	if worldNumber == 3 then
		if settings.lastOpenLevelLPSP <= currentLevelNumber and currentLevelNumber <= 15 then
			settings.lastOpenLevelLPSP = currentLevelNumber + 1
			saveLuaFileWrapper("settings.lua", "settings", true)
		end
	end
	
	if worldNumber == 4 then
		if settings.lastOpenLevelLPEaster <= currentLevelNumber and currentLevelNumber <= 15 then
			settings.lastOpenLevelLPEaster = currentLevelNumber + 1
			saveLuaFileWrapper("settings.lua", "settings", true)
		end
	end
	
	if worldNumber == 5 then
		if settings.lastOpenLevelLPSummer <= currentLevelNumber and currentLevelNumber <= 30 then
			settings.lastOpenLevelLPSummer = currentLevelNumber + 1
			saveLuaFileWrapper("settings.lua", "settings", true)
		end
	end

	if worldNumber == 6 or worldNumber == 7 then
		if usePCSelectionMenus() or isExpBranch and settings.lastOpenLevelLPMooncake < mooncakeManager:getLevelAmount() then
            if worldNumber == 7 then
				if currentLevelNumber <= 15 then
					settings.lastOpenLevelLPMooncake = _G.math.max(settings.lastOpenLevelLPMooncake, currentLevelNumber + 16)
				end
            else
                settings.lastOpenLevelLPMooncake = _G.math.max(settings.lastOpenLevelLPMooncake, currentLevelNumber + 1)
            end
            saveLuaFileWrapper("settings.lua", "settings", true)
        elseif settings.lastOpenLevelLPMooncake <= currentLevelNumber and currentLevelNumber <= 30 then
			settings.lastOpenLevelLPMooncake = currentLevelNumber + 1
            saveLuaFileWrapper("settings.lua", "settings", true)
		end
	end
    
    if worldNumber == 8 or worldNumber == 9 then
        if usePCSelectionMenus() or isExpBranch and settings.lastOpenLevelLPH2 < halloween2Manager:getLevelAmount() then
            if worldNumber == 9 then
                settings.lastOpenLevelLPH2 = _G.math.max(settings.lastOpenLevelLPH2, currentLevelNumber + 16)
            else
                settings.lastOpenLevelLPH2 = _G.math.max(settings.lastOpenLevelLPH2, currentLevelNumber + 1)
            end
        end
        saveLuaFileWrapper("settings.lua", "settings", true)
    end
	
	if worldNumber >= 12 and worldNumber <= 14 then
		if usePCSelectionMenus() or isExpBranch and settings.lastOpenLevelLPH < halloweenManager:getLevelAmount() then
            if worldNumber == 13 then
                settings.lastOpenLevelLPH = _G.math.max(settings.lastOpenLevelLPH, currentLevelNumber + 16)
            elseif worldNumber == 14 then
                settings.lastOpenLevelLPH = _G.math.max(settings.lastOpenLevelLPH, currentLevelNumber + 31)
            else
                settings.lastOpenLevelLPH = _G.math.max(settings.lastOpenLevelLPH, currentLevelNumber + 1)
            end
            saveLuaFileWrapper("settings.lua", "settings", true)
        elseif settings.lastOpenLevelLPH <= currentLevelNumber then
			settings.lastOpenLevelLPH = currentLevelNumber + 1
            saveLuaFileWrapper("settings.lua", "settings", true)
		end
	end
end

function getEpisodeFeathers(levelOrder)
	local total = 0
	local maxFeathers = 0
	
	for i = 1, #levelOrder do
		local totalPack, maxFeathersPack = getFeathersInPack(levelOrder[i])
		total = total + totalPack
		maxFeathers = maxFeathers + maxFeathersPack
	end
	
	return total, maxFeathers
end	

function getFeathersInPack(pack)
	local total = 0
	local maxFeathers = 0
	
	for i = 1, #pack do
		maxFeathers = maxFeathers + 1
		if highscores[pack[i]] and highscores[pack[i]].eagleScore == 100 then
			total = total + 1
		end
	end
	
	return total, maxFeathers
end

function getEagleScore(levelName)
	-- Check that this is actually availabe
	if(levelName == nil or highscores[levelName] == nil or highscores[levelName].eagleScore == nil) then
		return -1;
	end
	
	local eagleScore = 0

	if(highscores[levelName].eagleScore ~= nil) then
		eagleScore = highscores[levelName].eagleScore
	end		
	print("---------- Returning score : "..eagleScore.."\n")
	return eagleScore
end

function calculateFeathers(levelTable)
	local totalFeathers = 0
	local gainedFeathers = 0
	
	for k = 1, #levelTable do
		local pageTable = levelTable[k]
		totalFeathers = totalFeathers + #pageTable
		for i = 1, #pageTable do
			--local eagleScore = highscores[pageTable[i]].eagleScore or  highscores[pageTable[i]].trialEagleScore
			if highscores[pageTable[i]] ~= nil and getEagleScore(pageTable[i]) >= 100 then
				gainedFeathers = gainedFeathers + 1
			end
		end
	end
	
	return gainedFeathers, totalFeathers
end

function is3G()
    return getHardwareModel() == "iPhone1,2" or getHardwareModel() == "iPhone2,1"
end
